window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0162", [{"word":"scholarly","ipa_uk":"/ˈskɒləli/","ipa_us":"/ˈskɑːlərli/","definition_zh":"学术的；学者式的；博学的；论证严谨的","definition_en":"relating to serious academic study, or showing the careful reading and method of a trained researcher","core_image":"一张堆满批注本与索引卡的书桌，台灯下有人逐页核对脚注与异文","scene":"编者花了许多年比对残卷，终于交出一部可供同行复核的定本。The scholarly edition lists every variant reading from the earliest manuscripts.","sceneCN":"编者多年比对残卷，交出一部被同行反复引用的定本；句中的 scholarly 指「校勘精审、可供复核的」（第 7 个义项：带校勘与异文记录的权威版本）。图中可辨识物件：摊开的古卷、铅笔标注、索引卡、台灯。","pos":[{"tag":"adj.","zh":"学术的；学者式的；博学的；严谨细致的"}],"collocations":[{"phrase":"scholarly work","zh":"学术著作"},{"phrase":"scholarly research","zh":"学术研究"},{"phrase":"scholarly journal","zh":"学术期刊"},{"phrase":"scholarly consensus","zh":"学界共识"},{"phrase":"scholarly edition","zh":"校勘本；学术版本"},{"phrase":"scholarly attention","zh":"学界的关注"}],"forms":[{"label":"比较级","form":"more scholarly"},{"label":"最高级","form":"most scholarly"}],"derivatives":[{"word":"scholar","pos":"n.","zh":"学者；奖学金获得者"},{"word":"scholarship","pos":"n.","zh":"学术；奖学金"},{"word":"scholastic","pos":"adj.","zh":"经院的；学校的"},{"word":"scholastically","pos":"adv.","zh":"经院式地"},{"word":"school","pos":"n.","zh":"学校"}],"senses":[{"no":"01","title":"Work produced by trained researchers","titleCN":"受过高深训练的研究成果","definition":"relating to serious academic study and to work produced by trained researchers","definitionCN":"与严肃的学术研究相关，指由受过高深训练的研究者完成的成果","example":"The journal publishes scholarly articles on ancient languages.","exampleCN":"该期刊发表关于古代语言的学术论文。","why":"scholar first named a learned person, and the suffix -ly turned that noun into an adjective meaning 'of or like a scholar', so the word began by describing what belongs to such a person's work.","whyCN":"scholar 最初指有学问的人，形容词后缀把这个名词变成「属于学者、像学者那样的」形容词，因此这个词最早描述的是学者工作的属性。"},{"no":"02","title":"Devoted to learning","titleCN":"好学深思的（人）","definition":"spending much time on study and showing the habits of a careful learner","definitionCN":"把大量时间用于研读，并表现出细心学习者的习惯","example":"Her scholarly uncle keeps a card index of every book he reads.","exampleCN":"她那位好学的叔父把读过的每本书都记在卡片索引里。","why":"the adjective moved from the work to the worker, so a person can be called scholarly when study has shaped the way that person lives.","whyCN":"形容词从「工作」转向「人」，当研读塑造了一个人的生活方式，这个人就可以被称为好学深思的。"},{"no":"03","title":"Rigorous and well sourced","titleCN":"论证严谨、有据可查的","definition":"careful, exact and supported by sources rather than by guesswork","definitionCN":"细致准确，靠资料来源支撑而非凭猜测","example":"The report is scholarly in tone and cites a source for every claim.","exampleCN":"这份报告语气严谨，每一处主张都注明了出处。","why":"because a scholar must show where a claim comes from, the adjective took on the sense of method: exact, documented and open to checking.","whyCN":"因为学者必须交代主张的来源，这个形容词便带上了方法义：准确、有据、可被复核。"},{"no":"04","title":"Dense with references","titleCN":"行文博雅、引证繁富的","definition":"written with many references and allusions, rewarding readers who know the literature","definitionCN":"行文多引证与典故，对熟悉文献的读者更有收获","example":"His scholarly prose rewards readers who already know the literature.","exampleCN":"他那种引证繁富的文风，对已经熟悉文献的读者才显出好处。","why":"the style sense is the method sense seen from the reader's side: a text dense with sources reads as learned and unhurried.","whyCN":"文风义是方法义在读者一侧的投影：出处密集的文字读来博学而从容。"},{"no":"05","title":"Pursued for knowledge alone","titleCN":"纯学术的、不为实用的","definition":"studied for understanding rather than for immediate practical use","definitionCN":"为求理解而研究，而非为了眼前的实际用途","example":"They treated the question as a scholarly puzzle rather than a business problem.","exampleCN":"他们把这个题目当成纯学术的谜题，而不是商业问题。","why":"the Greek source of the word meant leisure, and study done in leisure was valued precisely because it was not tied to immediate gain.","whyCN":"这个词的希腊语源头意为闲暇，而在闲暇中所做的研究之所以受重视，正因为它不绑定眼前的收益。"},{"no":"06","title":"Bookish in manner","titleCN":"带书卷气的、学者做派的","definition":"having the appearance or manner of someone who lives among books","definitionCN":"带有常年与书为伴之人的外表或举止","example":"He adjusted his glasses with a scholarly air before answering.","exampleCN":"他带着学者式的神态推了推眼镜，然后作答。","why":"once the adjective described people, it could also describe their look, so the word acquired a mild flavour of bookishness.","whyCN":"当形容词可以描述人之后，也就能描述人的样子，于是这个词带上了淡淡的书卷气。"},{"no":"07","title":"A critical edition","titleCN":"校勘精审的定本","definition":"describing an edition that records variants and explains editorial choices","definitionCN":"指记录异文并说明取舍理由的版本","example":"The scholarly edition lists every variant reading from the earliest manuscripts.","exampleCN":"这部校勘本列出了最早几份手稿中的每一处异文。","why":"editing is the scholar's craft at its most visible, so a text prepared with full apparatus came to be called scholarly by association.","whyCN":"校勘是学者手艺最显眼的一种，因此附带完整校记的文本便顺理成章地被称为精审之本。"},{"no":"08","title":"Of schools, in old use","titleCN":"旧义：属于学校教育的","definition":"connected with schools and formal instruction, a sense now largely historical","definitionCN":"与学校和正规教学相关，此义如今基本只见于旧文献","example":"The old statutes set out scholarly exercises for the youngest boys.","exampleCN":"旧章程为最小的男孩规定了学校里的练习。","why":"the Latin ancestor scholaris simply meant 'of a school', and that plain institutional sense survives in old texts beside the modern learned sense.","whyCN":"其拉丁语前身 scholaris 本义就是「学校的」，这个朴素的机构义与现代的博学义并存于旧文献中。"}],"etymology":{"intro":{"en":"Scholarly is scholar plus the adjective suffix -ly. Scholar reached English through Old French from Late Latin scholaris 'of a school', which goes back to Latin schola and Greek skholē 'leisure, discussion, place of lecture'. Dates are approximate.","cn":"scholarly 由 scholar 加形容词后缀构成。scholar 经古法语来自晚期拉丁 scholaris「学校的」，后者可追溯至拉丁 schola 与希腊 skholē「闲暇、讨论、讲学之处」。年代为约数。"},"items":[{"era":"GREEK SKHOLE","en":"Skholē began as 'leisure, free time', then named the discussion held in that free time and finally the place where such discussion happened. The shift from leisure to learning place is documented within Greek usage.","cn":"skholē 最初表示「闲暇、空余时间」，随后指在闲暇中进行的讨论，最后指进行这种讨论的场所。从闲暇到讲学之地的转变在希腊语用法中有记录。"},{"era":"LATIN SCHOLA","en":"Latin borrowed the word as schola 'school, lecture place'. The derived adjective scholaris meant 'of a school or scholar'.","cn":"拉丁语借入该词作 schola「学校、讲学之处」，派生形容词 scholaris 意为「学校的、学者的」。"},{"era":"OLD FRENCH ESCOLER","en":"Old French escoler named a pupil or a learned man, and Middle English took the word as scholar in the fourteenth century.","cn":"古法语 escoler 指学生或有学问的人，中古英语在十四世纪把这个词吸收为 scholar。"},{"era":"SUFFIX -LY","en":"From the sixteenth century the suffix -ly, already used to form adjectives from nouns, produced scholarly with the sense 'of or like a scholar'.","cn":"自十六世纪起，本就可把名词构成形容词的后缀造出 scholarly，意为「学者的、像学者那样的」。"},{"era":"MODERN ACADEMIC SENSE","en":"By the nineteenth century scholarly was fixed to serious academic work and to editions that record variants, and this is its dominant use today.","cn":"到十九世纪，scholarly 已固定用于严肃学术工作与记录异文的版本，这一用法今日占主导。"},{"era":"SOURCE UNCERTAIN","en":"The deeper origin of Greek skholē is uncertain; the frequently repeated link to a root meaning 'to hold back' is a reconstruction, not an established derivation.","cn":"希腊 skholē 的更早来源不确定；常被提到的、与表示「拦住」的词根之间的联系属于重构形式，并非已证实的派生。"}]},"similar":{"note":{"en":"Group one holds words built on the same school root but with different jobs in a sentence; group two holds adjectives that also praise knowledge, each with a different shade.","cn":"第一组同出「学校」这一词根，但在句中承担不同功能；第二组都是称赞学问的形容词，各有不同的侧重。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"scholar","ipa":"/ˈskɒlə/","tag":"the person","definition":"The noun for the person; scholarly is the adjective built from it, so the two cannot replace each other.","definitionCN":"指人的名词；scholarly 是由它构成的形容词，二者不能互换。"},{"word":"scholarship","ipa":"/ˈskɒləʃɪp/","tag":"the funding or the field","definition":"Names either academic study as a field or money given for study; it is not a description of method.","definitionCN":"或指学术研究这一领域，或指用于学习的资助；它不是对方法的描述。"},{"word":"scholastic","ipa":"/skəˈlæstɪk/","tag":"medieval schools","definition":"From the same Latin stock but usually describes medieval school theology or a narrowly formal way of arguing.","definitionCN":"同出拉丁词源，但通常指中世纪经院神学或拘泥形式的论辩方式。"},{"word":"school","ipa":"/skuːl/","tag":"the institution","definition":"The plain noun for the institution; it shares the root but carries no hint of learned method.","definitionCN":"指机构的名词，与前者同根，却不含任何「治学方法」的意味。"}]},{"heading":"NEAR MEANING","entries":[{"word":"academic","ipa":"/əˈkædəmɪk/","tag":"institutional study","definition":"About universities, courses and formal study; it stresses the setting, while scholarly stresses the person's habits.","definitionCN":"关于大学、课程与正规学习；它强调场景，而 scholarly 强调人的习惯。"},{"word":"learned","ipa":"/ˈlɜːnɪd/","tag":"wide knowledge","definition":"Said of a person who knows a great deal; it describes the stock of knowledge rather than the method.","definitionCN":"用于知识广博的人，描述的是知识的存量而非方法。"},{"word":"erudite","ipa":"/ɪˈruːdaɪt/","tag":"bookish depth","definition":"A formal word for deep, often old-fashioned reading; it can sound slightly more decorative than scholarly.","definitionCN":"指深厚且常带古风的阅读，比 scholarly 更显文饰。"},{"word":"pedantic","ipa":"/pɪˈdæntɪk/","tag":"showing off detail","definition":"Negative: fussing over small details to display knowledge, which scholarly does not imply.","definitionCN":"贬义：为炫耀学问而抠细节，scholarly 不含此意。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations here are the real Greek and Latin steps behind the word, its real family and its real fixed phrases.","cn":"正常联想取自这个词真实的希腊语与拉丁语演变、真实词族与真实固定搭配。"},"normal":[{"en":"skholē 'leisure' became schola 'school': free time turned into the place of learning.","cn":"skholē「闲暇」变成 schola「学校」：空余时间转为学习之地。"},{"en":"scholar plus -ly: 'of or like a scholar'.","cn":"scholar 加形容词后缀：属于学者、像学者那样。"},{"en":"The family runs scholar, scholarship, scholastic, school and schooling.","cn":"词族包括 scholar、scholarship、scholastic、school 与 schooling。"},{"en":"Fixed phrases mark the work sense: scholarly journal, scholarly edition, scholarly consensus.","cn":"固定搭配标出成果义：学术期刊、校勘本、学界共识。"},{"en":"The contrast with popular writing keeps the tone precise: scholarly articles are checked, popular ones are not.","cn":"与通俗写作对照可保住语气分寸：学术论文经过复核，通俗文章则未必。"}],"abstract":[{"en":"Picture a reading room where the clock is ignored because nobody there is paid by the hour.","cn":"想象一间阅览室，那里没人按小时计酬，于是钟表被忽略。"},{"en":"Picture a footnote chain long enough to reach back to a manuscript nobody has opened for a century.","cn":"想象一串脚注长到能追回一份百年无人翻动的手稿。"},{"en":"Picture a pair of glasses left on a stack of index cards, the only sign that someone was just there.","cn":"想象一副眼镜搁在索引卡堆上，那是有人刚离开的唯一痕迹。"}]},"examples":[{"en":"Her scholarly work on the dialect has become the standard reference.","cn":"她关于该方言的学术著作已成为标准参考。"},{"en":"The seminar was scholarly without being dull.","cn":"这场研讨会有学术深度却不沉闷。"},{"en":"He answered with a scholarly caution that annoyed the reporters.","cn":"他以学者式的谨慎作答，令记者们颇为不耐。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「scholar（学者）+ 形容词后缀」——像学者那样读书、引证、校勘 → 学术的、博学的","word":"scholarly"},"root":"希腊 skholē「闲暇、讲学之处」→ 拉丁 schola「学校」→ 晚期拉丁 scholaris「学校的」→ 古法语 escoler → 英语 scholar 加形容词后缀；skholē 更深来源不确定，与「拦住」词根的联系属重构形式。","sensesIntro":{"en":"Eight senses follow one line: a place of leisure becomes a place of learning, the learner becomes a scholar, and the scholar's habits become marks of method, style, posture, editorial craft and finally of an old institutional sense.","cn":"八个义项沿一条线展开：闲暇之地变成学习之地，学习者成为学者，学者的习惯再变成方法、文风、气质、校勘手艺，最后落到一个旧的机构义。"},"semanticMap":{"core":{"en":"CORE IMAGE: a quiet room where free time is spent reading, and the reading slowly turns into a craft with rules.","cn":"核心意象：一间安静的房间，空余时间被用来阅读，而阅读慢慢变成一门有规矩的手艺。"},"chain":["LEISURE","SCHOOL","LEARNING","SCHOLAR","METHOD","AUTHORITY"],"branches":[{"senses":"01 · 02","en":"PLACE AND PERSON: the leisure place produces the learner, and the learner's work is the first thing called scholarly.","cn":"场所与人：闲暇之地造出学习者，学习者的成果是最早被称为学术的东西。"},{"senses":"03 · 04","en":"METHOD AND STYLE: documented claims harden into rigour, and rigour shows up in prose as dense citation.","cn":"方法与文风：有据的主张硬化为严谨，严谨在文字上表现为密集的引证。"},{"senses":"05 · 06","en":"POSTURE: study for its own sake, and the bookish manner that long study leaves on a person.","cn":"姿态：为学问而学问，以及长期研读留在一个人身上的书卷气。"},{"senses":"07","en":"CRAFT: editorial work is the scholar's method made visible in a printed book.","cn":"手艺：校勘工作让学者的方法在一本印成的书里显形。"},{"senses":"08","en":"OLD INSTITUTION: the plain 'of a school' sense survives from the Latin adjective beside all the later meanings.","cn":"旧的机构义：拉丁形容词那个朴素的「学校的」意思，与后来诸义并存。"}]},"affixes":{"intro":{"en":"The word can be read in two halves: the Greek-Latin school root, and the English suffix that turns a person into a quality.","cn":"这个词可以分两半读：希腊—拉丁的「学校」词根，以及把「人」变成「性质」的英语后缀。"},"latinIntro":{"en":"Latin schola and scholaris supply the root and the older noun; Greek skholē is the earliest recorded form of the same idea.","cn":"拉丁 schola 与 scholaris 提供词根与较早的名词；希腊 skholē 是同一观念最早有记录的形式。"},"items":[{"word":"-ly","structure":"suffix forming adjectives from nouns","meaning":"having the qualities of","meaningCN":"具有……性质的","example":"The suffix turns scholar into scholarly.","exampleCN":"这个后缀把 scholar 变成 scholarly。"},{"word":"skholē","structure":"Greek noun, 'leisure, discussion'","meaning":"free time used for talk and learning","meaningCN":"用于谈论与学习的空余时间","example":"Skholē is the earliest link in the chain.","exampleCN":"skholē 是这条演变链上最早的一环。"},{"word":"schola","structure":"Latin noun, first declension","meaning":"school, lecture place","meaningCN":"学校；讲学之处","example":"Schola passed through Old French into English.","exampleCN":"schola 经古法语进入英语。"},{"word":"scholaris","structure":"Late Latin adjective","meaning":"of a school or a scholar","meaningCN":"学校的；学者的","example":"The adjective supplied the noun scholar.","exampleCN":"这个形容词提供了名词 scholar。"},{"word":"scholar","structure":"schola + -ar (person concerned with)","meaning":"a learned person","meaningCN":"有学问的人","example":"Scholar entered English in the fourteenth century.","exampleCN":"scholar 于十四世纪进入英语。"},{"word":"scholarly","structure":"scholar + -ly (having the qualities of)","meaning":"of or like a scholar","meaningCN":"学者的；像学者那样的","example":"The adjective appeared in the sixteenth century.","exampleCN":"这个形容词于十六世纪出现。"},{"word":"scholarship","structure":"scholar + -ship (state or activity)","meaning":"academic study, or funding for it","meaningCN":"学术研究；用于学习的资助","example":"Her scholarship took her abroad.","exampleCN":"她的奖学金让她得以出国。"},{"word":"scholastic","structure":"schola + -asticus (belonging to)","meaning":"belonging to a school, especially medieval","meaningCN":"属于学校的，尤指中世纪经院","example":"Scholastic argument dominated the universities.","exampleCN":"经院论辩曾主导大学。"},{"word":"schooling","structure":"school + -ing (process)","meaning":"the process of being taught","meaningCN":"受教的过程","example":"His early schooling was strict.","exampleCN":"他早年的学校教育很严格。"}],"latinEntries":[{"word":"schola","structure":"schola, scholae (f., first declension)","meaning":"school, lecture place","meaningCN":"学校；讲学之处"},{"word":"scholaris","structure":"scholaris, scholare (adj., third declension)","meaning":"of a school, of a scholar","meaningCN":"学校的；学者的"},{"word":"scholasticus","structure":"scholasticus, scholastica, scholasticum (adj.)","meaning":"belonging to a school","meaningCN":"属于学校的"}],"derivatives":[{"word":"scholar","pos":"n.","zh":"学者；奖学金获得者"},{"word":"scholarship","pos":"n.","zh":"学术；奖学金"},{"word":"scholastic","pos":"adj.","zh":"经院的；学校的"},{"word":"school","pos":"n.","zh":"学校"},{"word":"schooling","pos":"n.","zh":"学校教育；培养"}]}},{"word":"research-based","ipa_uk":"/rɪˈsɜːtʃ beɪst/","ipa_us":"/rɪˈsɜːrtʃ beɪst/","definition_zh":"以研究为依据的；建立在系统调查与证据之上的","definition_en":"built on systematic investigation and evidence rather than on opinion, tradition or guesswork","core_image":"一份课程方案旁摊着三篇同行评审论文，每处主张都用高亮线连到同一张数据表","scene":"一所学校在改教材之前，先让教师把近十年的课堂实验报告摊在桌上逐条对照。Their new reading programme is entirely research-based.","sceneCN":"学校在改教材前把多年课堂实验报告逐条对照，新方案完全建立在研究证据上；句中的 research-based 指「以系统调查为依据的」（第 1 个义项：建立在系统研究而非意见之上）。图中可辨识物件：课程方案、论文抽印本、数据表、荧光笔。","pos":[{"tag":"adj.","zh":"以研究为依据的；基于证据的"}],"collocations":[{"phrase":"research-based approach","zh":"以研究为依据的方法"},{"phrase":"research-based evidence","zh":"研究证据"},{"phrase":"research-based learning","zh":"研究性学习"},{"phrase":"research-based policy","zh":"基于研究的政策"},{"phrase":"research-based instruction","zh":"基于研究的教学"},{"phrase":"research-based practice","zh":"循证实践"}],"forms":[{"label":"比较级","form":"more research-based"},{"label":"最高级","form":"most research-based"},{"label":"分词式写法（不带连字符）","form":"research based"}],"derivatives":[{"word":"research","pos":"n./v.","zh":"研究；调查"},{"word":"researcher","pos":"n.","zh":"研究者"},{"word":"researchable","pos":"adj.","zh":"可研究的"},{"word":"under-researched","pos":"adj.","zh":"研究不足的"}],"senses":[{"no":"01","title":"Founded on systematic inquiry","titleCN":"建立在系统研究之上","definition":"built on organised investigation rather than on opinion or habit","definitionCN":"以有组织的调查为基础，而非依据意见或习惯","example":"Their new reading programme is entirely research-based.","exampleCN":"他们的新阅读方案完全以研究为依据。","why":"the compound simply joins the noun research, which names organised inquiry, to based, which marks a foundation.","whyCN":"这个复合词把表示有组织调查的名词 research 与表示「以……为基础」的 based 直接接在一起。"},{"no":"02","title":"Evidence for classroom practice","titleCN":"教学实践的循证依据","definition":"describing teaching methods chosen because studies show they work","definitionCN":"指因研究显示有效而被选用的教学方法","example":"The district now prefers research-based instruction over handed-down routines.","exampleCN":"该学区如今更倾向基于研究的教学，而非沿袭旧例。","why":"education borrowed the compound because classroom tradition can be defended by custom alone, and the word insists on tested support.","whyCN":"教育界借用这个复合词，因为课堂传统往往只能靠习惯辩护，而这个词坚持要有经过检验的支持。"},{"no":"03","title":"Grounded in clinical trials","titleCN":"以临床试验为根据的","definition":"describing medical advice that rests on controlled trials and published outcomes","definitionCN":"指建立在对照试验与已发表结果之上的医学建议","example":"Only research-based treatments are covered by the new guideline.","exampleCN":"新指南只纳入以临床试验为依据的疗法。","why":"medicine supplied the earliest strict use, since a drug must show measured results before it can be recommended.","whyCN":"医学提供了最早也最严格的用法，因为药物必须先拿出测量结果才能被推荐。"},{"no":"04","title":"A claim with citations","titleCN":"有文献出处的主张","definition":"describing a statement that can be traced to published studies","definitionCN":"指可追溯到已发表研究的主张","example":"The brief is research-based, so every figure carries a citation.","exampleCN":"这份简报有研究依据，每个数字都带着出处。","why":"the word pushes a claim from assertion to traceable statement, which is why citations follow it.","whyCN":"这个词把主张从「断言」推成「可追溯的陈述」，因此它后面常跟着引文。"},{"no":"05","title":"A method drawn from trials","titleCN":"由实证试验得出的方法","definition":"describing a procedure developed and revised through repeated testing","definitionCN":"指经反复试验开发并修正的程序","example":"Their soil treatment is research-based and was retested on three farms.","exampleCN":"他们的土壤处理法基于实证研究，并已在三处农场复测。","why":"a method earns the label only after trials, so the compound implies a history of revision behind the procedure.","whyCN":"方法要经过试验才配得上这个标签，因此复合词隐含了这套程序背后的修订史。"},{"no":"06","title":"Against anecdotal practice","titleCN":"与凭经验传闻的做法相对","definition":"used to contrast tested practice with advice drawn from single stories","definitionCN":"用于把经过检验的做法与凭个别故事得出的建议相对照","example":"The clinic replaced anecdotal habits with research-based protocols.","exampleCN":"该诊所用以研究为依据的规程取代了凭传闻的习惯。","why":"the opposition to anecdote is built into the word: research means many cases measured, anecdote means one case remembered.","whyCN":"与轶事的对立内置于词中：研究意味着测量许多案例，轶事意味着记住一个案例。"},{"no":"07","title":"Driven by company research","titleCN":"由企业研发支撑的","definition":"describing a product decision that rests on the firm's own laboratory work","definitionCN":"指建立在企业自身实验工作的产品决策","example":"The formula is research-based and protected by two patents.","exampleCN":"这个配方由研发支撑，并受两项专利保护。","why":"industry uses the same compound for internal laboratories, where the evidence is produced by the company itself.","whyCN":"产业界把同一复合词用于内部实验室，此时证据由企业自己生产。"},{"no":"08","title":"Tested with users","titleCN":"经用户测试的（设计义）","definition":"describing a design shaped by observed user behaviour and measured results","definitionCN":"指依据观察到的用户行为与测量结果来塑造的设计","example":"The interface is research-based, built from months of usability sessions.","exampleCN":"这个界面以研究为依据，来自数月的可用性测试。","why":"design extended the compound to any product shaped by observation, because watching users is a form of research too.","whyCN":"设计领域把这个复合词扩展到一切由观察塑造的产品，因为观察用户也是一种研究。"}],"etymology":{"intro":{"en":"The adjective joins research, which came through Old French from the Latin verb circare 'to go about, explore', and based, which comes from Latin basis and Greek basis 'step, pedestal'. The compound itself is a modern formation. Dates are approximate.","cn":"这个形容词由 research 与 based 组合而成。research 经古法语来自拉丁动词 circare「四处走动、探查」；based 来自拉丁 basis 与希腊 basis「台阶、基座」。复合词本身是近代构造。年代为约数。"},"items":[{"era":"LATIN CIRCARE","en":"Circare meant 'to go about, to wander around searching'. It came from circus 'circle', so the original picture is someone tracing a circle while looking for something.","cn":"circare 意为「四处走动、搜寻」，来自 circus「圆圈」，因此最初的意象是循着圈子寻找东西。"},{"era":"OLD FRENCH RECERCHE","en":"Old French added an intensive re- to cerchier 'to search' and produced recerche, the act of searching thoroughly.","cn":"古法语在 cerchier「搜寻」前加起强化作用的 re-，构成 recerche，即彻底搜寻的行为。"},{"era":"MIDDLE ENGLISH","en":"English borrowed the word in the fifteenth century, first as the act of searching for a person or thing, then as systematic study.","cn":"英语在十五世纪借入该词，最初指寻找某人某物，后来指系统的研究。"},{"era":"LATIN AND GREEK BASIS","en":"Basis meant 'step, pedestal, foundation' in Greek and passed into Latin unchanged in meaning; French base gave English the noun base.","cn":"basis 在希腊语中意为「台阶、基座、基础」，进入拉丁语后意义不变；法语 base 给英语提供了名词 base。"},{"era":"COMPOUND FORMATION","en":"Research-based appears in the twentieth century as a hyphenated compound, first in medicine and then in education and policy, wherever a decision needs documented support.","cn":"research-based 于二十世纪作为带连字符的复合词出现，先用于医学，继而用于教育与政策，凡需要文献支持作决定之处都用它。"},{"era":"SOURCE UNCERTAIN","en":"The further origin of circus and of Greek basis is uncertain; the commonly cited links to a root meaning 'to turn' and to a verb meaning 'to step' are reconstructions rather than established derivations.","cn":"circus 与希腊 basis 的更早来源不确定；常被引用的、与表示「转动」的词根及表示「迈步」的动词之间的联系属于重构形式，并非已证实的派生。"}]},"similar":{"note":{"en":"Group one holds the parts of the compound and words that look close to them; group two holds labels for kinds of evidence, which differ in what counts as proof.","cn":"第一组是复合词的组成部分及形近词；第二组是各类「证据」标签，区别在于什么算作证明。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"research","ipa":"/rɪˈsɜːtʃ/","tag":"the noun itself","definition":"The activity of organised inquiry; the compound only says a thing rests on it.","definitionCN":"指有组织的探究活动本身；复合词只说明某物以它为基础。"},{"word":"researcher","ipa":"/rɪˈsɜːtʃə/","tag":"the person","definition":"The person who carries out the inquiry, not a description of the thing built on it.","definitionCN":"指从事探究的人，而非对「以其为基础之物」的描述。"},{"word":"search","ipa":"/sɜːtʃ/","tag":"false friend","definition":"Looks like the second half of research but lacks the intensive prefix, and means a plain hunt.","definitionCN":"形似 research 的后半，却少了那个强化前缀，只表示普通的搜寻。"},{"word":"recertify","ipa":"/riːˈsɜːtɪfaɪ/","tag":"prefix trap","definition":"Begins with the same re- sound but belongs to certify, with no connection to inquiry.","definitionCN":"开头是同样的 re- 音，却属于 certify，与探究毫无关系。"}]},{"heading":"NEAR MEANING","entries":[{"word":"evidence-based","ipa":"/ˈevɪdəns beɪst/","tag":"proof first","definition":"Names the proof itself; research-based names the activity that produced the proof.","definitionCN":"直接点明「证明」，而 research-based 点明产生证明的活动。"},{"word":"empirical","ipa":"/ɪmˈpɪrɪkəl/","tag":"from observation","definition":"Says knowledge comes from observation and experiment, without implying a body of studies.","definitionCN":"指知识来自观察与实验，但不暗示已有一批研究。"},{"word":"data-driven","ipa":"/ˈdeɪtə ˈdrɪvən/","tag":"numbers lead","definition":"Stresses that decisions follow measured numbers, which may come from routine tracking rather than inquiry.","definitionCN":"强调决策跟着测量数字走，而这些数字可能来自日常记录而非研究。"},{"word":"anecdotal","ipa":"/əˈnekdəʊtəl/","tag":"one story","definition":"The opposite pole: evidence from a single remembered case, not from systematic study.","definitionCN":"相反的一极：证据来自一个被记住的个案，而非系统研究。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations here are the two real halves of the compound, its real family and its real fixed phrases.","cn":"正常联想取自复合词真实的两半、真实词族与真实固定搭配。"},"normal":[{"en":"re- 'again, thoroughly' plus cerchier 'to search': to search thoroughly.","cn":"re-「再、彻底」加 cerchier「搜寻」：彻底搜寻。"},{"en":"research plus based: something standing on a foundation of inquiry.","cn":"research 加 based：某物立在探究的地基上。"},{"en":"The family runs research, researcher, researchable, under-researched.","cn":"词族包括 research、researcher、researchable、under-researched。"},{"en":"Fixed phrases mark the use: research-based policy, research-based instruction, research-based medicine.","cn":"固定搭配标出用法：基于研究的政策、基于研究的教学、循证医学。"},{"en":"The contrast with anecdotal advice keeps the meaning sharp.","cn":"与凭轶事给出的建议对照，词义才清楚。"}],"abstract":[{"en":"Picture a table with one leg resting on a stack of journals instead of on the floor.","cn":"想象一张桌子，一条桌腿不落在地面，而落在一摞期刊上。"},{"en":"Picture a recipe card with a footnote longer than the recipe.","cn":"想象一张食谱卡，脚注比食谱本身还长。"},{"en":"Picture a bridge whose every plank is stamped with the date it was tested.","cn":"想象一座桥，每块木板都盖着测试日期的印。"}]},"examples":[{"en":"The tutoring model is research-based and was piloted in twelve schools.","cn":"这套辅导模式以研究为依据，并已在十二所学校试点。"},{"en":"A research-based claim can be checked; a slogan cannot.","cn":"以研究为依据的主张可以被核查，口号则不能。"},{"en":"The hospital moved to research-based protocols for wound care.","cn":"这家医院改用基于研究的伤口护理规程。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「research（研究）+ based（以……为基础）」——把结论建立在研究上 → 以研究为依据的","word":"research-based"},"root":"拉丁 circare「四处探寻」→ 古法语 recerche「彻底搜寻」→ 英语 research；拉丁 basis／希腊 basis「基座」→ 法语 base → 英语 based；二者在二十世纪组成复合形容词。circus 与 basis 的更深来源不确定，常见词根联系属重构形式。","sensesIntro":{"en":"The eight senses keep one frame: an organised inquiry sits underneath a decision, and the frame is then filled by classrooms, clinics, citations, trials, company labs and tested designs.","cn":"八个义项共用一个框架：有组织的探究垫在某个决定之下；这个框架再被课堂、诊所、引文、试验、企业实验室与被测试的设计逐一填满。"},"semanticMap":{"core":{"en":"CORE IMAGE: a document standing on a thick stack of study reports instead of on thin air.","cn":"核心意象：一份文件立在厚厚一摞研究报告上，而不是悬在空中。"},"chain":["SEARCH","INQUIRY","FINDING","CITATION","APPLICATION","TESTED DESIGN"],"branches":[{"senses":"01 · 02","en":"FOUNDATION AND CLASSROOM: the compound first says 'resting on inquiry', then says which room the inquiry serves.","cn":"地基与课堂：复合词先说「立在探究上」，再说这份探究服务哪个场所。"},{"senses":"03 · 04","en":"CLINIC AND CITATION: strict medical use demands trials, and written use demands traceable sources.","cn":"诊所与引文：严格的医学用法要求试验，书面用法要求可追溯的出处。"},{"senses":"05 · 06","en":"TRIAL AND CONTRAST: a method earns the label through retesting, and the label sharpens against mere anecdote.","cn":"试验与对照：方法经复测才获得标签，而标签在与轶事的对照中变锋利。"},{"senses":"07","en":"COMPANY LAB: the evidence can come from the firm's own bench rather than from public studies.","cn":"企业实验室：证据可以来自企业自己的实验台，而非公开研究。"},{"senses":"08","en":"OBSERVED USE: design extends 'research' to watching how people actually behave with a product.","cn":"观察到的使用：设计领域把「研究」扩展到观察人如何使用产品。"}]},"affixes":{"intro":{"en":"The compound is transparent: one half names the inquiry, the other half names the foundation, and both halves have their own Latin and Greek histories.","cn":"这个复合词是透明的：一半点明探究，一半点明地基，两半各有自己的拉丁与希腊来历。"},"latinIntro":{"en":"Latin circare supplies research through Old French; Latin basis, from Greek basis, supplies base and based.","cn":"拉丁 circare 经古法语提供 research；拉丁 basis（源自希腊 basis）提供 base 与 based。"},"items":[{"word":"re-","structure":"Latin prefix, 'again, thoroughly'","meaning":"again; thoroughly","meaningCN":"再；彻底","example":"The prefix intensifies the search.","exampleCN":"这个前缀强化了「搜寻」这一动作。"},{"word":"circare","structure":"Latin verb, first conjugation","meaning":"to go about, explore","meaningCN":"四处走动；探查","example":"Circare came from the word for a circle.","exampleCN":"circare 来自表示「圆圈」的词。"},{"word":"research","structure":"re- + cerchier (Old French 'to search')","meaning":"organised inquiry","meaningCN":"有组织的探究","example":"Research precedes the compound.","exampleCN":"研究先于复合词存在。"},{"word":"basis","structure":"Greek and Latin noun, 'step, pedestal'","meaning":"a foundation to stand on","meaningCN":"可立其上的基础","example":"The base is what the claim stands on.","exampleCN":"基础就是主张所立之处。"},{"word":"based","structure":"base + -ed (having as a base)","meaning":"resting on something","meaningCN":"以某物为基础","example":"The second half marks the foundation.","exampleCN":"后半标示地基。"},{"word":"researcher","structure":"research + -er (person who)","meaning":"one who carries out inquiry","meaningCN":"从事探究的人","example":"A researcher gathered the evidence.","exampleCN":"研究者收集了证据。"},{"word":"researchable","structure":"research + -able (can be)","meaning":"able to be studied","meaningCN":"可被研究的","example":"The question is researchable.","exampleCN":"这个问题可以被研究。"},{"word":"under-researched","structure":"under- + research + -ed","meaning":"not yet studied enough","meaningCN":"研究尚不充分","example":"The condition remains under-researched.","exampleCN":"这种情况仍研究不足。"},{"word":"research-based","structure":"research + based","meaning":"resting on inquiry","meaningCN":"以研究为基础","example":"The programme is research-based.","exampleCN":"该方案以研究为依据。"}],"latinEntries":[{"word":"circare","structure":"circare, circavi, circatum (verb, first conjugation)","meaning":"to go about, explore","meaningCN":"四处走动；探查"},{"word":"circus","structure":"circus, circi (m., second declension)","meaning":"circle, ring","meaningCN":"圆圈；环"},{"word":"basis","structure":"basis, baseos (f., third declension, Greek origin)","meaning":"step, pedestal, foundation","meaningCN":"台阶；基座；基础"}],"derivatives":[{"word":"research","pos":"n./v.","zh":"研究；调查"},{"word":"researcher","pos":"n.","zh":"研究者"},{"word":"researchable","pos":"adj.","zh":"可研究的"},{"word":"under-researched","pos":"adj.","zh":"研究不足的"}]}},{"word":"examine","ipa_uk":"/ɪɡˈzæmɪn/","ipa_us":"/ɪɡˈzæmɪn/","definition_zh":"检查；审查；考查；检验；盘问","definition_en":"to look at something closely and in detail in order to judge its condition, quality or truth","core_image":"一架老式天平，指针停在刻度之间，旁边放着待称的信封与放大镜","scene":"一位技师把送来的旧钟拆开，逐枚查看齿轮的磨损痕迹。A conservator examines each gear under a magnifier before ordering repairs.","sceneCN":"技师拆开旧钟，逐枚查看齿轮磨损；句中的 examine 指「仔细查看以判断状况」（第 1 个义项：近距离细看以了解状态）。图中可辨识物件：拆开的机芯、放大镜、镊子、记录纸。","pos":[{"tag":"vt.","zh":"检查；审查；考查；检验；盘问"}],"collocations":[{"phrase":"examine evidence","zh":"审查证据"},{"phrase":"examine a patient","zh":"检查病人"},{"phrase":"examine a witness","zh":"询问证人"},{"phrase":"examine the data","zh":"分析数据"},{"phrase":"examine a proposal","zh":"审议提案"},{"phrase":"examine goods","zh":"检验货物"}],"forms":[{"label":"三单（he/she/it）","form":"examines"},{"label":"过去式","form":"examined"},{"label":"过去分词","form":"examined"},{"label":"现在分词","form":"examining"},{"label":"名词（检查；考试）","form":"examination"},{"label":"名词（主考人；检查者）","form":"examiner"},{"label":"名词（应试者）","form":"examinee"}],"derivatives":[{"word":"examination","pos":"n.","zh":"检查；考试；审查"},{"word":"examiner","pos":"n.","zh":"主考人；检查者"},{"word":"examinee","pos":"n.","zh":"应试者；受检者"},{"word":"cross-examine","pos":"v.","zh":"交叉询问"},{"word":"exam","pos":"n.","zh":"考试"}],"senses":[{"no":"01","title":"Look closely at a thing","titleCN":"近距离细看以判断状况","definition":"to inspect something closely in order to learn its condition","definitionCN":"近距离查看某物，以了解其状况","example":"A conservator examines each gear under a magnifier.","exampleCN":"修复师在放大镜下逐枚检查齿轮。","why":"the Latin verb came from the noun for the tongue of a balance, so the earliest picture is a needle settling to show how much something weighs.","whyCN":"这个拉丁动词来自表示「天平指针」的名词，因此最早的意象是一根指针停稳，显示某物有多重。"},{"no":"02","title":"Test a student's knowledge","titleCN":"考查学生的掌握程度","definition":"to question a student in order to measure what has been learned","definitionCN":"通过提问来测量学生学到了什么","example":"The committee examines candidates in both written and oral rounds.","exampleCN":"委员会用笔试与口试两轮考查候选人。","why":"a balance decides value by an exact measure, and an examiner does the same with a candidate's knowledge, which is why the school sense came early.","whyCN":"天平用精确的衡量判定价值，主考人对考生的知识做的也是同一件事，因此学校义很早就出现了。"},{"no":"03","title":"Investigate formally","titleCN":"正式审查（证据、案情）","definition":"to go through evidence in an official inquiry","definitionCN":"在正式调查中逐项查验证据","example":"Lawyers examined the invoices line by line.","exampleCN":"律师逐行审查了这些发票。","why":"the weighing image fits legal inquiry: each item is placed on the scale and its weight argued.","whyCN":"称量的意象正合法律调查：每一件证据都被放上天平，再争论它的分量。"},{"no":"04","title":"Check a patient","titleCN":"检查身体","definition":"to inspect a person's body to find signs of illness","definitionCN":"查看人体以发现疾病的迹象","example":"The doctor examined the ankle and sent him for a scan.","exampleCN":"医生检查了脚踝，又让他去做扫描。","why":"the medical sense is the general inspection sense narrowed to the body, where signs must be found before a judgement is made.","whyCN":"医学义是把一般查看收窄到身体：必须先找到迹象，才能作出判断。"},{"no":"05","title":"Analyse data critically","titleCN":"剖析数据","definition":"to study information closely to find patterns or errors","definitionCN":"细究信息以找出规律或错误","example":"The team examined the readings for seasonal drift.","exampleCN":"团队细查读数，寻找季节性漂移。","why":"data has to be weighed in the same way as goods: the verb keeps its old sense of testing rather than merely seeing.","whyCN":"数据也要像货物一样被称量：这个动词保留的是「检验」而非「看见」的旧义。"},{"no":"06","title":"Question a witness","titleCN":"盘问证人","definition":"to question a witness formally, especially in court","definitionCN":"正式询问证人，尤指在法庭上","example":"The defence examined the witness for two hours.","exampleCN":"辩方盘问证人达两小时。","why":"courtroom question and balance share an origin: both force an account to show its weight under pressure.","whyCN":"法庭讯问与天平同源：二者都迫使一份陈述在压力下显出分量。"},{"no":"07","title":"Inspect goods","titleCN":"检验货物","definition":"to check goods for quality or damage before accepting them","definitionCN":"在接受货物前查看其质量或损坏情况","example":"The buyer examined the crates before signing.","exampleCN":"买方在签字前检验了木箱。","why":"trade kept the most literal sense, because a merchant must look at what is being weighed and paid for.","whyCN":"商贸保留了最字面的意义，因为商人必须看清被称量、被付钱的东西。"},{"no":"08","title":"Weigh a proposal","titleCN":"权衡、审议提案","definition":"to consider an idea carefully before deciding","definitionCN":"在作决定前仔细考虑一个想法","example":"The board examined every option before voting.","exampleCN":"董事会在投票前审议了每一个选项。","why":"the balance image turns abstract: options are placed one after another on the same scale until a choice settles.","whyCN":"天平的意象在此抽象化：选项被逐一放上同一架秤，直到选择落定。"}],"etymology":{"intro":{"en":"Examine comes from Latin examinare 'to weigh, test', built on examen, the noun for the tongue or needle of a balance, which itself goes back to exigere 'to drive out, to weigh'. Dates are approximate.","cn":"examine 来自拉丁 examinare「称量、检验」，其名词 examen 指天平的指针或舌杆，而 examen 又可追溯至 exigere「驱出、称量」。年代为约数。"},"items":[{"era":"LATIN EXIGERE","en":"Exigere combined ex- 'out' with agere 'to drive, do' and meant 'to drive out, to demand, to weigh exactly'. The weighing sense grew from the demand for exact measure.","cn":"exigere 由 ex-「出」与 agere「驱使、做」构成，意为「驱出、索求、精确称量」。称量义由对精确衡量的要求发展而来。"},{"era":"LATIN EXAMEN","en":"Examen named the tongue of a balance, the pointer that settles when the two pans hold equal weight.","cn":"examen 指天平的舌杆，即两盘等重时停稳的那根指针。"},{"era":"LATIN EXAMINARE","en":"From the noun came examinare 'to weigh, to test, to inquire into', used for both goods and arguments.","cn":"由这个名词产生 examinare「称量、检验、查究」，既用于货物也用于论辩。"},{"era":"OLD FRENCH AND ENGLISH","en":"Old French examiner carried the verb into English in the fourteenth century, first in the legal and scholarly senses.","cn":"古法语 examiner 在十四世纪把这个动词带入英语，最初用于法律与学术场合。"},{"era":"SCHOOL AND MEDICAL SENSES","en":"By the sixteenth century the verb covered questioning a candidate and inspecting a patient, both extensions of testing.","cn":"到十六世纪，这个动词已涵盖考查考生与检查病人，二者都是「检验」的延伸。"},{"era":"SOURCE UNCERTAIN","en":"The detail that examen meant specifically the balance tongue is generally accepted, but the deeper origin of agere and the exact route from exigere to examen are not fully settled; forms offered for a pre-Latin root are reconstructions.","cn":"examen 特指天平舌杆这一细节一般认为是可靠的，但 agere 的更早来源以及从 exigere 到 examen 的确切路径尚无定论；为其拉丁语之前词根给出的形式属重构形式。"}]},"similar":{"note":{"en":"Group one holds the derived family and two words that merely look similar but come from a different verb; group two holds verbs of looking and testing that differ in pressure and purpose.","cn":"第一组是派生词族，以及两个只是形似、其实出自另一动词的词；第二组是查看与检验类动词，压力与目的各不相同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"examination","ipa":"/ɪɡˌzæmɪˈneɪʃən/","tag":"the noun","definition":"The act or result of examining, and also the paper sat in a school; it cannot stand where the verb is needed.","definitionCN":"检查或审查的行为与结果，也指学校里的试卷；不能代替动词。"},{"word":"examiner","ipa":"/ɪɡˈzæmɪnə/","tag":"the person","definition":"The one who questions or inspects, not the act itself.","definitionCN":"指提问或检查的人，而非行为本身。"},{"word":"example","ipa":"/ɪɡˈzæmpəl/","tag":"different root","definition":"Looks close but comes from eximere 'to take out', not from examen; an example is something taken out for display.","definitionCN":"形近但出自 eximere「取出」，与 examen 无关；example 是被取出展示的样本。"},{"word":"exempt","ipa":"/ɪɡˈzempt/","tag":"different root","definition":"Also from eximere: to take someone out of an obligation, with no notion of weighing.","definitionCN":"同样出自 eximere：把某人从义务中取出，不含称量之意。"}]},{"heading":"NEAR MEANING","entries":[{"word":"inspect","ipa":"/ɪnˈspekt/","tag":"official looking","definition":"A formal look, often by an authority checking standards; examine is broader and can include testing.","definitionCN":"正式查看，常指权威方查标准；examine 范围更广，可含检验。"},{"word":"investigate","ipa":"/ɪnˈvestɪɡeɪt/","tag":"following a trail","definition":"To look into a matter over time, following leads; it stresses process more than the single act of weighing.","definitionCN":"指沿线索在一段时间里查办某事，更强调过程而非单次称量。"},{"word":"scrutinize","ipa":"/ˈskruːtənaɪz/","tag":"close and suspicious","definition":"To examine with suspicion and great closeness, adding doubt that examine does not carry.","definitionCN":"带着怀疑极仔细地查看，多出 examine 所无的疑虑。"},{"word":"test","ipa":"/test/","tag":"put to proof","definition":"To make something show its quality by use or trial; examine may only look and judge.","definitionCN":"通过使用或试用让某物显出品质；examine 可能只是查看并判断。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations here are the real balance image, the real Latin steps, the real family and the real fixed phrases.","cn":"正常联想取自真实的天平意象、真实的拉丁演变、真实词族与真实固定搭配。"},"normal":[{"en":"examen was the tongue of a balance: to examine is to put something on the scale.","cn":"examen 是天平的舌杆：examine 就是把某物放上秤。"},{"en":"ex- 'out' plus agere 'drive': to drive a matter out into the open where it can be weighed.","cn":"ex-「出」加 agere「驱使」：把一件事驱到明处，好称它的分量。"},{"en":"The family runs examination, examiner, examinee, exam, cross-examine.","cn":"词族包括 examination、examiner、examinee、exam、cross-examine。"},{"en":"Fixed phrases mark the settings: examine evidence, examine a patient, examine a witness.","cn":"固定搭配标出场景：审查证据、检查病人、询问证人。"},{"en":"The passive is common in reports: the findings were examined by two reviewers.","cn":"报告中常用被动式：研究结果由两位审稿人审查。"}],"abstract":[{"en":"Picture a needle that will not settle until every doubt has been placed on one pan or the other.","cn":"想象一根指针，直到所有疑问都被放上这盘或那盘才肯停稳。"},{"en":"Picture a jeweller's loupe left on a tray of loose stones, each one already weighed.","cn":"想象一枚珠宝放大镜搁在一盘散石上，每颗都已称过。"},{"en":"Picture a courtroom where a sentence is literally hung on the scales.","cn":"想象一间法庭，判决就悬在天平上。"}]},"examples":[{"en":"The panel examined the proposal for hidden costs.","cn":"小组审议了提案，寻找隐藏成本。"},{"en":"She examined the transcript against the recording.","cn":"她对照录音检查了文字稿。"},{"en":"The vet examined the horse before the sale.","cn":"兽医在售前检查了这匹马。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「ex（出）+ amine（像「阿门」）」——把东西拿出来放到天平上称一称 → 检查、审查、考查","word":"examine"},"root":"拉丁 exigere「驱出、称量」→ 名词 examen「天平指针」→ 动词 examinare「称量、检验」→ 古法语 examiner → 英语 examine；agere 的更深来源与 exigere 到 examen 的确切路径尚无定论，相关词根形式属重构形式。","sensesIntro":{"en":"Eight senses hang on one instrument: something is placed on a balance, and the same gesture is then used on a clock, a student, a file of evidence, an ankle, a data set, a witness, a crate and finally on a list of options.","cn":"八个义项挂在同一件器具上：把某物放上天平，同一个动作随后用于旧钟、学生、证据卷宗、脚踝、数据集、证人、木箱，最后用于一列选项。"},"semanticMap":{"core":{"en":"CORE IMAGE: a balance needle that only settles after everything has been put on the pans.","cn":"核心意象：一根天平指针，非等一切都被放上秤盘不肯停稳。"},"chain":["WEIGH","INSPECT","QUESTION","PROVE","ANALYSE","DECIDE"],"branches":[{"senses":"01 · 07","en":"PHYSICAL CHECK: a gear and a crate are both looked over before a judgement is passed.","cn":"实物查验：齿轮与木箱都要先被看过，才有判断。"},{"senses":"02 · 06","en":"QUESTIONING: a candidate and a witness are pressed to show what they carry.","cn":"盘问：考生与证人都被追问，要他们显出分量。"},{"senses":"03 · 05","en":"PAPER AND NUMBERS: invoices and readings must be gone through line by line.","cn":"纸面与数字：发票与读数都得逐行过一遍。"},{"senses":"04","en":"BODY: the same inspection narrows to signs of illness in a patient.","cn":"身体：同样的查看收窄为病人身上的疾病迹象。"},{"senses":"08","en":"CHOICE: options are weighed one after another until the needle settles.","cn":"抉择：选项被逐一称量，直到指针停稳。"}]},"affixes":{"intro":{"en":"The verb is a Latin prefix and root plus two suffixes, and the same pieces build the whole examining family.","cn":"这个动词由拉丁前缀、词根再加两个后缀构成，同一批部件也造出整个「检查」词族。"},"latinIntro":{"en":"Latin exigere and examen supply the core; the English suffixes -ation, -er and -ee build the nouns.","cn":"拉丁 exigere 与 examen 提供核心；英语中的名词后缀与表人后缀造出各个名词。"},"items":[{"word":"ex-","structure":"Latin prefix, 'out'","meaning":"out; forth","meaningCN":"出；向外","example":"The prefix drives the action outward.","exampleCN":"这个前缀把动作向外驱出。"},{"word":"agere","structure":"Latin verb, third conjugation","meaning":"to drive, do, lead","meaningCN":"驱使；做；引导","example":"Agere is the root of the weighing image.","exampleCN":"agere 是称量意象的根。"},{"word":"examen","structure":"Latin noun, third declension","meaning":"balance tongue; a weighing","meaningCN":"天平指针；称量","example":"Examen supplied the English verb.","exampleCN":"examen 提供了英语动词。"},{"word":"examine","structure":"examinare (Latin verb)","meaning":"to weigh, test, inspect","meaningCN":"称量；检验；查看","example":"The verb entered English through French.","exampleCN":"这个动词经法语进入英语。"},{"word":"examination","structure":"examine + -ation (action, result)","meaning":"the act of testing or inspecting","meaningCN":"检验或审查的行为","example":"The examination lasted three hours.","exampleCN":"这场审查持续了三小时。"},{"word":"examiner","structure":"examine + -er (person who)","meaning":"one who tests or inspects","meaningCN":"主持考查或检查的人","example":"The examiner read the answers twice.","exampleCN":"主考人把答案读了两遍。"},{"word":"examinee","structure":"examine + -ee (person acted upon)","meaning":"one who is tested","meaningCN":"接受考查的人","example":"Each examinee received a numbered seat.","exampleCN":"每位应试者都拿到一个编号座位。"},{"word":"exam","structure":"clipped form of examination","meaning":"a school test","meaningCN":"学校考试","example":"The exam was moved to Friday.","exampleCN":"考试改到星期五。"},{"word":"cross-examine","structure":"cross- + examine","meaning":"to question a witness for the other side","meaningCN":"对另一方证人进行交叉询问","example":"Counsel cross-examined the clerk.","exampleCN":"律师交叉询问了那名职员。"}],"latinEntries":[{"word":"exigere","structure":"exigere, exegi, exactum (verb, third conjugation)","meaning":"to drive out, demand, weigh","meaningCN":"驱出；索求；称量"},{"word":"examen","structure":"examen, examinis (n., third declension)","meaning":"the tongue of a balance; a weighing","meaningCN":"天平舌杆；称量"},{"word":"examinare","structure":"examinare, examinavi, examinatum (verb, first conjugation)","meaning":"to weigh, test, inquire into","meaningCN":"称量；检验；查究"}],"derivatives":[{"word":"examination","pos":"n.","zh":"检查；考试；审查"},{"word":"examiner","pos":"n.","zh":"主考人；检查者"},{"word":"examinee","pos":"n.","zh":"应试者；受检者"},{"word":"cross-examine","pos":"v.","zh":"交叉询问"},{"word":"exam","pos":"n.","zh":"考试"}]}},{"word":"examination system","ipa_uk":"/ɪɡˌzæmɪˈneɪʃən ˈsɪstəm/","ipa_us":"/ɪɡˌzæmɪˈneɪʃən ˈsɪstəm/","definition_zh":"考试制度；考试体系","definition_en":"the organised set of examinations through which a school, region or state decides who advances, qualifies or is admitted","core_image":"一间考场里成排的课桌，桌角贴着编号，门口挂着统一的时间表","scene":"一个地区把升学名额几乎全押在一场统考之上，学校的课时安排也跟着考试日程起落。The examination system decides which students move on to the next level.","sceneCN":"该地区把升学名额几乎全押在一场统考上，课时也随之起落；句中的 examination system 指「决定谁能升学的整套考试安排」（第 1 个义项：以考试筛选与分流的制度）。图中可辨识物件：成排课桌、座位编号、考场时间表、封好的试卷袋。","pos":[{"tag":"n.","zh":"考试制度；考试体系"}],"collocations":[{"phrase":"examination system reform","zh":"考试制度改革"},{"phrase":"national examination system","zh":"国家考试制度"},{"phrase":"entrance examination system","zh":"入学考试制度"},{"phrase":"civil service examination system","zh":"文官考试制度"},{"phrase":"examination-oriented system","zh":"应试导向的制度"},{"phrase":"examination system overhaul","zh":"考试体系全面改革"}],"forms":[{"label":"复数","form":"examination systems"},{"label":"简称","form":"exam system"},{"label":"复数简称","form":"exam systems"},{"label":"定语连字符形式","form":"examination-system reform"}],"derivatives":[{"word":"examine","pos":"v.","zh":"考查；审查"},{"word":"examination","pos":"n.","zh":"考试；检查"},{"word":"examiner","pos":"n.","zh":"主考人；检查者"},{"word":"examinee","pos":"n.","zh":"应试者"},{"word":"exam","pos":"n.","zh":"考试"}],"senses":[{"no":"01","title":"A system that selects students","titleCN":"以考试筛选与分流的制度","definition":"the arrangement of exams by which a region decides who may move up to the next stage of education","definitionCN":"一个地区用以决定谁可升入下一阶段教育的考试安排","example":"The examination system decides which students move on to the next level.","exampleCN":"考试制度决定哪些学生升入下一阶段。","why":"examination names the single test, and system names an organised whole, so the phrase turns scattered tests into one machinery of selection.","whyCN":"examination 指单场考试，system 指有组织的整体，因此这个短语把零散的考试变成一部筛选机器。"},{"no":"02","title":"A school's assessment framework","titleCN":"学校内部的考评体系","definition":"the planned pattern of tests, marks and reports inside a school","definitionCN":"学校内部对测验、评分与成绩报告的整体安排","example":"The school revised its examination system to include project work.","exampleCN":"该校修改了考评体系，把课题作业纳入其中。","why":"once the phrase entered schools, it covered the ordinary round of mid-terms, finals and reports, not only national selection.","whyCN":"这个短语进入学校后，便涵盖期中、期末与成绩报告这一整轮常规安排，而不只是全国性的选拔。"},{"no":"03","title":"The imperial civil service exams","titleCN":"科举式的文官考试制度","definition":"the historic system of written state examinations used to recruit officials","definitionCN":"历史上以书面国家考试选拔官员的制度","example":"Historians compare the civil service examination system with modern testing.","exampleCN":"历史学者把文官考试制度与现代测试相比较。","why":"the longest-running example of the phrase is the Chinese system for recruiting officials, which tied examination results directly to office.","whyCN":"这个短语延续最久的实例是选拔官员的考试制度，它把考试结果与官职直接挂钩。"},{"no":"04","title":"A regime of standardized tests","titleCN":"标准化测试制度","definition":"a large-scale arrangement of uniform tests scored and compared across schools","definitionCN":"在全校际统一命题、统一评分并相互比较的大规模安排","example":"Under the standardized examination system, every school sits the same paper.","exampleCN":"在标准化考试制度下，每所学校都考同一份卷。","why":"scale changed the phrase: uniform papers and shared scoring turned the system into an instrument of comparison.","whyCN":"规模改变了这个短语：统一试卷与统一评分把它变成一件比较工具。"},{"no":"05","title":"The university admission structure","titleCN":"高校招生考试体系","definition":"the set of exams and score thresholds that govern entry to universities","definitionCN":"管辖大学入学的考试组合与分数门槛","example":"The university entrance examination system was reformed twice in a decade.","exampleCN":"高校入学考试体系在十年内改革了两次。","why":"admission is the highest-stakes use, because a single score can decide a place and a future course of study.","whyCN":"招生是利害最大的用法，因为一个分数就能决定一个名额与未来的专业方向。"},{"no":"06","title":"Professional licensing exams","titleCN":"职业资格考试制度","definition":"the required exams that license people to practise a profession","definitionCN":"准许某人执业所必须通过的考试安排","example":"The new examination system for nurses includes a practical station.","exampleCN":"新的护士考试制度加入了实操站点。","why":"professions borrowed the phrase because a licence is a public claim of competence, and the exam is how the claim is checked.","whyCN":"各行业借用这个短语，因为执照是对胜任力的公开声明，而考试正是核查这份声明的方式。"},{"no":"07","title":"Periodic in-service appraisal","titleCN":"定期考核制度","definition":"a recurring schedule of tests or reviews for people already employed","definitionCN":"对在职人员定期测验或评议的固定安排","example":"The bank's examination system reviews staff every two years.","exampleCN":"这家银行的考核制度每两年评议一次员工。","why":"the phrase moved from entry to maintenance: the same machinery now checks people who are already inside.","whyCN":"这个短语从「入口」转到「维持」：同一套机器现在检查已经在里面的人。"},{"no":"08","title":"Exam-driven schooling","titleCN":"应试教育体系（批评用法）","definition":"a school culture in which teaching is shaped mainly by what tests require","definitionCN":"教学主要由考试要求塑造的学校文化","example":"Critics say the examination system narrows what counts as learning.","exampleCN":"批评者认为这种应试体系窄化了「学习」的定义。","why":"the critical sense is the selection sense seen from the classroom: when tests decide advancement, they also decide what gets taught.","whyCN":"批评义是从课堂一侧看筛选义：当考试决定升学，它也就决定了教什么。"}],"etymology":{"intro":{"en":"The phrase joins examination, from Latin examinare 'to weigh, test', and system, from Late Latin systema and Greek systema 'organised whole'. The English phrase is a modern formation naming an institution. Dates are approximate.","cn":"这个短语由 examination 与 system 组成。examination 来自拉丁 examinare「称量、检验」；system 来自晚期拉丁 systema 与希腊 systema「有组织的整体」。英语短语是命名一项制度的近代构造。年代为约数。"},"items":[{"era":"LATIN EXAMEN","en":"Examen named the tongue of a balance, and examinare meant 'to weigh, test'. Testing knowledge inherited the image of a needle settling.","cn":"examen 指天平舌杆，examinare 意为「称量、检验」。考查知识继承的就是指针停稳的意象。"},{"era":"GREEK SYSTEMA","en":"Systema meant 'an organised whole, a body of parts standing together', built from syn- 'together' and histanai 'to set up, stand'.","cn":"systema 意为「有组织的整体、各部分共同立成的团体」，由 syn-「共同」与 histanai「立起、站立」构成。"},{"era":"LATE LATIN SYSTEMA","en":"Late Latin kept systema for a whole arranged in parts; English system entered in the seventeenth century with the same sense.","cn":"晚期拉丁保留 systema，指按部分安排的整体；英语 system 于十七世纪以同一意义进入。"},{"era":"MASS SCHOOLING","en":"In the nineteenth century states built school systems and attached public examinations to them, and the two nouns became a fixed phrase.","cn":"十九世纪各国建立学校体系并把公共考试挂在体系上，这两个名词由此成为固定短语。"},{"era":"REFORM AND CRITIQUE","en":"In the twentieth and twenty-first centuries the phrase appears mainly in reform debates, where its selection function and its effect on teaching are both questioned.","cn":"在二十与二十一世纪，这个短语主要出现在改革争论中，其筛选功能与对教学的影响同时受到质疑。"},{"era":"SOURCE UNCERTAIN","en":"The exact first citation of the English phrase is uncertain; the deeper origin of Greek histanai is generally connected to a root meaning 'to stand', and any form offered before Greek is a reconstruction.","cn":"这个英语短语确切的最早书证不确定；希腊 histanai 的更早来源一般被认为与表示「站立」的词根相关，凡在希腊语之前给出的形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds the two component nouns and the short form used in speech; group two holds neighbouring institutional labels that stress a different part of the same machinery.","cn":"第一组是组成短语的两个名词，以及口语中的简称；第二组是相邻的制度名称，各自强调同一套机器的不同部分。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"examination","ipa":"/ɪɡˌzæmɪˈneɪʃən/","tag":"one test, or the act","definition":"Names a single paper or the act of inspecting; it does not by itself mean a nationwide arrangement.","definitionCN":"指单份试卷或检查行为，本身不含全国性制度的意味。"},{"word":"exam system","ipa":"/ɪɡˈzæm ˈsɪstəm/","tag":"spoken short form","definition":"The everyday clipping of the phrase, common in conversation and headlines.","definitionCN":"该短语在日常口语与标题中的缩略形式。"},{"word":"system","ipa":"/ˈsɪstəm/","tag":"the whole","definition":"Any organised whole; without the first noun it says nothing about tests.","definitionCN":"指任何有组织的整体；没有前一个名词便与考试无关。"},{"word":"examiner","ipa":"/ɪɡˈzæmɪnə/","tag":"the official","definition":"The person who marks or questions, a role inside the system rather than the system itself.","definitionCN":"指评分或提问的人，是体系内的角色而非体系本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"assessment system","ipa":"/əˈsesmənt ˈsɪstəm/","tag":"judging in general","definition":"Covers coursework, portfolios and observation as well as papers; examination system is narrower and test-centred.","definitionCN":"涵盖课业、作品集与观察，不限于笔试；examination system 更窄，以考试为中心。"},{"word":"testing regime","ipa":"/ˈtestɪŋ rɪˈʒiːm/","tag":"frequency and pressure","definition":"Stresses how often tests occur and how much they control, often with a critical tone.","definitionCN":"强调测试的频率与控制力，常带批评语气。"},{"word":"admissions system","ipa":"/əˈmɪʃənz ˈsɪstəm/","tag":"who gets in","definition":"Focuses on the gate to institutions, of which exams may be only one part.","definitionCN":"聚焦进入机构的那道门，考试可能只是其中一环。"},{"word":"school-leaving examination","ipa":"/ˈskuːl ˈliːvɪŋ ɪɡˌzæmɪˈneɪʃən/","tag":"the final paper","definition":"Names the terminal test itself, not the machinery that surrounds it.","definitionCN":"指毕业时那场终结性考试本身，而非围绕它的整套机器。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations here are the two real halves, their real Latin and Greek sources, and the real settings where the phrase is used.","cn":"正常联想取自短语真实的两半、它们真实的拉丁与希腊来源，以及这个短语真实的使用场景。"},"normal":[{"en":"examination from the balance needle, system from parts standing together.","cn":"examination 来自天平指针，system 来自共同立起的各部分。"},{"en":"One test is an event; a system is the timetable that repeats it.","cn":"一场考试是一个事件；一套制度是让事件重复的时间表。"},{"en":"Fixed phrases mark the scale: national examination system, entrance examination system, civil service examination system.","cn":"固定搭配标出规模：国家考试制度、入学考试制度、文官考试制度。"},{"en":"The phrase appears in reform talk: overhaul, reform, abolish.","cn":"这个短语常出现在改革话题中：全面整改、改革、废除。"},{"en":"The critical form adds oriented: an examination-oriented system puts tests at the centre.","cn":"批评用法加上「导向」二字：应试导向的制度把考试放到中心。"}],"abstract":[{"en":"Picture a corridor of identical desks, each with the same clock above it.","cn":"想象一条走廊，排着相同的课桌，每张桌上方挂同一口钟。"},{"en":"Picture a single number printed at the top of a page, deciding which door opens.","cn":"想象页首印着一个数字，决定哪扇门会打开。"},{"en":"Picture a timetable so heavy that teachers plan lessons backwards from it.","cn":"想象一份重到让教师倒着排课的时间表。"}]},"examples":[{"en":"The national examination system was designed to standardize admission.","cn":"国家考试制度的设计目的是统一招生标准。"},{"en":"Reformers argued that the examination system rewarded memory over reasoning.","cn":"改革者认为这种考试制度奖励记忆而非推理。"},{"en":"Every province runs its own version of the examination system.","cn":"各省运行自己版本的考试制度。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「examination（考试）+ system（体系）」——把一场场考试连成一套决定升学的机器 → 考试制度","word":"examination system"},"root":"拉丁 examen「天平指针」→ examinare「称量、检验」→ examination；希腊 systema「共同立起的整体」（syn- 共同 + histanai 立起）→ 晚期拉丁 systema → 英语 system；两词在近代组成固定短语。histanai 的更深来源一般与「站立」词根相关，更早形式属重构。","sensesIntro":{"en":"Eight senses all describe one machine: a set of tests is arranged into a system, and that machine is then used to select, to grade inside a school, to recruit officials, to compare schools, to admit students, to license workers, to review staff and finally to shape teaching itself.","cn":"八个义项描述的是同一部机器：一组考试被安排成体系，这部机器随后用于选拔、校内评分、招募官员、比较学校、录取学生、发放执照、评议在职者，最后反过来塑造教学本身。"},"semanticMap":{"core":{"en":"CORE IMAGE: a row of identical desks under one clock, and a single timetable that decides what happens after the paper is collected.","cn":"核心意象：同一口钟下排着相同的课桌，一张时间表决定收卷之后发生什么。"},"chain":["TEST","ORDER","SELECTION","COMPARISON","LICENCE","CULTURE"],"branches":[{"senses":"01 · 05","en":"GATE: the same machinery decides who advances and who is admitted to university.","cn":"闸门：同一套机器决定谁升学、谁被大学录取。"},{"senses":"02 · 07","en":"INSIDE THE HOUSE: schools grade their own pupils, employers review their own staff.","cn":"院内：学校评自己的学生，雇主评自己的员工。"},{"senses":"03","en":"OFFICE: the oldest large example ties written results directly to a post.","cn":"官职：延续最久的大规模实例把书面成绩直接绑到职位上。"},{"senses":"04 · 06","en":"SCALE AND LICENCE: uniform papers allow comparison across schools, and exams certify fitness to practise.","cn":"规模与执照：统一试卷使校际比较可行，考试则证明可以执业。"},{"senses":"08","en":"BACK ONTO TEACHING: when tests decide advancement, they also decide what is taught.","cn":"反作用于教学：考试决定升学，也就决定了教什么。"}]},"affixes":{"intro":{"en":"The phrase is built from two complete words, each with its own Latin or Greek lineage, and each lineage also builds a family of English words.","cn":"这个短语由两个完整的词构成，各有自己的拉丁或希腊谱系，每个谱系又各造出一族英语词。"},"latinIntro":{"en":"Latin examen and examinare supply the first word; Greek systema, through Late Latin, supplies the second.","cn":"拉丁 examen 与 examinare 提供第一个词；希腊 systema 经晚期拉丁提供第二个词。"},"items":[{"word":"examen","structure":"Latin noun, third declension","meaning":"balance tongue; a weighing","meaningCN":"天平指针；称量","example":"Examen is the earliest form of the first word.","exampleCN":"examen 是第一个词最早的形式。"},{"word":"examinare","structure":"Latin verb, first conjugation","meaning":"to weigh, test","meaningCN":"称量；检验","example":"Examinare became English examine.","exampleCN":"examinare 变成英语 examine。"},{"word":"examination","structure":"examinare + -ation (action)","meaning":"the act of testing; a test","meaningCN":"检验行为；考试","example":"Examination entered English through French.","exampleCN":"examination 经法语进入英语。"},{"word":"examine","structure":"back-formed from examination","meaning":"to test or inspect","meaningCN":"考查；检查","example":"Committees examine candidates.","exampleCN":"委员会考查候选人。"},{"word":"systema","structure":"Greek noun, third declension","meaning":"organised whole","meaningCN":"有组织的整体","example":"Systema is the source of system.","exampleCN":"systema 是 system 的来源。"},{"word":"system","structure":"systema through Late Latin","meaning":"an organised set of parts","meaningCN":"由各部分组成的体系","example":"The system repeats the test.","exampleCN":"体系让考试重复发生。"},{"word":"systematic","structure":"systema + -aticus (belonging to)","meaning":"done according to a plan","meaningCN":"按计划进行的","example":"The review was systematic.","exampleCN":"这次复查是按计划进行的。"},{"word":"systematize","structure":"systematic + -ize (make)","meaning":"to arrange into a system","meaningCN":"使成体系","example":"They systematized the marking.","exampleCN":"他们把评分体系化。"},{"word":"exam","structure":"clipped form of examination","meaning":"a school test","meaningCN":"学校考试","example":"The exam is next week.","exampleCN":"考试在下周。"}],"latinEntries":[{"word":"examen","structure":"examen, examinis (n., third declension)","meaning":"the tongue of a balance; a weighing","meaningCN":"天平舌杆；称量"},{"word":"examinare","structure":"examinare, examinavi, examinatum (verb, first conjugation)","meaning":"to weigh, test, inquire into","meaningCN":"称量；检验；查究"},{"word":"systema","structure":"systema, systematis (n., third declension, Greek origin)","meaning":"an organised whole","meaningCN":"有组织的整体"}],"derivatives":[{"word":"examine","pos":"v.","zh":"考查；审查"},{"word":"examination","pos":"n.","zh":"考试；检查"},{"word":"examiner","pos":"n.","zh":"主考人"},{"word":"examinee","pos":"n.","zh":"应试者"},{"word":"systematic","pos":"adj.","zh":"系统的；有条理的"}]}},{"word":"academic achievement","ipa_uk":"/ˌækəˈdemɪk əˈtʃiːvmənt/","ipa_us":"/ˌækəˈdemɪk əˈtʃiːvmənt/","definition_zh":"学业成就；学习成绩","definition_en":"the level of learning a student has reached, usually shown by grades, test scores and completed work","core_image":"一张成绩单与一摞作业本并排放在桌上，旁边贴着逐年上升的折线图","scene":"一所乡镇中学把连续三年的毕业成绩贴在走廊尽头，来访者一眼就能看出变化。Academic achievement rose steadily after the tutoring programme began.","sceneCN":"学校把三年毕业成绩贴在走廊，变化一眼可见；句中的 academic achievement 指「以分数与作品体现的学业水平」（第 1 个义项：可测量的学习成果）。图中可辨识物件：成绩单、作业本、折线图、走廊公告板。","pos":[{"tag":"n.","zh":"学业成就；学习成绩"}],"collocations":[{"phrase":"academic achievement gap","zh":"学业成就差距"},{"phrase":"academic achievement scores","zh":"学业成绩分数"},{"phrase":"improve academic achievement","zh":"提高学业成绩"},{"phrase":"measure academic achievement","zh":"衡量学业成就"},{"phrase":"academic achievement standards","zh":"学业成就标准"},{"phrase":"student academic achievement","zh":"学生学业成就"}],"forms":[{"label":"复数","form":"academic achievements"},{"label":"定语用法","form":"academic achievement data"},{"label":"带连字符的定语","form":"academic-achievement gap"}],"derivatives":[{"word":"academic","pos":"adj./n.","zh":"学术的；大学教师"},{"word":"academy","pos":"n.","zh":"学院；研究院"},{"word":"academically","pos":"adv.","zh":"学业上；学术上"},{"word":"academician","pos":"n.","zh":"院士"},{"word":"achieve","pos":"v.","zh":"取得；达到"},{"word":"achievable","pos":"adj.","zh":"可实现的"}],"senses":[{"no":"01","title":"Measured learning outcomes","titleCN":"可测量的学习成果","definition":"the level of learning shown by grades, marks and test results","definitionCN":"由等级、分数与测验结果体现的学习水平","example":"Academic achievement rose steadily after the tutoring programme began.","exampleCN":"辅导计划开始后，学业成绩稳步上升。","why":"achievement names something brought to a head or completed, so the phrase measures how much learning has actually been finished and shown.","whyCN":"achievement 指被做到头、被完成的事，因此这个短语衡量的是学习究竟完成了多少并显现出来。"},{"no":"02","title":"Accomplishment at school","titleCN":"在校取得的成就","definition":"a notable success in school, such as a prize, a finished project or a completed course","definitionCN":"在学校的显著成绩，如获奖、完成课题或读完课程","example":"Her academic achievement included a national science prize.","exampleCN":"她的学业成就包括一项全国科学奖。","why":"the phrase also carries the older sense of achievement as a feat, so it can name a single honour rather than a score.","whyCN":"这个短语还带着 achievement「功业」的旧义，因此可以指一项荣誉而非一个分数。"},{"no":"03","title":"Research accomplishment","titleCN":"科研上的成就","definition":"the record of research a scholar has produced, judged by publications and grants","definitionCN":"以论文与经费衡量的研究者成果记录","example":"The department reviews academic achievement through publications.","exampleCN":"该系通过发表成果来评议科研成就。","why":"inside universities the phrase shifts from students to staff, and achievement then means published work rather than examination marks.","whyCN":"在大学内部，这个短语从学生转到教师，achievement 也就指已发表的工作而非考试分数。"},{"no":"04","title":"An attainment level for comparison","titleCN":"用于比较的 attainment 水平","definition":"a standard measure that lets schools or regions be set side by side","definitionCN":"使学校或地区可以并排比较的标准化衡量","example":"The report compares academic achievement across districts.","exampleCN":"报告比较了各学区的学业水平。","why":"measurement makes the phrase political: once results are comparable, they become a ranking of places as well as of pupils.","whyCN":"可测量性使这个短语政治化：结果一旦可比较，它就不只是学生的排名，也成了地区的排名。"},{"no":"05","title":"The achievement gap","titleCN":"学业成就差距","definition":"the persistent difference in results between groups of students","definitionCN":"不同学生群体之间持续存在的成绩差异","example":"The district targeted the academic achievement gap in reading.","exampleCN":"该学区把阅读方面的学业差距作为重点。","why":"the phrase is often used in a compound with gap, where the focus moves from one pupil's result to a difference between groups.","whyCN":"这个短语常与「差距」构成复合形式，焦点于是从单个学生的成绩转到群体之间的差异。"},{"no":"06","title":"Honours and recognition","titleCN":"荣誉与表彰","definition":"public recognition of scholarly work, such as scholarships or awards","definitionCN":"对学业成果的公开认可，如奖学金或奖项","example":"A scholarship recognised her academic achievement in mathematics.","exampleCN":"一项奖学金表彰了她在数学上的学业成就。","why":"recognition is achievement as a social fact: someone else has judged the work and said so publicly.","whyCN":"表彰使成就成为社会事实：由他人评判并公开说出。"},{"no":"07","title":"Progress over time","titleCN":"一段时间内的进步","definition":"the growth in a student's learning measured from one point to another","definitionCN":"从某一时点到另一时点所测得的学业增长","example":"The chart tracks academic achievement from year to year.","exampleCN":"这张图逐年追踪学业进步。","why":"growth adds a time axis, so the same phrase can praise improvement even when the absolute score stays modest.","whyCN":"加入时间轴之后，同一个短语即使在绝对分数不高时也能表彰进步。"},{"no":"08","title":"Learning beyond scores","titleCN":"分数之外的成长","definition":"the wider development of a learner, including curiosity, method and independence","definitionCN":"学习者更广的发展，包括好奇心、方法与独立性","example":"The school counts curiosity as part of academic achievement.","exampleCN":"这所学校把好奇心也算作学业成就的一部分。","why":"the broad sense pushes back against measurement, insisting that what is learned includes habits that no paper can capture.","whyCN":"宽义是对测量的反弹，坚持所学之中包含纸笔无法捕捉的习惯。"}],"etymology":{"intro":{"en":"The phrase joins academic, from Greek Akadēmeia, the garden where Plato taught, and achievement, from Old French achever 'to finish', literally 'to come to a head'. Dates are approximate.","cn":"这个短语由 academic 与 achievement 组成。academic 来自希腊 Akadēmeia，即柏拉图讲学的那座园林；achievement 来自古法语 achever「完成」，字面意思是「到达头部」。年代为约数。"},"items":[{"era":"GREEK AKADEMEIA","en":"Akadēmeia was the name of the grove outside Athens where Plato taught; it was named after a local hero, Akadēmos.","cn":"Akadēmeia 是雅典城外柏拉图讲学的那片园林之名，得名于当地一位英雄 Akadēmos。"},{"era":"LATIN ACADEMICUS","en":"Latin academicus meant 'of the Academy', and English academic first described the school of Plato before widening to universities in general.","cn":"拉丁 academicus 意为「学园的」，英语 academic 最初指柏拉图的学园，后来扩展到泛指大学。"},{"era":"OLD FRENCH ACHEVER","en":"Achever 'to finish' came from the phrase a chief 'to a head', built on Latin caput 'head'. To achieve was to bring something to its head, that is, to completion.","cn":"achever「完成」来自古法语短语，字面义为「到达头部」，其词根是拉丁 caput「头」。achieve 即把某事做到头，也就是完成。"},{"era":"MIDDLE ENGLISH","en":"Both words settled in English by the fourteenth and fifteenth centuries, academic as an adjective of the schools and achievement as the act of finishing.","cn":"两个词在十四、十五世纪先后进入英语：academic 是学校的形容词，achievement 是完成的行为。"},{"era":"EDUCATIONAL PHRASE","en":"From the nineteenth century, as mass schooling spread, the two words were paired to name a pupil's measured results, and the phrase became standard in reports.","cn":"十九世纪大众教育普及后，两词被组合起来指学生可测量的成绩，这个短语遂成为报告中的标准说法。"},{"era":"SOURCE UNCERTAIN","en":"The origin of the name Akadēmos is uncertain; proposals linking it to a district name or to a personal name are hypotheses. The deeper pre-Latin origin of caput is also unsettled, and forms offered for it are reconstructions.","cn":"Akadēmos 这个名字的来源不确定；把它与某个地名或人名相联的说法均属假说。caput 在拉丁语之前的更深来源亦无定论，为其给出的形式属重构形式。"}]},"similar":{"note":{"en":"Group one holds the school-root family and its look-alikes; group two holds words for results and attainment, each measuring a slightly different thing.","cn":"第一组是「学园」词根的词族与形近词；第二组是表示成绩与水平的词，各自衡量的东西略有不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"academy","ipa":"/əˈkædəmi/","tag":"the institution","definition":"A learned society or school; it shares the Greek name but names a body, not a result.","definitionCN":"指学术团体或学校，与希腊原名同源，但指机构而非成绩。"},{"word":"academic","ipa":"/ˌækəˈdemɪk/","tag":"the adjective","definition":"Describes study or a teacher; alone it says nothing about how well anyone did.","definitionCN":"描述学业或教师，单用并不说明成绩好坏。"},{"word":"academia","ipa":"/əˈkædəmiə/","tag":"the world of scholars","definition":"The collective world of universities and research, a place rather than a measure.","definitionCN":"指大学与研究的整体世界，是场所而非衡量。"},{"word":"academician","ipa":"/əˌkædəˈmɪʃən/","tag":"the member","definition":"A member of a learned academy, a title rather than a score.","definitionCN":"指学术团体的成员，是头衔而非分数。"}]},{"heading":"NEAR MEANING","entries":[{"word":"attainment","ipa":"/əˈteɪnmənt/","tag":"level reached","definition":"The standard reached in a subject, common in British school reporting; it is close to the score sense.","definitionCN":"指在某学科达到的水平，常用于英国学校报告，接近分数义。"},{"word":"performance","ipa":"/pəˈfɔːməns/","tag":"how one does","definition":"How well someone carries out a task, which may be judged by observation rather than papers.","definitionCN":"指完成任务的表现，可能靠观察而非纸笔评判。"},{"word":"learning outcome","ipa":"/ˈlɜːnɪŋ ˈaʊtkʌm/","tag":"what was learned","definition":"A stated result of a course, often broader than a single grade.","definitionCN":"指课程设定的学习结果，通常比单一分数更宽。"},{"word":"scholastic record","ipa":"/skəˈlæstɪk ˈrekɔːd/","tag":"the paper trail","definition":"The accumulated file of marks and reports, rather than the achievement itself.","definitionCN":"指积累起来的分数与报告档案，而非成就本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations here are the two real source words, their real history and the real settings in which the phrase appears.","cn":"正常联想取自两个真实来源词、它们真实的历史，以及这个短语真实出现的场合。"},"normal":[{"en":"Akadēmeia was a garden of learning, so academic points back to a place.","cn":"Akadēmeia 是一座求学园林，因此 academic 指向一个场所。"},{"en":"a chief 'to a head' gave achieve: to bring work to completion.","cn":"古法语短语「到达头部」造出 achieve：把工作做到完成。"},{"en":"Fixed phrases mark measurement: achievement scores, achievement gap, achievement standards.","cn":"固定搭配标出测量：成绩分数、成就差距、成就标准。"},{"en":"The phrase pairs with verbs of change: improve, raise, measure, close the gap.","cn":"这个短语常与变化类动词连用：提高、拉升、衡量、缩小差距。"},{"en":"Reports use it with comparisons: across districts, over time, between groups.","cn":"报告用它作比较：跨学区、随时间、在群体之间。"}],"abstract":[{"en":"Picture a line drawn upward on a wall chart while the corridor stays exactly the same.","cn":"想象墙图上的线在上升，而走廊本身毫无变化。"},{"en":"Picture a stack of exercise books standing as tall as the child who filled them.","cn":"想象一摞作业本，高度抵得上写它的那个孩子。"},{"en":"Picture a single prize medal lying on top of a thick file of reports.","cn":"想象一枚奖牌搁在厚厚一叠报告上。"}]},"examples":[{"en":"The programme raised academic achievement among first-year students.","cn":"该计划提高了新生的学业成绩。"},{"en":"Academic achievement is one measure of a school, not the only one.","cn":"学业成绩是衡量学校的一项指标，而非唯一指标。"},{"en":"Researchers studied the academic achievement gap between language groups.","cn":"研究者考察了不同语言群体之间的学业差距。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「academic（学业的）+ achievement（达成）」——在学业上达成的东西 → 学业成就、学习成绩","word":"academic achievement"},"root":"希腊 Akadēmeia（柏拉图讲学的园林，得名于 Akadēmos）→ 拉丁 academicus「学园的」→ 英语 academic；拉丁 caput「头」→ 古法语短语（字面义「到达头部」）→ achever「完成」→ 英语 achieve／achievement。Akadēmos 之名与 caput 的更早来源均不确定。","sensesIntro":{"en":"Eight senses describe one measured climb: learning is finished and shown, then the showing becomes an honour, a research record, a comparable number, a gap, a public recognition, a curve over time and finally a claim that some growth cannot be scored.","cn":"八个义项描述同一条被测量的攀升：学习被完成并显现，显现随后变成荣誉、科研记录、可比较的数字、差距、公开表彰、时间曲线，最后变成一句主张——有些成长无法打分。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wall chart rising year by year above a stack of completed exercise books.","cn":"核心意象：一张逐年上升的墙图，悬在一摞已完成的作业本上方。"},"chain":["LEARNING","COMPLETION","SCORE","COMPARISON","RECOGNITION","GROWTH"],"branches":[{"senses":"01 · 02","en":"WORK AND HONOUR: finished learning shows as marks, and an especially finished piece shows as a prize.","cn":"学业与荣誉：完成的学习表现为分数，格外出色的一件则表现为奖项。"},{"senses":"03 · 04","en":"STAFF AND SCALE: the same phrase judges publications, then turns results into comparable numbers.","cn":"教师与规模：同一短语先评论文，再把结果变成可比较的数字。"},{"senses":"05","en":"THE GAP: comparison hardens into a persistent difference between groups.","cn":"差距：比较硬化成群体之间持续存在的差异。"},{"senses":"06 · 07","en":"TWO KINDS OF TIME: a public award fixes one moment, a chart records many.","cn":"两种时间：公开奖项固定一个时刻，折线图记录许多时刻。"},{"senses":"08","en":"THE LIMIT: the broad sense insists that curiosity and method never fit a single score.","cn":"限度：宽义坚持好奇心与方法无法塞进一个分数。"}]},"affixes":{"intro":{"en":"The phrase is two whole words, each with a real root and suffix history, and each root also builds a family of English words.","cn":"这个短语是两个完整的词，各有一个真实的词根与后缀史，每个词根又各造出一族英语词。"},"latinIntro":{"en":"Greek Akadēmeia and Latin academicus supply the first word; Latin caput, through Old French, supplies the second.","cn":"希腊 Akadēmeia 与拉丁 academicus 提供第一个词；拉丁 caput 经古法语提供第二个词。"},"items":[{"word":"Akadēmeia","structure":"Greek proper noun","meaning":"the grove where Plato taught","meaningCN":"柏拉图讲学的园林","example":"Akadēmeia is the origin of academic.","exampleCN":"Akadēmeia 是 academic 的来源。"},{"word":"academicus","structure":"Latin adjective","meaning":"of the Academy","meaningCN":"学园的","example":"Academicus entered English as academic.","exampleCN":"academicus 进入英语作 academic。"},{"word":"academic","structure":"academicus through French","meaning":"of study or a school","meaningCN":"学业或学校的","example":"The adjective precedes the phrase.","exampleCN":"这个形容词先于短语存在。"},{"word":"academy","structure":"Akadēmeia through Latin and French","meaning":"a learned body","meaningCN":"学术团体","example":"The academy elected her a member.","exampleCN":"该学会选她为成员。"},{"word":"caput","structure":"Latin noun, third declension","meaning":"head","meaningCN":"头","example":"Caput is the root of achieve.","exampleCN":"caput 是 achieve 的根。"},{"word":"achever","structure":"Old French verb, 'to come to a head'","meaning":"to finish","meaningCN":"完成","example":"Achever became English achieve.","exampleCN":"achever 变成英语 achieve。"},{"word":"achieve","structure":"achever through Middle English","meaning":"to bring to completion","meaningCN":"做到；完成","example":"She achieved a high score.","exampleCN":"她取得了高分。"},{"word":"achievement","structure":"achieve + -ment (result)","meaning":"a completed result","meaningCN":"完成的成果","example":"The phrase centers on the result.","exampleCN":"短语以成果为中心。"},{"word":"achievable","structure":"achieve + -able (can be)","meaning":"able to be reached","meaningCN":"可达到的","example":"The target is achievable.","exampleCN":"这个目标可以达到。"}],"latinEntries":[{"word":"Akadēmeia","structure":"Akadēmeia (Greek proper noun, first declension)","meaning":"the grove of the Academy","meaningCN":"学园园林"},{"word":"academicus","structure":"academicus, academica, academicum (adj.)","meaning":"of the Academy","meaningCN":"学园的"},{"word":"caput","structure":"caput, capitis (n., third declension)","meaning":"head","meaningCN":"头"}],"derivatives":[{"word":"academy","pos":"n.","zh":"学院；研究院"},{"word":"academic","pos":"adj./n.","zh":"学术的；大学教师"},{"word":"academically","pos":"adv.","zh":"学业上"},{"word":"academician","pos":"n.","zh":"院士"},{"word":"achieve","pos":"v.","zh":"取得；达到"},{"word":"achievable","pos":"adj.","zh":"可实现的"}]}},{"word":"performance assessment","ipa_uk":"/pəˈfɔːməns əˈsesmənt/","ipa_us":"/pərˈfɔːrməns əˈsesmənt/","definition_zh":"表现性评价；绩效评估","definition_en":"the judging of someone's work by watching or reviewing what they actually do, rather than only by written tests","core_image":"一间排练厅里有人当场演奏，几位评委在表格上逐项勾选","scene":"乐团招新不再只看笔试，而让每位报名者当场演奏一段，再由评委逐项记录。The panel completed a performance assessment of every candidate.","sceneCN":"乐团让报名者当场演奏、评委逐项记录；句中的 performance assessment 指「依据实际完成的任务来评判」（第 1 个义项：以真实表现而非纸笔测验为证据）。图中可辨识物件：排练厅、乐谱架、评分表、计时器。","pos":[{"tag":"n.","zh":"表现性评价；绩效评估"}],"collocations":[{"phrase":"performance assessment rubric","zh":"表现性评价量表"},{"phrase":"performance-based assessment","zh":"基于表现的评价"},{"phrase":"employee performance assessment","zh":"员工绩效评估"},{"phrase":"performance assessment system","zh":"绩效评估体系"},{"phrase":"performance assessment criteria","zh":"绩效评估标准"},{"phrase":"annual performance assessment","zh":"年度绩效评估"}],"forms":[{"label":"复数","form":"performance assessments"},{"label":"定语用法","form":"performance assessment results"},{"label":"同义变体","form":"performance-based assessment"}],"derivatives":[{"word":"perform","pos":"v.","zh":"表演；执行"},{"word":"performance","pos":"n.","zh":"表现；演出；绩效"},{"word":"performer","pos":"n.","zh":"表演者"},{"word":"assess","pos":"v.","zh":"评估"},{"word":"assessment","pos":"n.","zh":"评估"},{"word":"assessor","pos":"n.","zh":"评估员"},{"word":"assessable","pos":"adj.","zh":"可评估的"}],"senses":[{"no":"01","title":"Judging what someone actually does","titleCN":"以实际完成的任务来评判","definition":"the judging of work by observing a real task rather than only by a written paper","definitionCN":"通过观察真实任务来评判，而非只看笔试","example":"The panel completed a performance assessment of every candidate.","exampleCN":"评审组对每位候选人完成了表现性评价。","why":"performance names what is carried out, and assessment names the sitting beside a case to judge it, so the phrase judges the doing itself.","whyCN":"performance 指实际执行出来的东西，assessment 指坐到案例旁边作判断，因此这个短语评判的是「做」本身。"},{"no":"02","title":"Workplace appraisal","titleCN":"员工绩效评估","definition":"the periodic review of an employee's results, conduct and targets","definitionCN":"对员工成果、行为与目标的定期评议","example":"Her annual performance assessment cited three completed projects.","exampleCN":"她的年度绩效评估提到三个已完成的项目。","why":"employers borrowed the phrase because output is visible at work, and a review must rest on what was delivered.","whyCN":"雇主借用这个短语，因为工作产出一目了然，而评议必须落在实际交付的东西上。"},{"no":"03","title":"Judging an art or a sport","titleCN":"艺术与竞技的现场评判","definition":"the scoring of a recital, a match or a display by trained judges","definitionCN":"由受过训练的评委对演奏、比赛或展示打分","example":"The festival's performance assessment rewards stage presence as well as accuracy.","exampleCN":"该音乐节的表现评价既看准确度，也看舞台感染力。","why":"the arts kept the most literal sense: the work exists only while it is being performed, so the judgement must happen in that moment.","whyCN":"艺术保留了最字面的意义：作品只在被表演的当下存在，因此评判必须发生在那一刻。"},{"no":"04","title":"Rubric-based classroom assessment","titleCN":"量规式的课堂评价","definition":"the marking of student work against stated criteria for a real task","definitionCN":"按公开标准对真实任务中的学生作品评分","example":"Teachers use a performance assessment rubric for the science fair.","exampleCN":"教师用表现性评价量表给科学展评分。","why":"education added rubric and task: the point is that criteria are public and the task is authentic, not that the paper is long.","whyCN":"教育领域加上「量规」与「任务」：重点在于标准公开、任务真实，而不在于卷子有多长。"},{"no":"05","title":"System accountability","titleCN":"学校或系统的问责评估","definition":"the use of measured results to judge whether a school or service is doing its job","definitionCN":"用测量结果判断学校或公共服务是否尽责","example":"The inspectorate published a performance assessment of each district.","exampleCN":"督学机构公布了各学区的绩效评估。","why":"when the unit of judgement rises from a person to an institution, the phrase becomes an instrument of public accountability.","whyCN":"当评判单位从个人上升到机构，这个短语就成为公共问责的工具。"},{"no":"06","title":"A diagnostic review","titleCN":"诊断性复查","definition":"a close review of how a process has worked, used to find where to improve","definitionCN":"细查某流程的实际运转，以找出改进之处","example":"The team ran a performance assessment of the booking system.","exampleCN":"团队对预约系统做了一次绩效复查。","why":"diagnosis shifts the purpose from reward to repair: the same evidence is read for weak points rather than for a grade.","whyCN":"诊断把目的从奖赏转为修补：同样的证据被用来找薄弱处，而不是定等级。"},{"no":"07","title":"Judging a machine or device","titleCN":"设备性能评估","definition":"the measurement of how well a device or system meets stated targets","definitionCN":"衡量设备或系统达成既定指标的程度","example":"Engineers finished the performance assessment of the new pump.","exampleCN":"工程师完成了新泵的性能评估。","why":"machines extend the word beyond people: a pump also performs, and its performance is judged against a specification.","whyCN":"机器把这个词扩展到人之外：泵也在「表现」，其表现按规格被评判。"},{"no":"08","title":"Authentic assessment","titleCN":"真实性评价","definition":"judging learning through tasks that resemble real work outside school","definitionCN":"用接近校外真实工作的任务来评判学习","example":"The internship ends with a performance assessment in a real clinic.","exampleCN":"实习以在真实诊所中的表现性评价收尾。","why":"the authentic sense makes the task itself the evidence, which is why the phrase is often paired with real settings.","whyCN":"真实性义让任务本身成为证据，因此这个短语常与真实场景并提。"}],"etymology":{"intro":{"en":"The phrase joins performance, from Old French parformance 'a carrying out', and assessment, from Latin assidere 'to sit beside', the verb behind a tax official who sat beside a case to fix its value. Dates are approximate.","cn":"这个短语由 performance 与 assessment 组成。performance 来自古法语 parformance「执行、完成」；assessment 来自拉丁 assidere「坐在旁边」，即税务官坐在案旁核定价值所用之词。年代为约数。"},"items":[{"era":"OLD FRENCH PARFOURNIR","en":"Parfournir meant 'to complete, to carry out fully', built from par- 'thoroughly' and fournir 'to provide'. The noun parformance named the carrying out.","cn":"parfournir 意为「完成、彻底执行」，由 par-「彻底」与 fournir「提供」构成；名词 parformance 指执行这件事。"},{"era":"ENGLISH PERFORM","en":"English took perform in the sixteenth century, first as 'to carry out a task' and soon after as 'to act before an audience'.","cn":"英语在十六世纪吸收 perform，最初指「执行任务」，不久又指「在观众面前表演」。"},{"era":"LATIN ASSIDERE","en":"Assidere combined ad- 'to' with sedere 'to sit' and meant 'to sit beside'. Tax officials used it for sitting beside a case to set its value.","cn":"assidere 由 ad-「向」与 sedere「坐」构成，意为「坐在旁边」。税务官用它指坐到案旁核定价值。"},{"era":"ASSESSMENT","en":"English assessment appeared in the sixteenth century for the fixing of a tax or a value, and only later widened to any judgement of worth.","cn":"英语 assessment 于十六世纪出现，指核定税额或价值，后来才扩展到对任何价值的判断。"},{"era":"EDUCATIONAL USE","en":"In the twentieth century the two words were paired in education, where a task performed under observation replaced or supplemented the written paper.","cn":"二十世纪，两词在教育领域组合起来，指以观察下的实际任务取代或补充纸笔测验。"},{"era":"SOURCE UNCERTAIN","en":"The Frankish origin of fournir is generally accepted but its exact pre-Old-French form is reconstructed; the precise route by which assidere moved from sitting to valuing is not fully documented.","cn":"fournir 的弗兰克语来源一般认为是可靠的，但其古法语之前的确切形式属重构；assidere 从「坐」到「估值」的确切演变路径缺乏完整记录。"}]},"similar":{"note":{"en":"Group one holds the two component nouns and their verb; group two holds neighbouring judgement words that differ in what evidence they accept.","cn":"第一组是组成短语的两个名词及其动词；第二组是相邻的评判词，区别在于接受何种证据。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"performance","ipa":"/pəˈfɔːməns/","tag":"the doing","definition":"The carrying out or the show itself; assessment is the judgement passed on it.","definitionCN":"指执行或演出本身；assessment 则是对它的评判。"},{"word":"assessment","ipa":"/əˈsesmənt/","tag":"the judgement","definition":"Any judgement of value or quality, which may rest on a paper alone.","definitionCN":"对价值或质量的判断，可只凭一份纸面材料作出。"},{"word":"perform","ipa":"/pəˈfɔːm/","tag":"the verb","definition":"To carry out or act; it names the activity being judged.","definitionCN":"执行或表演；它指出被评判的活动。"},{"word":"assessor","ipa":"/əˈsesə/","tag":"the judge","definition":"The person who makes the judgement, a role rather than the judgement itself.","definitionCN":"作出评判的人，是角色而非判断本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"appraisal","ipa":"/əˈpreɪzəl/","tag":"value and price","definition":"Often about worth or cost, and common in staff reviews; it does not insist on an observed task.","definitionCN":"常关于价值或成本，多用于员工评议；不强调现场任务。"},{"word":"authentic assessment","ipa":"/ɔːˈθentɪk əˈsesmənt/","tag":"real-world task","definition":"A close relative that stresses the task resembles real work; performance assessment stresses the doing.","definitionCN":"近亲词，强调任务接近真实工作；performance assessment 强调「做」本身。"},{"word":"evaluation","ipa":"/ˌiːvæljuˈeɪʃən/","tag":"broad judgement","definition":"The widest word for judging a programme or person against goals, by any evidence.","definitionCN":"最宽的评判词，用任何证据对照目标评判项目或人。"},{"word":"testing","ipa":"/ˈtestɪŋ/","tag":"paper and score","definition":"Specifically the use of set tests; the phrase performance assessment is defined partly against it.","definitionCN":"特指使用既定测验；表现性评价部分正是相对它而定义的。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations here are the two real halves, their real French and Latin sources, and the real rooms where such judgements happen.","cn":"正常联想取自短语真实的两半、它们真实的法语与拉丁来源，以及这类评判真实发生的场所。"},"normal":[{"en":"parfournir 'to complete' gave perform; assidere 'to sit beside' gave assess.","cn":"parfournir「完成」造出 perform；assidere「坐在旁边」造出 assess。"},{"en":"A performance is what is done; an assessment is the judge sitting beside it.","cn":"performance 是被做出来的东西；assessment 是坐在它旁边的评判者。"},{"en":"Fixed phrases mark the setting: performance assessment rubric, employee performance assessment, annual performance assessment.","cn":"固定搭配标出场景：表现性评价量表、员工绩效评估、年度绩效评估。"},{"en":"The phrase contrasts with written testing, so it often pairs with task, project, portfolio.","cn":"这个短语与笔试相对，因而常与任务、项目、作品集并提。"},{"en":"In engineering the same phrase checks a device against its specification.","cn":"在工程领域，同一短语按规格检验设备。"}],"abstract":[{"en":"Picture a judge's chair pulled up beside a stage, not beside a desk.","cn":"想象一把评委椅被拉到舞台旁，而不是书桌旁。"},{"en":"Picture a score sheet with boxes for things that can only be seen while they happen.","cn":"想象一张评分表，格子对应只能在发生时看见的东西。"},{"en":"Picture a pump on a test bench with a clipboard hanging from its valve.","cn":"想象泵在试验台上，阀上挂着记录板。"}]},"examples":[{"en":"The course replaces one written exam with a performance assessment.","cn":"该课程用表现性评价取代一次笔试。"},{"en":"Managers were trained to conduct a fair performance assessment.","cn":"管理者接受了公平绩效评估的培训。"},{"en":"The audit included a performance assessment of the heating system.","cn":"审计包含对供暖系统的性能评估。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「performance（表现）+ assessment（评估）」——看实际表现来评 → 表现性评价、绩效评估","word":"performance assessment"},"root":"古法语 par-「彻底」+ fournir「提供」→ parfournir「完成」→ 英语 perform／performance；拉丁 ad-「向」+ sedere「坐」→ assidere「坐在旁边」→ 英语 assess／assessment。fournir 的古法语之前形式属重构；assidere 从「坐」到「估值」的路径记录不全。","sensesIntro":{"en":"Eight senses keep one scene: a judge sits beside an actual doing and marks it, and the doing can be a recital, a job, a rubric task, a school system, a broken process, a machine or an internship.","cn":"八个义项共用一幕：评判者坐在一件真实的「做」旁边给它打分，而这件事可以是演奏、工作、课堂任务、学校系统、出问题的流程、机器或实习。"},"semanticMap":{"core":{"en":"CORE IMAGE: a chair pulled up beside a stage or a workbench, with a score sheet balanced on the knee.","cn":"核心意象：一把椅子被拉到舞台或工作台旁，评分表搁在膝上。"},"chain":["ACT","OBSERVE","CRITERIA","SCORE","REVIEW","IMPROVE"],"branches":[{"senses":"01 · 03","en":"THE DOING: a candidate plays and an artist performs, and the judgement must happen while it lasts.","cn":"做：候选人演奏、艺术家表演，评判必须在它持续时发生。"},{"senses":"02","en":"THE JOB: at work the doing is a delivered project, reviewed after the fact.","cn":"工作：在职场，这件「做」是已交付的项目，事后评议。"},{"senses":"04 · 08","en":"THE TASK: a rubric makes criteria public, and a real setting makes the task authentic.","cn":"任务：量规让标准公开，真实场景让任务可信。"},{"senses":"05","en":"THE INSTITUTION: the unit of judgement rises from a person to a school or a service.","cn":"机构：评判单位从个人上升到学校或公共服务。"},{"senses":"06 · 07","en":"REPAIR AND SPECIFICATION: a process is reviewed to find faults, a device is measured against a target.","cn":"修补与规格：流程被复查以找出毛病，设备按指标被测量。"}]},"affixes":{"intro":{"en":"The phrase is two whole nouns, each built from a prefix and a root, and each half also builds a working family of English words.","cn":"这个短语是两个完整的名词，各由前缀与词根构成，每一半又各造出一族在用的英语词。"},"latinIntro":{"en":"Old French par- and fournir supply performance; Latin ad- and sedere supply assess and assessment.","cn":"古法语 par- 与 fournir 提供 performance；拉丁 ad- 与 sedere 提供 assess 与 assessment。"},"items":[{"word":"par-","structure":"Old French prefix, 'thoroughly'","meaning":"completely","meaningCN":"彻底","example":"The prefix intensifies the carrying out.","exampleCN":"这个前缀强化「执行」这一动作。"},{"word":"fournir","structure":"Old French verb, Frankish origin","meaning":"to provide, supply","meaningCN":"提供；供给","example":"Fournir is the root of perform.","exampleCN":"fournir 是 perform 的根。"},{"word":"perform","structure":"parfournir through Anglo-Norman","meaning":"to carry out; to act","meaningCN":"执行；表演","example":"Perform entered English in the sixteenth century.","exampleCN":"perform 于十六世纪进入英语。"},{"word":"performance","structure":"perform + -ance (act or result)","meaning":"a carrying out; a show","meaningCN":"执行；演出；表现","example":"Performance is the first half of the phrase.","exampleCN":"performance 是短语的前半。"},{"word":"ad-","structure":"Latin prefix, 'to, toward'","meaning":"to; beside","meaningCN":"向；在旁边","example":"The prefix points the sitting toward the case.","exampleCN":"这个前缀把「坐」指向案件。"},{"word":"sedere","structure":"Latin verb, second conjugation","meaning":"to sit","meaningCN":"坐","example":"Sedere is the root of assess.","exampleCN":"sedere 是 assess 的根。"},{"word":"assess","structure":"assidere through Old French","meaning":"to sit beside and fix a value","meaningCN":"坐旁核定价值","example":"Officials assessed the land.","exampleCN":"官员核定了土地价值。"},{"word":"assessment","structure":"assess + -ment (result)","meaning":"a judgement of value","meaningCN":"对价值的判断","example":"Assessment is the second half of the phrase.","exampleCN":"assessment 是短语的后半。"},{"word":"assessor","structure":"assess + -or (one who)","meaning":"one who judges value","meaningCN":"评估价值的人","example":"The assessor signed the report.","exampleCN":"评估员签署了报告。"}],"latinEntries":[{"word":"fournir","structure":"fournir (Old French verb, Frankish origin)","meaning":"to provide, supply","meaningCN":"提供；供给"},{"word":"sedere","structure":"sedere, sedi, sessum (verb, second conjugation)","meaning":"to sit","meaningCN":"坐"},{"word":"assidere","structure":"assidere, assedi, assessum (verb, third conjugation)","meaning":"to sit beside","meaningCN":"坐在旁边"}],"derivatives":[{"word":"perform","pos":"v.","zh":"表演；执行"},{"word":"performance","pos":"n.","zh":"表现；演出；绩效"},{"word":"performer","pos":"n.","zh":"表演者"},{"word":"assess","pos":"v.","zh":"评估"},{"word":"assessment","pos":"n.","zh":"评估"},{"word":"assessor","pos":"n.","zh":"评估员"}]}},{"word":"proficiency","ipa_uk":"/prəˈfɪʃənsi/","ipa_us":"/prəˈfɪʃənsi/","definition_zh":"熟练程度；精通；语言水平","definition_en":"a high level of skill or command in a subject or activity, especially in a language","core_image":"一位口译员在隔间里边听边译，耳机旁摆着一份评分表","scene":"一位译员在隔间里边听边译，术语与语速都没能拖住他。Her proficiency in two languages won her the post.","sceneCN":"译员在隔间里边听边译，术语与语速都没拖住她；句中的 proficiency 指「语言上达到的高水平运用能力」（第 1 个义项：对语言的熟练掌控）。图中可辨识物件：隔间、耳机、评分表、术语本。","pos":[{"tag":"n.","zh":"熟练程度；精通；（语言的）水平"}],"collocations":[{"phrase":"language proficiency","zh":"语言水平"},{"phrase":"proficiency test","zh":"水平测试"},{"phrase":"proficiency level","zh":"熟练等级"},{"phrase":"demonstrate proficiency","zh":"显示出熟练"},{"phrase":"proficiency in","zh":"在……方面的熟练"},{"phrase":"technical proficiency","zh":"技术熟练度"}],"forms":[{"label":"复数","form":"proficiencies"},{"label":"形容词","form":"proficient"},{"label":"副词","form":"proficiently"},{"label":"比较级（形容词）","form":"more proficient"}],"derivatives":[{"word":"proficient","pos":"adj./n.","zh":"熟练的；能手"},{"word":"proficiently","pos":"adv.","zh":"熟练地"}],"senses":[{"no":"01","title":"Command of a language","titleCN":"对语言的熟练掌控","definition":"the ability to use a language accurately and fluently for real purposes","definitionCN":"为实际目的准确而流畅地使用一种语言的能力","example":"Her proficiency in two languages won her the post.","exampleCN":"她两种语言都熟练，因此赢得了这个职位。","why":"proficere meant 'to make progress', so proficiency measures how far someone has advanced in a skill rather than how long they have studied it.","whyCN":"proficere 意为「取得进展」，因此 proficiency 衡量的是一个人在技能上走到多远，而非学了多久。"},{"no":"02","title":"High skill in a field","titleCN":"某一领域的高水平技能","definition":"a strong working command of a subject such as law, music or surgery","definitionCN":"在法律、音乐或外科等领域具备扎实的实操能力","example":"The post requires proficiency in statistics.","exampleCN":"这个职位要求统计方面的熟练能力。","why":"the word moved from language to any practised field, because every field has a level at which a person can work unaided.","whyCN":"这个词从语言扩展到任何需要练习的领域，因为每个领域都有一个人可以独立工作的水平线。"},{"no":"03","title":"A measured level on a scale","titleCN":"按等级量表测出的水平","definition":"a score or band that places a learner at a defined stage","definitionCN":"把学习者放入某个明确阶段的分数或等级","example":"She reached the upper proficiency band after one year.","exampleCN":"一年后她达到了较高的水平等级。","why":"testing turned advancement into a rung: once a scale exists, proficiency can be reported as a band rather than a vague compliment.","whyCN":"测试把「进展」变成一级台阶：量表一旦存在，水平就能报成一个等级，而不只是模糊的称赞。"},{"no":"04","title":"Mastery gained by practice","titleCN":"经练习获得的熟练","definition":"the fluency that comes from repeated use rather than from native origin","definitionCN":"由反复使用而非母语出身带来的流畅","example":"His proficiency came from years of night shifts in the emergency room.","exampleCN":"他的熟练来自急诊室里多年的夜班。","why":"because proficiency is progress, it belongs to learners: a native speaker has a language, but proficiency is what practice earns.","whyCN":"因为 proficiency 是「进展」，它属于学习者：母语者拥有一种语言，而熟练是练习挣来的。"},{"no":"05","title":"A professional standard","titleCN":"职业上的能力标准","definition":"the level a profession sets before someone may practise independently","definitionCN":"行业规定的、可以独立执业前必须达到的水平","example":"The board checks proficiency before issuing a licence.","exampleCN":"委员会在发执照前核查专业能力。","why":"professions need a threshold, and proficiency supplies the neutral word for it without claiming excellence.","whyCN":"行业需要一个门槛，proficiency 正好提供这个中性词，而不宣称卓越。"},{"no":"06","title":"Operational skill with tools","titleCN":"使用工具与仪器的熟练","definition":"the practised ability to handle an instrument or a technique","definitionCN":"操作仪器或运用技法的熟练能力","example":"The technician showed proficiency with the laser cutter.","exampleCN":"这位技师表现出使用激光切割机的熟练度。","why":"skill with a tool is progress made visible in the hands, which is why the word fits craft and laboratory work.","whyCN":"使用工具的技艺是显现在手上的进展，因此这个词也适合手艺与实验工作。"},{"no":"07","title":"A limited degree of skill","titleCN":"有限的熟练程度","definition":"a modest working ability, enough for simple tasks but not for complex ones","definitionCN":"足以应付简单任务、不足以应付复杂任务的有限能力","example":"The form asks applicants to state their proficiency in each language.","exampleCN":"表格要求申请人写明每种语言的熟练程度。","why":"proficiency is gradable, so a form can ask for it without implying mastery; the scale runs from limited to full.","whyCN":"proficiency 可分等级，因此表格可以询问它而不暗示精通；量表从有限到完全都能排。"},{"no":"08","title":"A certified level for study","titleCN":"为求学或工作认证的水平","definition":"an officially recorded level accepted by a university or an employer","definitionCN":"被大学或雇主接受的、正式记录在案的水平","example":"The university accepts a proficiency certificate instead of an entrance test.","exampleCN":"这所大学接受水平证书以替代入学测试。","why":"institutions need portable evidence, so proficiency became something a certificate can carry between countries.","whyCN":"机构需要可携带的证据，于是 proficiency 变成一张能在国家之间携带的证书。"}],"etymology":{"intro":{"en":"Proficiency is proficient plus -ency. Proficient comes from Latin proficere 'to make progress, accomplish', built on pro- 'forward' and facere 'to do, make'. Dates are approximate.","cn":"proficiency 由 proficient 加名词后缀构成。proficient 来自拉丁 proficere「取得进展、完成」，由 pro-「向前」与 facere「做、造」构成。年代为约数。"},"items":[{"era":"LATIN FACERE","en":"Facere meant 'to do, make, bring about'. It is one of the most productive roots in English, giving fact, effect, office and dozens of verbs in -fic.","cn":"facere 意为「做、造、促成」，是英语中产量最高的词根之一，给出 fact、effect、office 以及大量由它构成的动词。"},{"era":"LATIN PROFICERE","en":"Pro- 'forward' plus facere produced proficere 'to make progress, to accomplish, to be useful'. The forward prefix is what separates it from plain doing.","cn":"pro-「向前」加 facere 构成 proficere「取得进展、完成、有用」。这个向前的方向正是它与单纯「做」的区别。"},{"era":"LATIN PROFICIENS","en":"The present participle proficiens 'making progress, effective' described a person or thing that gets somewhere.","cn":"现在分词 proficiens「有进展的、有效的」用于描述能走到某处的人或物。"},{"era":"ENGLISH PROFICIENT","en":"English took proficient in the sixteenth century, first as 'useful, advantageous' and soon as 'well advanced in a skill'.","cn":"英语在十六世纪吸收 proficient，最初意为「有用的、有利的」，很快转为「在技能上进展良好的」。"},{"era":"ENGLISH PROFICIENCY","en":"The noun proficiency appeared in the seventeenth century as the state of being proficient; modern testing fixed it to measured language levels in the twentieth century.","cn":"名词 proficiency 于十七世纪出现，指熟练的状态；现代测试在二十世纪把它固定为可测量的语言等级。"},{"era":"SOURCE UNCERTAIN","en":"The deeper origin of facere is generally connected to a root meaning 'to put, set', but the exact chain is reconstructed. The early history of the English -ency noun is also thinly documented.","cn":"facere 的更早来源一般被认为与表示「放置」的词根相关，但确切链条属重构。英语中这个表状态名词的早期历史记录也较单薄。"}]},"similar":{"note":{"en":"Group one holds the same Latin root under different prefixes and a look-alike that means something else; group two holds words for skill, each with a different centre of gravity.","cn":"第一组是同出拉丁词根但前缀不同的词，以及一个形似而义异的词；第二组是表示技能的词，重心各不相同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"proficient","ipa":"/prəˈfɪʃənt/","tag":"the adjective","definition":"The adjective describing the person; proficiency is the noun for the level itself.","definitionCN":"描述人的形容词；proficiency 是表示水平本身的名词。"},{"word":"efficient","ipa":"/ɪˈfɪʃənt/","tag":"same root, other prefix","definition":"From ex- 'out' plus facere: producing a result with little waste, a different idea from being well advanced.","definitionCN":"由 ex-「出」加 facere：以很少耗费产出结果，与「进展良好」不是同一概念。"},{"word":"sufficient","ipa":"/səˈfɪʃənt/","tag":"same root, other prefix","definition":"From sub- 'under' plus facere: enough to meet a need, which is a matter of quantity, not skill.","definitionCN":"由 sub-「在下」加 facere：足以满足需要，关乎数量而非技能。"},{"word":"profit","ipa":"/ˈprɒfɪt/","tag":"look-alike, different route","definition":"Looks close and shares the forward prefix, but comes through French for 'advantage gained', not from the participle of proficere.","definitionCN":"形近且同有向前的前缀，但经法语指「所得利益」，并非来自 proficere 的分词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"fluency","ipa":"/ˈfluːənsi/","tag":"smoothness","definition":"The ease and speed of speech; proficiency also covers accuracy and range, not only smoothness.","definitionCN":"指说话的轻松与速度；proficiency 还涵盖准确度与覆盖面，不只是顺滑。"},{"word":"mastery","ipa":"/ˈmɑːstəri/","tag":"full control","definition":"A higher claim than proficiency: complete control of a field, not merely a working level.","definitionCN":"比 proficiency 更强的说法：对某一领域的完全掌控，而非仅有工作水平。"},{"word":"competence","ipa":"/ˈkɒmpɪtəns/","tag":"enough to do the job","definition":"The threshold of being able to act; proficiency usually implies a level above that threshold.","definitionCN":"指足以行动的门槛；proficiency 通常意味着高于该门槛的水平。"},{"word":"expertise","ipa":"/ˌekspɜːˈtiːz/","tag":"specialist knowledge","definition":"Deep specialist knowledge, often recognized by others; proficiency can be self-measured.","definitionCN":"指深的专门知识，常由他人认可；proficiency 则可由自己测出。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations here are the real Latin steps, the real prefix contrast and the real settings where the noun is used.","cn":"正常联想取自真实的拉丁演变、真实的前缀对照，以及这个名词真实的使用场合。"},"normal":[{"en":"pro- 'forward' plus facere 'do': to be moving forward in what one does.","cn":"pro-「向前」加 facere「做」：在做的事上不断向前。"},{"en":"The same root gives efficient with ex-, sufficient with sub-, and proficiency with pro-.","cn":"同一词根配 ex- 得 efficient，配 sub- 得 sufficient，配 pro- 得 proficiency。"},{"en":"The noun is gradable: limited proficiency, working proficiency, full proficiency.","cn":"这个名词可分等级：有限熟练、工作熟练、完全熟练。"},{"en":"Fixed phrases mark testing: proficiency test, proficiency level, language proficiency.","cn":"固定搭配标出测试场景：水平测试、熟练等级、语言水平。"},{"en":"The word belongs to learners, not to native origin: practice produces it.","cn":"这个词属于学习者，而不属于母语出身：练习才产出它。"}],"abstract":[{"en":"Picture a ladder standing in a language classroom, each rung labelled with what a learner can now do.","cn":"想象语言教室里立着一把梯子，每一级都标着学习者现在能做的事。"},{"en":"Picture a pair of headphones still warm from hours of practice.","cn":"想象一副耳机还带着数小时练习的余温。"},{"en":"Picture a certificate that travels in a pocket from one country to another.","cn":"想象一张证书被装进口袋，从一个国家带到另一个国家。"}]},"examples":[{"en":"Applicants must show proficiency in written English.","cn":"申请人必须证明书面英语熟练。"},{"en":"Her proficiency with the instrument surprised the orchestra.","cn":"她对这件乐器的熟练让乐团吃了一惊。"},{"en":"The course takes students from beginner to working proficiency.","cn":"这门课把学生从初学带到工作水平。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「pro（向前）+ fic（做）」——一直向前做，越做越熟 → 熟练、水平","word":"proficiency"},"root":"拉丁 pro-「向前」+ facere「做」→ proficere「取得进展、完成」→ 分词 proficiens → 英语 proficient 加名词后缀 → proficiency；facere 的更早来源一般与「放置」词根相关，确切链条属重构。","sensesIntro":{"en":"Eight senses follow one ladder: a learner moves forward in a skill, the moving shows as command of a language, then as skill in any field, as a band on a scale, as the fruit of practice, as a professional threshold, as tool craft, as a limited degree and finally as portable certified evidence.","cn":"八个义项沿同一把梯子展开：学习者在技能上向前走，这份前进先表现为语言掌控，再表现为各领域的技能、量表上的等级、练习的果实、职业门槛、工具手艺、有限的程度，最后成为可携带的认证证据。"},"semanticMap":{"core":{"en":"CORE IMAGE: a ladder whose rungs are labelled with what a learner can do, and the climb is measured rather than merely praised.","cn":"核心意象：一把梯子，每级标着学习者能做的事，而攀爬是被测量的，不只是被称赞。"},"chain":["PROGRESS","PRACTICE","COMMAND","MEASURE","THRESHOLD","EVIDENCE"],"branches":[{"senses":"01 · 02","en":"COMMAND: the same forward movement shows first in a language, then in any practised field.","cn":"掌控：同一份向前的进展先显于语言，再显于任何经过练习的领域。"},{"senses":"03 · 07","en":"SCALE: a measured band and a limited degree are two readings of the same ruler.","cn":"量表：测出的等级与有限的程度，是同一把尺子的两种读数。"},{"senses":"04","en":"PRACTICE: the climb belongs to learners, because practice is what produces it.","cn":"练习：这段攀爬属于学习者，因为产出它的是练习。"},{"senses":"05 · 06","en":"THRESHOLD AND TOOL: a profession sets a rung, and a craft shows the rung in the hands.","cn":"门槛与工具：行业设下一级，手艺把这一级显在手上。"},{"senses":"08","en":"PORTABLE PROOF: what was climbed becomes a paper that crosses borders.","cn":"可携带的证明：爬到的位置变成一张能跨越国界的纸。"}]},"affixes":{"intro":{"en":"The noun is a Latin prefix and root plus an English suffix, and the same pieces build a large family of English words.","cn":"这个名词由拉丁前缀、词根加一个英语后缀构成，同一批部件还造出一大族英语词。"},"latinIntro":{"en":"Pro- and facere build proficere, whose participle gives proficient; the English suffix -ency turns the adjective into a noun of state.","cn":"pro- 与 facere 构成 proficere，其分词给出 proficient；英语中的名词后缀把形容词变成表状态的名词。"},"items":[{"word":"pro-","structure":"Latin prefix, 'forward, before'","meaning":"forward","meaningCN":"向前","example":"The prefix gives the sense of advancing.","exampleCN":"这个前缀带来「前进」的意思。"},{"word":"facere","structure":"Latin verb, third conjugation","meaning":"to do, make","meaningCN":"做；造","example":"The root is shared with effect and fact.","exampleCN":"这个词根与 effect、fact 共享。"},{"word":"proficere","structure":"pro- + facere","meaning":"to make progress, accomplish","meaningCN":"取得进展；完成","example":"Proficere is the source of the whole family.","exampleCN":"proficere 是整个词族的来源。"},{"word":"proficiens","structure":"present participle of proficere","meaning":"making progress; effective","meaningCN":"有进展的；有效的","example":"The participle gave the adjective.","exampleCN":"这个分词给出形容词。"},{"word":"proficient","structure":"proficiens through Latin","meaning":"well advanced in a skill","meaningCN":"在技能上进展良好的","example":"She is proficient in two languages.","exampleCN":"她两种语言都熟练。"},{"word":"proficiency","structure":"proficient + -ency (state)","meaning":"the state of being proficient","meaningCN":"熟练的状态","example":"Proficiency is measured by a test.","exampleCN":"熟练程度由测试衡量。"},{"word":"proficiently","structure":"proficient + -ly (in a manner)","meaning":"in a skilled way","meaningCN":"以熟练的方式","example":"He handled the tool proficiently.","exampleCN":"他熟练地操作这件工具。"},{"word":"efficient","structure":"ex- + facere","meaning":"producing results without waste","meaningCN":"以少耗费产出结果","example":"Efficient is a prefix sibling, not a synonym.","exampleCN":"efficient 是前缀上的同族词，并非同义词。"},{"word":"sufficient","structure":"sub- + facere","meaning":"enough for a need","meaningCN":"足以满足需要","example":"Sufficient concerns quantity, not skill.","exampleCN":"sufficient 关乎数量，而非技能。"}],"latinEntries":[{"word":"facere","structure":"facere, feci, factum (verb, third conjugation)","meaning":"to do, make","meaningCN":"做；造"},{"word":"proficere","structure":"proficere, profeci, profectum (verb, third conjugation)","meaning":"to make progress, accomplish","meaningCN":"取得进展；完成"},{"word":"proficiens","structure":"proficiens, proficientis (present participle)","meaning":"making progress, effective","meaningCN":"有进展的；有效的"}],"derivatives":[{"word":"proficient","pos":"adj./n.","zh":"熟练的；能手"},{"word":"proficiently","pos":"adv.","zh":"熟练地"}]}},{"word":"proficient","ipa_uk":"/prəˈfɪʃənt/","ipa_us":"/prəˈfɪʃənt/","definition_zh":"熟练的；精通的；（语言）达到工作水平的","definition_en":"able to do something well and effectively, at a level good enough for real work","core_image":"一位乐手不看谱也能把整段协奏曲拉完，手指在弦上几乎没有停顿","scene":"排练时乐手不看谱便把整段协奏曲拉完，指挥只偶尔点头。By her third year she was proficient on the cello.","sceneCN":"乐手三年后不看谱也能完整拉完协奏曲；句中的 proficient 指「熟练到足以实际运用」（第 1 个义项：在真实任务中能独立做好）。图中可辨识物件：大提琴、弓、谱架、节拍器。","pos":[{"tag":"adj.","zh":"熟练的；精通的"},{"tag":"n.","zh":"能手；熟练者（罕用）"}],"collocations":[{"phrase":"proficient in","zh":"在……方面熟练"},{"phrase":"proficient at","zh":"擅长……"},{"phrase":"highly proficient","zh":"高度熟练的"},{"phrase":"proficient user","zh":"熟练使用者"},{"phrase":"proficient speaker","zh":"熟练的说话者"},{"phrase":"become proficient","zh":"变得熟练"}],"forms":[{"label":"比较级","form":"more proficient"},{"label":"最高级","form":"most proficient"},{"label":"副词","form":"proficiently"},{"label":"名词","form":"proficiency"},{"label":"复数（名词用法，罕用）","form":"proficients"}],"derivatives":[{"word":"proficiency","pos":"n.","zh":"熟练程度；水平"},{"word":"proficiently","pos":"adv.","zh":"熟练地"}],"senses":[{"no":"01","title":"Skilled enough for real work","titleCN":"熟练到足以实际运用","definition":"able to carry out a task well without close supervision","definitionCN":"能在没有密切监督的情况下把任务做好","example":"By her third year she was proficient on the cello.","exampleCN":"到第三年，她已经能熟练地演奏大提琴。","why":"proficere means 'to make progress', so the adjective marks someone who has got far enough to work, not someone who has merely begun.","whyCN":"proficere 意为「取得进展」，因此这个形容词标记的是已经走到能做事的人，而不是刚刚起步的人。"},{"no":"02","title":"A working level in a language","titleCN":"语言达到工作水平","definition":"able to use a language for ordinary professional or academic purposes","definitionCN":"能把一种语言用于日常的职业或学术目的","example":"He is proficient in English and can chair a meeting.","exampleCN":"他英语熟练，能够主持会议。","why":"language testing fixed the adjective at a working band: enough to function, not necessarily native-like.","whyCN":"语言测试把这个形容词固定在「工作水平」这一档：足以运转，不必像母语者。"},{"no":"03","title":"Technically skilled","titleCN":"技术上熟练的","definition":"practised in the use of a tool, instrument or technique","definitionCN":"在使用工具、仪器或技法方面经过练习","example":"The lab hires only proficient technicians.","exampleCN":"实验室只聘用熟练的技术员。","why":"the adjective attaches easily to tools because skill with a tool can be seen at once.","whyCN":"这个形容词很容易与工具连用，因为用工具的技艺一看便知。"},{"no":"04","title":"An advanced learner, as a noun","titleCN":"名词用法：学有所成者（罕用）","definition":"a person who has reached an advanced level, especially in a language","definitionCN":"达到较高水平的人，尤指在语言方面","example":"The class moved the proficients into a separate reading group.","exampleCN":"班上把学有所成者分进另一个阅读组。","why":"the rare noun turns the adjective into a person, a usage kept alive mainly in language teaching.","whyCN":"罕用的名词用法把形容词变成人，这种用法主要活在语言教学里。"},{"no":"05","title":"Effective in practice","titleCN":"在实际中行之有效","definition":"doing what is needed competently rather than merely knowing about it","definitionCN":"把需要的事做得像样，而不只是知道怎么做","example":"A proficient manager settles the dispute before it spreads.","exampleCN":"一位称职的管理者会在争执扩散前把它解决。","why":"the word always points at performance: proficiency is shown in what gets done, not in what is claimed.","whyCN":"这个词始终指向实际表现：熟练显现在做成的事上，而非宣称上。"},{"no":"06","title":"Showing mastery in performance","titleCN":"在表现中显出功力","definition":"performing with control and assurance that practice has produced","definitionCN":"以练习带来的控制力与把握完成表演","example":"Her proficient handling of the difficult passage drew applause.","exampleCN":"她处理那段难句时显出功力，赢得掌声。","why":"in the arts the adjective praises control: the notes are not merely correct but securely held.","whyCN":"在艺术中，这个形容词称赞的是控制力：音符不仅正确，而且握得稳。"},{"no":"07","title":"Trained and qualified","titleCN":"受过训练并合格","definition":"having completed the training that a role requires","definitionCN":"已完成某个岗位所要求的训练","example":"Only proficient operators may run the press.","exampleCN":"只有熟练的操作员才能开这台压机。","why":"qualification adds a gate: training ends when a person is judged proficient enough to be trusted alone.","whyCN":"「合格」加上一道闸门：训练在一人被判定熟练到可以独自负责时结束。"},{"no":"08","title":"Capable but not an expert","titleCN":"够用但非专家","definition":"good enough for the task at hand while falling short of mastery","definitionCN":"足以应付眼前任务，但尚未达到精通","example":"He is proficient, though not yet expert, at repairing watches.","exampleCN":"他修表已算熟练，但还称不上专家。","why":"the comparative scale leaves room above proficient; the word marks a threshold passed, not a summit reached.","whyCN":"比较级量表在 proficient 之上还留有空间；这个词标记的是已过的门槛，而非登上的顶峰。"}],"etymology":{"intro":{"en":"Proficient is the present participle of Latin proficere 'to make progress, accomplish', built on pro- 'forward' and facere 'to do, make'. It entered English in the sixteenth century. Dates are approximate.","cn":"proficient 是拉丁 proficere「取得进展、完成」的现在分词，由 pro-「向前」与 facere「做、造」构成，于十六世纪进入英语。年代为约数。"},"items":[{"era":"LATIN FACERE","en":"Facere 'to do, make' is the root behind fact, effect, defect and every English verb in -fy.","cn":"facere「做、造」是 fact、effect、defect 以及一切由它构成的英语动词背后的词根。"},{"era":"LATIN PROFICERE","en":"Pro- 'forward' plus facere gave proficere 'to make progress, to accomplish, to be of use'.","cn":"pro-「向前」加 facere 给出 proficere「取得进展、完成、有用」。"},{"era":"PARTICIPLE PROFICIENS","en":"The present participle proficiens described someone in the middle of making progress, hence 'getting somewhere, effective'.","cn":"现在分词 proficiens 描述正处在进展中的人，因此意为「走得到地方的、有效的」。"},{"era":"ENGLISH ADJECTIVE","en":"English adopted proficient in the sixteenth century, at first for things that were useful, then for people well advanced in a skill.","cn":"英语在十六世纪采用 proficient，先指事物有用，后指人在技能上进展良好。"},{"era":"LANGUAGE TESTING","en":"Twentieth-century language testing gave the adjective a fixed working band, so a certificate can state that someone is proficient rather than fluent.","cn":"二十世纪的语言测试给这个形容词一个固定的工作档位，于是证书可以写明某人为熟练而非流利。"},{"era":"SOURCE UNCERTAIN","en":"The pre-Latin origin of facere is generally connected to a root meaning 'to put, set', but the exact chain is a reconstruction, and the sixteenth-century sense development is only partly documented.","cn":"facere 在拉丁语之前的来源一般被认为与表示「放置」的词根相关，但确切链条属重构，十六世纪的语义发展也只有部分记录。"}]},"similar":{"note":{"en":"Group one holds the noun and the prefix siblings that look alike; group two holds adjectives of ability that claim different degrees.","cn":"第一组是名词形式以及形近的前缀同族词；第二组是表示能力的形容词，各自宣称的程度不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"proficiency","ipa":"/prəˈfɪʃənsi/","tag":"the noun","definition":"The measured level; proficient describes the person who holds it.","definitionCN":"指被测出的水平；proficient 描述拥有这个水平的人。"},{"word":"proficiently","ipa":"/prəˈfɪʃəntli/","tag":"the adverb","definition":"Describes how a task is done, not what a person is.","definitionCN":"描述任务如何被完成，而非人怎样。"},{"word":"efficient","ipa":"/ɪˈfɪʃənt/","tag":"different prefix","definition":"From ex- plus facere: getting results with little waste, which says nothing about skill level.","definitionCN":"由 ex- 加 facere：以很少耗费取得结果，与技能水平无关。"},{"word":"sufficient","ipa":"/səˈfɪʃənt/","tag":"different prefix","definition":"From sub- plus facere: enough in amount, a quantity word rather than a skill word.","definitionCN":"由 sub- 加 facere：数量上足够，是数量词而非技能词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"skilled","ipa":"/skɪld/","tag":"trained","definition":"The plain adjective for training and practice; proficient adds the sense of being good enough for real work.","definitionCN":"指受过训练与练习的普通形容词；proficient 多出「足以实际工作」之意。"},{"word":"competent","ipa":"/ˈkɒmpɪtənt/","tag":"meets the standard","definition":"Meets the required standard, sometimes no more than that; proficient usually implies a firmer command.","definitionCN":"达到要求的标准，有时仅止于此；proficient 通常意味着更稳的掌控。"},{"word":"fluent","ipa":"/ˈfluːənt/","tag":"smooth speech","definition":"Smooth and rapid in speech, with less attention to accuracy or range than proficient.","definitionCN":"说话顺滑快速，对准确度与覆盖面不如 proficient 看重。"},{"word":"expert","ipa":"/ˈekspɜːt/","tag":"top of the scale","definition":"A far higher claim than proficient: recognized mastery in a narrow field.","definitionCN":"比 proficient 高得多的说法：在狭窄领域被认可的精通。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations here are the real Latin participle, the real family and the real threshold the word marks.","cn":"正常联想取自真实的拉丁分词、真实词族，以及这个词所标记的真实门槛。"},"normal":[{"en":"proficiens is a participle: someone in the middle of getting somewhere.","cn":"proficiens 是分词：一个正走到某处的人。"},{"en":"pro- 'forward' plus facere 'do': moving forward in what one does.","cn":"pro-「向前」加 facere「做」：在做的事上向前走。"},{"en":"The family runs proficient, proficiency, proficiently.","cn":"词族包括 proficient、proficiency、proficiently。"},{"en":"Fixed phrases mark the test: proficient in, highly proficient, proficient user.","cn":"固定搭配标出测试语境：在……熟练、高度熟练、熟练使用者。"},{"en":"The word marks a threshold, so it pairs with enough and not yet: proficient enough, not yet expert.","cn":"这个词标记门槛，因此常与「够」和「尚未」连用：够熟练、尚未精通。"}],"abstract":[{"en":"Picture a musician who no longer needs the score but still keeps it open.","cn":"想象一位乐手已不再需要看谱，却仍把谱子摊开。"},{"en":"Picture a toolbox whose every handle is worn smooth in the same place.","cn":"想象一只工具箱，每个把手的同一处都被磨得光滑。"},{"en":"Picture a door marked with a line at shoulder height, already passed.","cn":"想象一扇门在齐肩高处画了一道线，而人已走过它。"}]},"examples":[{"en":"She became proficient in Spanish after two summers abroad.","cn":"在国外度过两个夏天后，她的西班牙语变得熟练。"},{"en":"A proficient reader adjusts speed to the difficulty of the text.","cn":"熟练的读者会按文本难度调整速度。"},{"en":"The workshop produces proficient welders in six months.","cn":"这个工作坊六个月就能培养出熟练的焊工。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「pro（向前）+ fic（做）」——越做越往前 → 熟练的、精通的","word":"proficient"},"root":"拉丁 pro-「向前」+ facere「做」→ proficere「取得进展」→ 现在分词 proficiens → 英语 proficient；facere 的更早来源一般与「放置」词根相关，确切链条属重构。","sensesIntro":{"en":"Eight senses share one threshold: a learner has moved far enough forward to do real work, and the threshold is then applied to a language, a tool, a classroom role, a dispute, a performance, a licence and a repair bench.","cn":"八个义项共用一个门槛：学习者向前走到足以做真实工作的位置，这个门槛随后用于语言、工具、课堂角色、争执、表演、执照与修理台。"},"semanticMap":{"core":{"en":"CORE IMAGE: a line on a doorframe at shoulder height, already crossed, with more height still available above it.","cn":"核心意象：门框上齐肩高处的一道线，人已跨过，而线上方仍有余地。"},"chain":["FORWARD","PRACTICE","REAL WORK","LANGUAGE","LICENCE","MASTERY"],"branches":[{"senses":"01 · 07","en":"THE THRESHOLD: the same line separates training from trusted independent work.","cn":"门槛：同一条线把训练与可被信任的独立工作分开。"},{"senses":"02","en":"THE LANGUAGE BAND: testing pins the threshold to a working level of a language.","cn":"语言档位：测试把门槛固定在语言的工作水平上。"},{"senses":"03 · 06","en":"HAND AND STAGE: a tool and a performance both show the threshold in execution.","cn":"手与舞台：工具与表演都把门槛显现在执行之中。"},{"senses":"04 · 05","en":"ROLE AND PRACTICE: the rare noun names the person, and effective practice proves the claim.","cn":"角色与实践：罕用名词指人，有效的实践则证明这份宣称。"},{"senses":"08","en":"ROOM ABOVE: mastery lies beyond the line, so proficient never means finished.","cn":"线上余地：精通在门槛之外，因此 proficient 从不意味「到头」。"}]},"affixes":{"intro":{"en":"The adjective is a Latin prefix and root plus a participle ending, and the same pieces build the whole proficiency family.","cn":"这个形容词由拉丁前缀、词根加一个分词词尾构成，同一批部件造出整个 proficiency 词族。"},"latinIntro":{"en":"Pro- and facere build proficere; its present participle proficiens is the direct source of the English adjective.","cn":"pro- 与 facere 构成 proficere；其现在分词 proficiens 是英语形容词的直接来源。"},"items":[{"word":"pro-","structure":"Latin prefix, 'forward'","meaning":"forward","meaningCN":"向前","example":"The prefix supplies direction.","exampleCN":"这个前缀提供方向。"},{"word":"facere","structure":"Latin verb, third conjugation","meaning":"to do, make","meaningCN":"做；造","example":"Facere is the shared root.","exampleCN":"facere 是共享的词根。"},{"word":"proficere","structure":"pro- + facere","meaning":"to make progress","meaningCN":"取得进展","example":"Proficere is the base verb.","exampleCN":"proficere 是基础动词。"},{"word":"proficiens","structure":"present participle, -ens ending","meaning":"making progress; effective","meaningCN":"有进展的；有效的","example":"The participle ending is -ens.","exampleCN":"分词词尾表示进行与主动。"},{"word":"proficient","structure":"proficiens through Latin","meaning":"well advanced in a skill","meaningCN":"技能上进展良好的","example":"The adjective entered English in the sixteenth century.","exampleCN":"这个形容词于十六世纪进入英语。"},{"word":"proficiency","structure":"proficient + -ency (state)","meaning":"the level reached","meaningCN":"达到的水平","example":"Proficiency is what tests report.","exampleCN":"水平是测试所报告的东西。"},{"word":"proficiently","structure":"proficient + -ly (manner)","meaning":"in a skilled manner","meaningCN":"以熟练的方式","example":"She answered proficiently.","exampleCN":"她熟练地作答。"},{"word":"efficient","structure":"ex- + facere","meaning":"without waste","meaningCN":"无浪费地","example":"Efficient is a sibling, not a synonym.","exampleCN":"efficient 是同族词，并非同义词。"},{"word":"sufficient","structure":"sub- + facere","meaning":"enough in amount","meaningCN":"数量上足够","example":"Sufficient measures quantity.","exampleCN":"sufficient 衡量数量。"}],"latinEntries":[{"word":"facere","structure":"facere, feci, factum (verb, third conjugation)","meaning":"to do, make","meaningCN":"做；造"},{"word":"proficere","structure":"proficere, profeci, profectum (verb, third conjugation)","meaning":"to make progress, accomplish","meaningCN":"取得进展；完成"},{"word":"proficiens","structure":"proficiens, proficientis (present participle)","meaning":"making progress, effective","meaningCN":"有进展的；有效的"}],"derivatives":[{"word":"proficiency","pos":"n.","zh":"熟练程度；水平"},{"word":"proficiently","pos":"adv.","zh":"熟练地"}]}},{"word":"competence","ipa_uk":"/ˈkɒmpɪtəns/","ipa_us":"/ˈkɑːmpɪtəns/","definition_zh":"能力；胜任力；权限；（语言）能力","definition_en":"the ability to do a task well enough, or the official power to act in a matter","core_image":"一位法官坐在案前，手边摊着法条与案卷，桌角立着一支笔","scene":"法庭先要确认自己对这桩纠纷是否有审理权，再进入实体审理。The court questioned its own competence to hear the case.","sceneCN":"法庭先确认对这桩纠纷是否有审理权，才进入实体审理；句中的 competence 指「官方权限」（第 2 个义项：依法可以管辖某事的权力）。图中可辨识物件：法条、案卷、法官席、笔。","pos":[{"tag":"n.","zh":"能力；胜任力；权限；（语言）能力"}],"collocations":[{"phrase":"professional competence","zh":"专业能力"},{"phrase":"linguistic competence","zh":"语言能力"},{"phrase":"competence in","zh":"在……方面的能力"},{"phrase":"legal competence","zh":"法律上的权限"},{"phrase":"core competence","zh":"核心能力"},{"phrase":"demonstrate competence","zh":"展现胜任力"}],"forms":[{"label":"复数","form":"competences"},{"label":"形容词","form":"competent"},{"label":"副词","form":"competently"}],"derivatives":[{"word":"competent","pos":"adj.","zh":"能胜任的；有权限的"},{"word":"competently","pos":"adv.","zh":"胜任地"},{"word":"competency","pos":"n.","zh":"具体技能；胜任力项"},{"word":"incompetence","pos":"n.","zh":"不胜任"}],"senses":[{"no":"01","title":"Ability to do a job well enough","titleCN":"足以把工作做好的能力","definition":"the ability to carry out a task to an acceptable standard","definitionCN":"把一项任务做到可接受标准的能力","example":"The exam tests competence rather than memorised facts.","exampleCN":"这项考试检验的是胜任能力，而非背下来的事实。","why":"competere meant 'to meet, to come together, to be suitable', so competence is the point at which a person and a task meet properly.","whyCN":"competere 意为「相遇、相合、适合」，因此 competence 就是人与任务恰好相合的那个点。"},{"no":"02","title":"Official power to act","titleCN":"依法可以行事的权限","definition":"the legal authority of a body or an official to decide a matter","definitionCN":"机构或官员对某事作出决定的法定权力","example":"The court questioned its own competence to hear the case.","exampleCN":"法院对自身审理此案的权限提出疑问。","why":"law took the 'suitability' sense and made it formal: a court is competent when the matter properly belongs to it.","whyCN":"法律取用「相合」义并使之形式化：当某事正属某一法院管辖，该法院即有权限。"},{"no":"03","title":"Knowledge of language rules","titleCN":"语言规则的内在知识","definition":"the underlying knowledge a speaker has of a language's rules","definitionCN":"说话者对一种语言规则的内在知识","example":"Linguistic competence is not the same as what a speaker actually says.","exampleCN":"语言能力并不等同于说话者实际说出的内容。","why":"linguistics borrowed the word for hidden knowledge, contrasting it with performance, the actual use of that knowledge.","whyCN":"语言学借这个词指隐藏的知识，并与「实际运用」相区分。"},{"no":"04","title":"The skill set a role requires","titleCN":"岗位所需的能力组合","definition":"the set of skills and behaviours a position demands","definitionCN":"某一职位所要求的一组技能与行为","example":"The job description lists the competences required for the role.","exampleCN":"职位说明列出了该岗位所需的能力项。","why":"when employers list competences, they break competence into named pieces that can be taught and checked.","whyCN":"雇主列出「能力项」时，是把胜任力拆成可教、可查的具名部件。"},{"no":"05","title":"Organisational capability","titleCN":"组织的整体能力","definition":"the collective ability of an institution to deliver what it promises","definitionCN":"机构兑现承诺的整体能力","example":"The audit judged the agency's competence in emergency planning.","exampleCN":"审计评估了该机构在应急规划方面的能力。","why":"the unit can rise from a person to an organisation, and competence then means the whole body's capacity to deliver.","whyCN":"单位可以从个人上升到组织，competence 也就指整个机构交付的能力。"},{"no":"06","title":"Sufficiency of means","titleCN":"财力物力上的足够（旧义）","definition":"enough income or resources to live or to act, an older legal and everyday sense","definitionCN":"足以生活或行事的收入与资源，属较旧的法律与日常义","example":"The estate was valued as sufficient for her competence.","exampleCN":"这份产业被估定为足以维持她的生活。","why":"the oldest everyday sense was 'means sufficient for living', which survives in legal wording about a person's estate.","whyCN":"最早的日常义是「足以维持生活的财产」，这一意义残留在关于个人财产的法律措辞中。"},{"no":"07","title":"A professional standard","titleCN":"职业标准","definition":"the level of skill a profession regards as safe to practise","definitionCN":"行业视为可以安全执业的技能水平","example":"The board found him below the competence required for surgery.","exampleCN":"委员会认定他未达到外科所要求的胜任水平。","why":"professions define competence as a floor, not a ceiling: below it, practice is unsafe.","whyCN":"行业把胜任力定义为地板而非天花板：低于它，执业就不安全。"},{"no":"08","title":"Fitness to function, in old biology","titleCN":"旧生物学：机能上的适应","definition":"the ability of an organism or organ to function as its kind should","definitionCN":"生物体或器官按其种类应有的运作能力","example":"Early texts spoke of the competence of the organ to repair itself.","exampleCN":"早期文献谈到该器官自我修复的机能。","why":"older biology used the word for an organ's fitness, the same 'suitability' idea applied to living tissue.","whyCN":"较早的生物学用这个词指器官的适应能力，仍是那套「相合」观念用在活体组织上。"}],"etymology":{"intro":{"en":"Competence comes from Latin competentia 'a meeting, agreement', built on competere 'to meet, come together, be suitable', from com- 'together' and petere 'to seek, aim at'. Dates are approximate.","cn":"competence 来自拉丁 competentia「相遇、一致」，由 competere「相遇、相合、适合」构成，后者又由 com-「共同」与 petere「寻求、指向」构成。年代为约数。"},"items":[{"era":"LATIN PETERE","en":"Petere meant 'to seek, to aim at, to attack'. It is also the root of petition, appetite and repeat, all built on the idea of aiming toward something.","cn":"petere 意为「寻求、指向、攻击」，也是 petition、appetite 与 repeat 的词根，这些词都建立在「朝某物指向」的观念上。"},{"era":"LATIN COMPETERE","en":"Com- 'together' plus petere gave competere 'to meet, to fall together, to be suitable or sufficient'. Two people seeking the same prize also competed.","cn":"com-「共同」加 petere 给出 competere「相遇、相合、合适或足够」。两人争同一奖品，也就是「竞争」。"},{"era":"LATIN COMPETENTIA","en":"Competentia named a meeting or a correspondence between things, hence a proper fit between a person and a duty.","cn":"competentia 指事物之间的相遇或对应，因此也指人与职责之间恰当的相合。"},{"era":"ENGLISH COMPETENCE","en":"English took competence in the sixteenth century for the power or ability to act, including legal authority.","cn":"英语在十六世纪吸收 competence，指行动的能力或权力，包括法定权限。"},{"era":"LINGUISTICS","en":"In the twentieth century linguistics gave the word a technical sense: the hidden knowledge of rules that makes speech possible, set against actual performance.","cn":"二十世纪语言学给了这个词一个术语义：使言语成为可能的、关于规则的内在知识，与实际的言语运用相对。"},{"era":"SOURCE UNCERTAIN","en":"The deeper origin of petere is uncertain; the common link to a root meaning 'to rush at' is a reconstruction. The relation between competere and competere 'to compete' is historical but the modern split in meaning is not documented step by step.","cn":"petere 的更早来源不确定；常被提到的、与表示「扑向」的词根的联系属重构形式。competere 与「竞争」义的关系是历史事实，但现代语义的分化缺乏逐步记录。"}]},"similar":{"note":{"en":"Group one holds the same Latin root under neighbouring spellings, including one that now means something quite different; group two holds words for ability that differ in scope and in legal force.","cn":"第一组是同出拉丁词根、拼写相邻的词，其中有的今义已大不相同；第二组是表示能力的词，范围与法律效力各不相同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"competent","ipa":"/ˈkɒmpɪtənt/","tag":"the adjective","definition":"Describes a person or body that has the ability or the authority; competence is the noun for that ability.","definitionCN":"描述有能力或有权限的人或机构；competence 是表示这种能力的名词。"},{"word":"competency","ipa":"/ˈkɒmpɪtənsi/","tag":"a named skill","definition":"Usually a single skill or behaviour standard, especially in human resources; competence is broader.","definitionCN":"通常指单项技能或行为标准，多用于人力资源；competence 更宽。"},{"word":"competition","ipa":"/ˌkɒmpɪˈtɪʃən/","tag":"same root, other branch","definition":"From the same verb, but names the contest of people aiming at one prize, not the ability to do a job.","definitionCN":"同出该动词，但指众人争同一奖品的竞赛，而非做好工作的能力。"},{"word":"petition","ipa":"/pəˈtɪʃən/","tag":"shared root","definition":"From petere 'to seek': a formal request. It shares the root but not the prefix, and has nothing to do with ability.","definitionCN":"来自 petere「寻求」：正式请求。同词根而不同前缀，与能力无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"ability","ipa":"/əˈbɪləti/","tag":"can do it","definition":"The general word for being able; competence adds the idea of meeting a standard or a duty.","definitionCN":"表示「能够」的通用词；competence 多出「达到标准或职责要求」之意。"},{"word":"capability","ipa":"/ˌkeɪpəˈbɪləti/","tag":"capacity to grow","definition":"Often about potential capacity, of a person or a system, including what could be developed.","definitionCN":"常指人或系统的潜在容量，包括尚可发展出来的部分。"},{"word":"skill","ipa":"/skɪl/","tag":"trained technique","definition":"A specific learned technique; competence is the overall fitness to perform a role.","definitionCN":"指具体学成的技术；competence 是整体上能胜任一个角色。"},{"word":"jurisdiction","ipa":"/ˌdʒʊərɪsˈdɪkʃən/","tag":"legal power","definition":"The legal word for the power to decide, close to the legal sense of competence but more explicit.","definitionCN":"表示裁决权的法律用词，接近 competence 的权限义但更明确。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations here are the real meeting image in competere, the real legal sense and the real modern split from competition.","cn":"正常联想取自 competere 真实的「相遇」意象、真实的权限义，以及它与「竞争」的真实现代分化。"},"normal":[{"en":"com- 'together' plus petere 'seek': two things seeking and meeting, hence fitting.","cn":"com-「共同」加 petere「寻求」：两物相寻而相遇，因此相合。"},{"en":"The same verb also gives competition: two people seeking one prize.","cn":"同一动词也给出 competition：两人争一个奖品。"},{"en":"Legal competence means the matter belongs to your court.","cn":"法律上的权限意味着这件事归你这家法院管。"},{"en":"Linguistic competence is hidden knowledge, contrasted with actual performance.","cn":"语言能力是隐藏的知识，与实际的言语运用相对。"},{"en":"Employers pluralise it into competences: teachable named skills.","cn":"雇主把它变成复数「能力项」：可教的具名技能。"}],"abstract":[{"en":"Picture two puzzle pieces that meet exactly, neither forced nor loose.","cn":"想象两块拼图恰好合上，既不勉强也不松动。"},{"en":"Picture a key that fits one lock and no other.","cn":"想象一把钥匙只能开一把锁。"},{"en":"Picture a floor line in a workshop below which nobody may work alone.","cn":"想象车间地面画着一条线，线下不许独自作业。"}]},"examples":[{"en":"The role requires competence in both accounting and law.","cn":"这个岗位要求兼具会计与法律方面的能力。"},{"en":"The tribunal has competence over disputes of this kind.","cn":"该法庭对这类纠纷有管辖权。"},{"en":"Her competence was never in doubt, only her authority.","cn":"她的能力从不受疑，受疑的只是她的权限。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「com（共同）+ pet（追求）」——人与事恰好相合 → 能力、胜任、权限","word":"competence"},"root":"拉丁 com-「共同」+ petere「寻求、指向」→ competere「相遇、相合、适合」→ competentia「相遇、一致」→ 英语 competence；petere 的更早来源不确定，与「扑向」词根的联系属重构形式。","sensesIntro":{"en":"Eight senses turn on one meeting: a person and a duty come together and fit, and that fit is then read as ability, as legal power, as hidden language knowledge, as a named skill, as institutional capacity, as old means of living, as a professional floor and as an organ's fitness.","cn":"八个义项围绕一次「相遇」转动：人与职责走到一起并恰好相合；这份相合随后被读成能力、法定权限、隐藏的语言知识、具名技能、机构容量、旧时的生活财力、职业地板与器官的适应力。"},"semanticMap":{"core":{"en":"CORE IMAGE: two pieces meeting exactly, a key and its one lock, a fit that is neither forced nor loose.","cn":"核心意象：两块拼图恰好合上，一把钥匙与唯一那把锁，一种既不勉强也不松动的相合。"},"chain":["MEET","FIT","ABILITY","AUTHORITY","STANDARD","CAPACITY"],"branches":[{"senses":"01 · 04","en":"FIT FOR WORK: the meeting of person and task, whether judged whole or broken into named skills.","cn":"与工作相合：人与任务的相遇，或整体评判，或拆成具名技能。"},{"senses":"02 · 07","en":"POWER AND FLOOR: law formalises the fit as jurisdiction, and a profession fixes it as a minimum.","cn":"权力与地板：法律把相合形式化为权限，行业把它固定为下限。"},{"senses":"03","en":"HIDDEN RULES: linguistics reads the fit as knowledge behind speech rather than speech itself.","cn":"隐藏规则：语言学把相合读成言语背后的知识，而非言语本身。"},{"senses":"05","en":"THE BODY: the same fit scales up from a person to an institution that must deliver.","cn":"整体：同一份相合从个人放大到必须交付的机构。"},{"senses":"06 · 08","en":"OLD SENSES: enough means to live, and an organ fit to function, both kept from earlier usage.","cn":"旧义：足以生活的财力与足以运作的器官，两者都从更早用法留存。"}]},"affixes":{"intro":{"en":"The noun is a Latin prefix, root and suffix, and the same pieces build the whole competent family, including the branch that became competition.","cn":"这个名词由拉丁前缀、词根与后缀构成，同一批部件造出整个 competent 词族，其中包括分出去成为 competition 的那一支。"},"latinIntro":{"en":"Com- and petere build competere; its participle competens gives competent, and competentia gives the English noun.","cn":"com- 与 petere 构成 competere；其分词 competens 给出 competent，competentia 给出英语名词。"},"items":[{"word":"com-","structure":"Latin prefix, 'together'","meaning":"together; with","meaningCN":"共同；一起","example":"The prefix brings the two sides together.","exampleCN":"这个前缀把两方带到一起。"},{"word":"petere","structure":"Latin verb, third conjugation","meaning":"to seek, aim at","meaningCN":"寻求；指向","example":"Petere is the shared root.","exampleCN":"petere 是共享词根。"},{"word":"competere","structure":"com- + petere","meaning":"to meet, be suitable","meaningCN":"相遇；适合","example":"Competere is the base verb.","exampleCN":"competere 是基础动词。"},{"word":"competentia","structure":"competere + -entia (state)","meaning":"a meeting, a fitting","meaningCN":"相遇；相合","example":"Competentia gave the English noun.","exampleCN":"competentia 给出英语名词。"},{"word":"competent","structure":"present participle competens","meaning":"suitable, able, authorised","meaningCN":"适合的；有能力的；有权限的","example":"The adjective describes the fit.","exampleCN":"形容词描述这份相合。"},{"word":"competence","structure":"competent + -ence (state)","meaning":"the state of being fit","meaningCN":"相合的状态","example":"Competence is the noun of state.","exampleCN":"competence 是表状态的名词。"},{"word":"competency","structure":"competent + -ency (state)","meaning":"a single skill or standard","meaningCN":"单项技能或标准","example":"Competency is common in human resources.","exampleCN":"competency 常用于人力资源。"},{"word":"competition","structure":"com- + petere + -ition","meaning":"a seeking together for one prize","meaningCN":"众人同争一奖","example":"Competition split off into contest.","exampleCN":"competition 分出去指竞赛。"},{"word":"incompetence","structure":"in- + competence","meaning":"lack of the needed ability","meaningCN":"缺乏所需能力","example":"Incompetence is the negated noun.","exampleCN":"incompetence 是否定形式。"}],"latinEntries":[{"word":"petere","structure":"petere, petivi, petitum (verb, third conjugation)","meaning":"to seek, aim at","meaningCN":"寻求；指向"},{"word":"competere","structure":"competere, competivi, competitum (verb, third conjugation)","meaning":"to meet, be suitable","meaningCN":"相遇；适合"},{"word":"competentia","structure":"competentia, competentiae (f., first declension)","meaning":"a meeting, a fitting","meaningCN":"相遇；相合"}],"derivatives":[{"word":"competent","pos":"adj.","zh":"能胜任的；有权限的"},{"word":"competently","pos":"adv.","zh":"胜任地"},{"word":"competency","pos":"n.","zh":"具体技能；胜任力项"},{"word":"incompetence","pos":"n.","zh":"不胜任"}]}},{"word":"competent","ipa_uk":"/ˈkɒmpɪtənt/","ipa_us":"/ˈkɑːmpɪtənt/","definition_zh":"有能力的；能胜任的；有法定权限的；尚可的","definition_en":"having enough ability or authority to do what is required, though not necessarily with brilliance","core_image":"一位技师把拆开的机芯重新装回，桌上每颗螺钉都归回原位","scene":"维修台前，技师把拆散的机芯重新装好，走时准确，顾客当场取走。The watch is repaired by a competent technician, not by a specialist.","sceneCN":"技师把机芯装回、走时准确，顾客当场取走；句中的 competent 指「能力足以把活干好」（第 1 个义项：达到工作要求，未必出色）。图中可辨识物件：机芯、螺丝刀、走时检测仪、工作台。","pos":[{"tag":"adj.","zh":"有能力的；能胜任的；有法定权限的；尚可的"}],"collocations":[{"phrase":"competent authority","zh":"主管机关"},{"phrase":"competent staff","zh":"称职的员工"},{"phrase":"competent in","zh":"在……方面有能力"},{"phrase":"highly competent","zh":"非常称职的"},{"phrase":"competent performance","zh":"合乎要求的履行"},{"phrase":"legally competent","zh":"有法定资格的"}],"forms":[{"label":"比较级","form":"more competent"},{"label":"最高级","form":"most competent"},{"label":"副词","form":"competently"},{"label":"名词","form":"competence"},{"label":"否定形式","form":"incompetent"}],"derivatives":[{"word":"competence","pos":"n.","zh":"能力；权限"},{"word":"competently","pos":"adv.","zh":"称职地"},{"word":"competency","pos":"n.","zh":"具体技能；胜任力项"},{"word":"incompetent","pos":"adj.","zh":"不胜任的"}],"senses":[{"no":"01","title":"Able to do the task","titleCN":"能力足以把活干好","definition":"having enough skill to carry out a task to an acceptable standard","definitionCN":"具备足够技能，把任务做到可接受标准","example":"The watch is repaired by a competent technician, not by a specialist.","exampleCN":"这只表由一位称职的技师修好，并非出自专家之手。","why":"competere meant 'to meet, to be suitable', so competent describes a person who meets the demands of the task, neither below nor far above them.","whyCN":"competere 意为「相遇、适合」，因此 competent 描述的是与任务要求相合的人，既不低于也不远高于要求。"},{"no":"02","title":"Legally authorised","titleCN":"有法定权限的","definition":"having the legal power to decide or to act in a matter","definitionCN":"对某事拥有作出决定或采取行动的法定权力","example":"Only the competent authority may close the road.","exampleCN":"只有主管机关可以封闭这条道路。","why":"law made the suitability formal: an authority is competent when the matter falls within its assigned power.","whyCN":"法律把「适合」形式化：当某事落在被授予的权力范围内，该机关就是有权限的。"},{"no":"03","title":"Adequate but not brilliant","titleCN":"合格但并不出色","definition":"satisfactory in quality, doing what is needed without distinction","definitionCN":"质量上令人满意，能完成所需之事但不出众","example":"The report was competent, thorough and entirely forgettable.","exampleCN":"这份报告合格、周全，也完全不出彩。","why":"because the word marks a threshold rather than a peak, it often carries a faint note of 'only just good enough'.","whyCN":"这个词标记的是门槛而非顶峰，因此常带一点「刚刚够好」的意味。"},{"no":"04","title":"Fit in body, in old use","titleCN":"旧义：身体上适合的","definition":"having the physical capacity expected of a healthy person, an older medical use","definitionCN":"具备健康人应有的身体能力，属较旧的医学用法","example":"The old form asked whether the recruit was competent to march.","exampleCN":"旧表格问的是新兵是否具备行军的体能。","why":"older medicine asked whether a body was competent for a duty, the same suitability idea applied to the frame.","whyCN":"较早的医学问身体是否胜任某项职责，仍是那套「适合」观念用在身体上。"},{"no":"05","title":"Knowing the rules of a language","titleCN":"具备语言规则知识","definition":"having the underlying knowledge of a language's rules, in linguistic terms","definitionCN":"按语言学术语，具备关于语言规则的内在知识","example":"A competent speaker can judge which sentences are well formed.","exampleCN":"有语言能力的说话者能判断哪些句子合乎语法。","why":"linguistics used the adjective for the hidden knowledge behind speech, as opposed to actual use.","whyCN":"语言学用这个形容词指言语背后的隐藏知识，与实际的运用相对。"},{"no":"06","title":"Sufficient in amount, in law","titleCN":"法律旧义：数目上足够的","definition":"large enough in amount to satisfy a legal requirement, as of an income","definitionCN":"在数量上足以满足法律要求，如收入","example":"The trustee must hold a competent estate for the child.","exampleCN":"受托人须为这孩子持有一份足额的产业。","why":"the oldest everyday sense was 'sufficient', which survives in legal phrases about money and property.","whyCN":"最早的日常义是「足够」，这一意义残留在关于金钱与财产的法律短语里。"},{"no":"07","title":"Reliable in a profession","titleCN":"职业上靠得住的","definition":"trusted to work without close supervision, because past work met the standard","definitionCN":"因以往工作达标而被信任可独立作业","example":"After two years she was competent enough to run the shift alone.","exampleCN":"两年后她已能胜任独自带班。","why":"trust is the social form of the threshold: once competence is shown repeatedly, supervision can be withdrawn.","whyCN":"信任是这个门槛的社会形式：胜任力一旦被反复证明，监督就可以撤走。"},{"no":"08","title":"Admissible as evidence","titleCN":"证据上可采且充分的","definition":"legally valid and weighty enough to support a finding","definitionCN":"在法律上有效，且分量足以支撑一项裁定","example":"The judge ruled the record competent evidence.","exampleCN":"法官裁定这份记录是可采信的证据。","why":"courtroom usage adds a second test: evidence must be both allowed and strong enough, which is the same double fit.","whyCN":"法庭用法加了第二道检验：证据既须被允许，也须足够有力，仍是同一种双重相合。"}],"etymology":{"intro":{"en":"Competent is the present participle of Latin competere 'to meet, be suitable'. The verb joins com- 'together' with petere 'to seek, aim at', so the picture is two things seeking and meeting. Dates are approximate.","cn":"competent 是拉丁 competere「相遇、适合」的现在分词。该动词把 com-「共同」与 petere「寻求、指向」接在一起，意象是两物相寻而相遇。年代为约数。"},"items":[{"era":"LATIN PETERE","en":"Petere meant 'to seek, aim at, attack'. Petition and appetite come from the same root, all built on aiming toward something.","cn":"petere 意为「寻求、指向、攻击」。petition 与 appetite 同出这个词根，都建立在「朝某物指向」上。"},{"era":"LATIN COMPETERE","en":"Com- 'together' plus petere produced competere 'to meet, to be suitable, to be sufficient'; the same verb also described rivals seeking one prize.","cn":"com-「共同」加 petere 产生 competere「相遇、适合、足够」；同一动词也描述争夺同一奖品的对手。"},{"era":"PARTICIPLE COMPETENS","en":"The present participle competens meant 'meeting, suitable, fit for a duty', and English took it as competent in the sixteenth century.","cn":"现在分词 competens 意为「相合的、适合的、胜任某职责的」，英语在十六世纪把它吸收为 competent。"},{"era":"LEGAL SENSE","en":"English law fixed competent as a term for authority and sufficiency: a competent court, a competent income, competent evidence.","cn":"英语法律把 competent 固定为表示权限与足额的术语：有管辖权的法院、足额的收入、可采信的证据。"},{"era":"MODERN EVERYDAY SENSE","en":"From the eighteenth century the adjective also served as plain praise for work that meets the standard, often with the implication of adequacy rather than excellence.","cn":"从十八世纪起，这个形容词也用作对达标工作的朴素称赞，常隐含「够用而非卓越」之意。"},{"era":"SOURCE UNCERTAIN","en":"The deeper origin of petere is uncertain; the usual link to a root meaning 'to rush at' is reconstructed. The route from 'meeting' to 'legally authorised' is historically attested but not documented in every step.","cn":"petere 的更早来源不确定；通常所说的、与表示「扑向」的词根的联系属重构。从「相遇」到「有法定权限」的演变有历史书证，但并非每一步都有记录。"}]},"similar":{"note":{"en":"Group one holds the noun forms and the look-alike that now means a contest; group two holds adjectives of ability at different heights on the same scale.","cn":"第一组是名词形式，以及今义已转为「竞赛」的形近词；第二组是同一把能力尺子上不同高度的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"competence","ipa":"/ˈkɒmpɪtəns/","tag":"the noun","definition":"The ability or authority itself; competent describes the person who has it.","definitionCN":"指能力或权限本身；competent 描述拥有它的人。"},{"word":"competency","ipa":"/ˈkɒmpɪtənsi/","tag":"a single item","definition":"A named skill or behaviour standard, usually one item in a list; competent is a general judgement.","definitionCN":"指具名技能或行为标准，通常是清单中的一项；competent 是整体判断。"},{"word":"competition","ipa":"/ˌkɒmpɪˈtɪʃən/","tag":"same root, other branch","definition":"The contest of rivals aiming at one prize, which grew from the same verb but took a different road.","definitionCN":"指对手争一奖的竞赛，同出该动词却走上另一条路。"},{"word":"petition","ipa":"/pəˈtɪʃən/","tag":"shared root","definition":"A formal request, from petere 'to seek'; it shares the root but has nothing to do with ability.","definitionCN":"指正式请求，来自 petere「寻求」；同词根，与能力无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"capable","ipa":"/ˈkeɪpəbl/","tag":"can do it","definition":"Able to do something, sometimes only in principle; competent usually implies a demonstrated standard.","definitionCN":"指有能力做，有时仅指原则上可以；competent 通常意味着已被证明达到标准。"},{"word":"qualified","ipa":"/ˈkwɒlɪfaɪd/","tag":"paper proof","definition":"Having the certificates or training a role requires; competent is about actual work, not papers.","definitionCN":"指持有岗位所需的证书或训练；competent 关乎实际工作，而非纸面。"},{"word":"skilled","ipa":"/skɪld/","tag":"trained technique","definition":"Strong at a technique, often above the merely acceptable line that competent marks.","definitionCN":"指技术强，常高于 competent 所标记的「尚可」线。"},{"word":"adequate","ipa":"/ˈædɪkwət/","tag":"just enough","definition":"Enough for the purpose, with no judgement of a person's ability; competent always judges a doer.","definitionCN":"指足以达成目的，不评判人的能力；competent 总在评判做事的人。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations here are the real meeting image, the real legal phrases and the real threshold flavour of the word.","cn":"正常联想取自真实的「相遇」意象、真实的法律短语，以及这个词真实的门槛意味。"},"normal":[{"en":"com- 'together' plus petere 'seek': two sides meeting and fitting.","cn":"com-「共同」加 petere「寻求」：两方相遇而相合。"},{"en":"The same verb gives competition: rivals also seek one prize together.","cn":"同一动词给出 competition：对手也一同争一个奖品。"},{"en":"Legal phrases are fixed: competent authority, competent court, competent evidence.","cn":"法律短语固定：主管机关、有管辖权的法院、可采信的证据。"},{"en":"The word marks a floor, so it often sounds like faint praise.","cn":"这个词标记下限，因此常听起来像淡淡的称赞。"},{"en":"The negative incompetent is far more common than the positive in complaints.","cn":"否定形式 incompetent 在抱怨语境中远比肯定形式常见。"}],"abstract":[{"en":"Picture a tool returned to its exact outline on a workbench board.","cn":"想象一把工具被放回工作台板上它自己的轮廓里。"},{"en":"Picture a door that opens only for a key cut to the right depth, not a master key.","cn":"想象一扇门只为齿深正好的钥匙打开，而非万能钥匙。"},{"en":"Picture a line on a form marked 'meets requirement', ticked, nothing more.","cn":"想象表格上一栏写着「符合要求」，打了个勾，别无其他。"}]},"examples":[{"en":"The agency is competent to inspect the site.","cn":"该机构有权检查这个场地。"},{"en":"A competent editor would have caught that error.","cn":"一位称职的编辑本会发现那个错误。"},{"en":"The work was competent, if not inspired.","cn":"这件作品合格，虽然谈不上有灵感。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「com（共同）+ pet（追求）」——与岗位要求恰好对上 → 能胜任的、称职的","word":"competent"},"root":"拉丁 com-「共同」+ petere「寻求、指向」→ competere「相遇、适合」→ 现在分词 competens → 英语 competent；petere 的更早来源不确定，与「扑向」词根的联系属重构形式。","sensesIntro":{"en":"Eight senses mark one threshold: a person or thing meets a requirement, and the meeting is read as skill, as legal power, as mere adequacy, as old bodily fitness, as language knowledge, as sufficient amount, as professional trust and as admissible proof.","cn":"八个义项标记同一个门槛：人或事物与某项要求相合；这份相合被读成技能、法定权力、仅止合格、旧时的体能、语言知识、足额、职业信任与可采信的证据。"},"semanticMap":{"core":{"en":"CORE IMAGE: a key cut to exactly the depth the lock requires, opening it without being a master key.","cn":"核心意象：一把按锁所需深度削好的钥匙，能开这把锁，却不是万能钥匙。"},"chain":["MEET","FIT","THRESHOLD","AUTHORITY","ADEQUACY","TRUST"],"branches":[{"senses":"01 · 03","en":"THE FLOOR: meeting the task and meeting it only adequately are the same line seen from two sides.","cn":"地板：与任务相合，与仅止合格，是同一条线从两侧看。"},{"senses":"02 · 08","en":"FORMAL FIT: law turns suitability into authority and into evidence that may be admitted.","cn":"形式化的相合：法律把适合变成权限，也变成可被采纳的证据。"},{"senses":"04 · 06","en":"OLD BODY AND OLD MONEY: fitness to march and a sufficient estate keep the earliest 'enough' sense.","cn":"旧时的身体与钱财：能行军的体能与足额的产业，保留最早的「足够」义。"},{"senses":"05","en":"HIDDEN KNOWLEDGE: linguistics reads the fit as rules known but not spoken.","cn":"隐藏知识：语言学把相合读成已知而未说出的规则。"},{"senses":"07","en":"TRUST: repeated meeting of the standard is what allows supervision to be removed.","cn":"信任：反复达到标准，才使监督得以撤走。"}]},"affixes":{"intro":{"en":"The adjective is a Latin prefix and root plus a participle ending, and the same pieces build the family, including the branch that became competition.","cn":"这个形容词由拉丁前缀、词根与分词词尾构成，同一批部件造出这个词族，包括分出去成为 competition 的一支。"},"latinIntro":{"en":"Com- and petere build competere, whose participle competens is the direct source of competent.","cn":"com- 与 petere 构成 competere，其分词 competens 是 competent 的直接来源。"},"items":[{"word":"com-","structure":"Latin prefix, 'together'","meaning":"together","meaningCN":"共同","example":"The prefix brings the two sides together.","exampleCN":"这个前缀把两方带到一起。"},{"word":"petere","structure":"Latin verb, third conjugation","meaning":"to seek, aim at","meaningCN":"寻求；指向","example":"Petere is the shared root.","exampleCN":"petere 是共享词根。"},{"word":"competere","structure":"com- + petere","meaning":"to meet, be suitable","meaningCN":"相遇；适合","example":"Competere is the base verb.","exampleCN":"competere 是基础动词。"},{"word":"competens","structure":"present participle, -ens ending","meaning":"meeting, suitable","meaningCN":"相遇的；适合的","example":"The participle ending is -ens.","exampleCN":"分词词尾表示进行与主动。"},{"word":"competent","structure":"competens through Latin","meaning":"fit for a duty","meaningCN":"胜任某项职责","example":"The adjective entered English in the sixteenth century.","exampleCN":"这个形容词于十六世纪进入英语。"},{"word":"competence","structure":"competent + -ence (state)","meaning":"the state of fitting","meaningCN":"相合的状态","example":"Competence is the noun of state.","exampleCN":"competence 是表状态的名词。"},{"word":"competently","structure":"competent + -ly (manner)","meaning":"in a fitting way","meaningCN":"以称职的方式","example":"She handled the case competently.","exampleCN":"她称职地处理了此案。"},{"word":"incompetent","structure":"in- + competent","meaning":"not fit for the duty","meaningCN":"不胜任职责","example":"Incompetent reverses the judgement.","exampleCN":"incompetent 反转了这个判断。"},{"word":"competition","structure":"com- + petere + -ition","meaning":"a seeking together for one prize","meaningCN":"同争一奖","example":"Competition is the contest branch.","exampleCN":"competition 是竞赛那一支。"}],"latinEntries":[{"word":"petere","structure":"petere, petivi, petitum (verb, third conjugation)","meaning":"to seek, aim at","meaningCN":"寻求；指向"},{"word":"competere","structure":"competere, competivi, competitum (verb, third conjugation)","meaning":"to meet, be suitable","meaningCN":"相遇；适合"},{"word":"competens","structure":"competens, competentis (present participle)","meaning":"meeting, suitable","meaningCN":"相遇的；适合的"}],"derivatives":[{"word":"competence","pos":"n.","zh":"能力；权限"},{"word":"competently","pos":"adv.","zh":"称职地"},{"word":"competency","pos":"n.","zh":"具体技能；胜任力项"},{"word":"incompetent","pos":"adj.","zh":"不胜任的"}]}},{"word":"competency","ipa_uk":"/ˈkɒmpɪtənsi/","ipa_us":"/ˈkɑːmpɪtənsi/","definition_zh":"单项胜任力；技能项；能力标准","definition_en":"a single named skill or behaviour standard that a role or course requires, treated as one item in a list","core_image":"一张能力清单钉在墙上，每一项后面都留着一格待勾的方框","scene":"招聘主管把岗位拆成若干可教可查的能力项，逐条写进面试评分表。The hiring panel scored each competency separately.","sceneCN":"招聘主管把岗位拆成可教可查的能力项写进评分表；句中的 competency 指「清单中的单项能力标准」（第 1 个义项：可单独培训与检验的技能项）。图中可辨识物件：能力清单、勾选框、面试评分表、笔。","pos":[{"tag":"n.","zh":"单项胜任力；技能项；能力标准"}],"collocations":[{"phrase":"core competency","zh":"核心能力项"},{"phrase":"competency framework","zh":"能力框架"},{"phrase":"competency model","zh":"胜任力模型"},{"phrase":"competency-based education","zh":"基于能力的教育"},{"phrase":"key competencies","zh":"关键能力项"},{"phrase":"competency standard","zh":"能力标准"}],"forms":[{"label":"复数","form":"competencies"},{"label":"同义变体","form":"competence"},{"label":"形容词","form":"competent"},{"label":"副词","form":"competently"}],"derivatives":[{"word":"competent","pos":"adj.","zh":"能胜任的"},{"word":"competence","pos":"n.","zh":"能力；权限"},{"word":"competently","pos":"adv.","zh":"称职地"},{"word":"incompetence","pos":"n.","zh":"不胜任"}],"senses":[{"no":"01","title":"A named skill in a list","titleCN":"清单中的具名技能","definition":"one skill or behaviour, written down so that it can be taught and checked","definitionCN":"一项可写下、可教、可查的技能或行为","example":"The hiring panel scored each competency separately.","exampleCN":"招聘小组对每一项能力分别评分。","why":"competency is the countable form: competence is the general fitness, while one competency is a single item that can be named.","whyCN":"competency 是可数形式：competence 指整体的胜任，competency 指一项可以命名的条目。"},{"no":"02","title":"An item in a human-resources framework","titleCN":"人力资源框架中的一项","definition":"a standard entry in a framework used for hiring, review and promotion","definitionCN":"用于招聘、评议与晋升的框架中的标准条目","example":"The new competency framework lists twelve items for managers.","exampleCN":"新的能力框架为管理者列出十二项。","why":"human resources turned the word into an inventory item, because a framework needs countable pieces rather than a vague quality.","whyCN":"人力资源把这个词变成库存条目，因为框架需要可数的部件，而非一种模糊的品质。"},{"no":"03","title":"A core competency of a firm","titleCN":"企业的核心能力项","definition":"one capability a company treats as central to its strategy","definitionCN":"企业视为战略核心的一项能力","example":"Designing quiet engines is the firm's core competency.","exampleCN":"设计安静的发动机是这家公司的核心能力。","why":"strategy borrowed the countable form because a firm must choose a few capabilities to be known for.","whyCN":"战略领域借用这个可数形式，因为企业必须选定少数几项能力来立身。"},{"no":"04","title":"Legal capacity, in variant spelling","titleCN":"法律上的资格（异体拼写）","definition":"the legal power to act, in the older spelling that still appears in some jurisdictions","definitionCN":"行动的法律权力，这一较旧拼写仍见于部分司法辖区","example":"The document uses competency for the court's power to act.","exampleCN":"这份文件用 competency 指法院的行动权力。","why":"the two spellings overlap here, so a legal text may use the countable-looking form for the uncountable idea.","whyCN":"两种拼写在此时重叠，因此法律文本可能用看似可数的形式表达不可数的概念。"},{"no":"05","title":"Demonstrated skill in assessment","titleCN":"评估中已证明的技能","definition":"a skill shown to an assessor through a task, not merely claimed on a form","definitionCN":"通过任务向评估者证明的技能，而非仅在表格上宣称","example":"Candidates must demonstrate each competency in a simulated shift.","exampleCN":"候选人须在模拟班次中证明每一项能力。","why":"assessment joins the word to proof: a competency is not possessed until it has been shown doing something.","whyCN":"评估把词与证据接上：一项能力在被做出来之前不算拥有。"},{"no":"06","title":"A teaching or clinical requirement","titleCN":"教学或临床的能力要求","definition":"a skill that a training programme requires before a learner may progress","definitionCN":"培训项目要求学习者在进阶前必须掌握的一项技能","example":"The nursing course certifies competency in wound care.","exampleCN":"护理课程对伤口护理的能力予以认证。","why":"training programmes need milestones, so each competency becomes a gate a learner must pass.","whyCN":"培训项目需要里程碑，于是每项能力都成为学习者必须通过的一道门。"},{"no":"07","title":"A behavioural model item","titleCN":"行为模型中的一项","definition":"a described pattern of behaviour, such as listening or giving feedback","definitionCN":"被描述出来的一类行为模式，如倾听或给出反馈","example":"The leadership model includes the competency of giving clear feedback.","exampleCN":"领导力模型包含「给出清晰反馈」这一能力项。","why":"when the item is behavioural, the standard describes what a person does, not only what a person knows.","whyCN":"当条目属于行为时，标准描述的是人做什么，而不只是人知道什么。"},{"no":"08","title":"A minimum standard for a stage","titleCN":"某一阶段的最低标准","definition":"the threshold skill a pupil must reach before moving on","definitionCN":"学生进阶前必须达到的门槛技能","example":"The district set a minimum competency in reading for each grade.","exampleCN":"该学区为每个年级设定了阅读的最低能力标准。","why":"education uses the countable form for a floor: a competency is something a learner either has or lacks at a given stage.","whyCN":"教育领域用可数形式表示地板：一项能力在学习者的某一阶段，要么具备，要么不具备。"}],"etymology":{"intro":{"en":"Competency is the countable branch of competence, built the same way from Latin competere 'to meet, be suitable', through the participle competens and the English suffix -ency. Its modern list sense grew in management and education. Dates are approximate.","cn":"competency 是 competence 的可数分支，同样来自拉丁 competere「相遇、适合」，经分词 competens 与英语中的名词后缀构成。其现代「清单条目」义在管理学与教育领域发展出来。年代为约数。"},"items":[{"era":"LATIN COMPETERE","en":"Com- 'together' plus petere 'to seek' gave competere 'to meet, be suitable, be sufficient'.","cn":"com-「共同」加 petere「寻求」给出 competere「相遇、适合、足够」。"},{"era":"COMPETENTIA","en":"The noun competentia named a meeting or a correspondence, the fit between two things.","cn":"名词 competentia 指相遇或对应，即两物之间的相合。"},{"era":"ENGLISH COMPETENCE","en":"English competence appeared in the sixteenth century for ability and authority, an uncountable quality.","cn":"英语 competence 于十六世纪出现，指能力与权限，是不可数的品质。"},{"era":"COUNTABLE BRANCH","en":"The spelling competency developed as a parallel form; from the nineteenth century it increasingly named a specific capacity that could be listed.","cn":"competency 这一拼写作为并行形式发展；从十九世纪起，它越来越多地指可被列出的一项具体能力。"},{"era":"MANAGEMENT AND EDUCATION","en":"In the twentieth century human resources and competency-based education made the word countable in earnest, so each skill became one item on a framework.","cn":"二十世纪，人力资源与「基于能力的教育」让这个词真正可数，每项技能成为框架中的一条。"},{"era":"SOURCE UNCERTAIN","en":"The reason the -ency spelling became the countable one is not fully documented; the split is conventional rather than logical. The deeper origin of petere remains uncertain, and forms offered for it are reconstructions.","cn":"为何是这一拼写承担可数义，缺乏完整记录；这一分工属约定俗成而非逻辑必然。petere 的更早来源仍不确定，为其给出的形式属重构。"}]},"similar":{"note":{"en":"Group one holds the two spellings that are often confused and the adjective behind them; group two holds words for skills and proof, each with a different unit.","cn":"第一组是常被混淆的两种拼写及其背后的形容词；第二组是技能与证明类词，计量单位各不相同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"competence","ipa":"/ˈkɒmpɪtəns/","tag":"the uncountable form","definition":"The general ability or legal authority; it does not normally name one item in a list.","definitionCN":"指整体能力或法定权限；通常不指清单中的某一项。"},{"word":"competent","ipa":"/ˈkɒmpɪtənt/","tag":"the adjective","definition":"Describes a person who meets the standard; competency is the item being measured.","definitionCN":"描述达到标准的人；competency 是被测量的条目。"},{"word":"competition","ipa":"/ˌkɒmpɪˈtɪʃən/","tag":"same root, other branch","definition":"A contest for one prize, from the same verb but with no sense of a skill item.","definitionCN":"指争一奖的竞赛，同出该动词，却毫无「技能项」之意。"},{"word":"incompetence","ipa":"/ɪnˈkɒmpɪtəns/","tag":"the negative","definition":"The lack of general ability, an uncountable judgement rather than a listed item.","definitionCN":"指缺乏整体能力，是不可数的判断而非清单条目。"}]},{"heading":"NEAR MEANING","entries":[{"word":"skill","ipa":"/skɪl/","tag":"learned technique","definition":"The everyday word for a learned ability; a competency is a skill written as an assessable standard.","definitionCN":"指学成的能力，是日常词；competency 是被写成可评估标准的技能。"},{"word":"capability","ipa":"/ˌkeɪpəˈbɪləti/","tag":"capacity","definition":"Often a broader capacity of a person or system, not necessarily certified.","definitionCN":"常指人或系统更宽的容量，未必经认证。"},{"word":"qualification","ipa":"/ˌkwɒlɪfɪˈkeɪʃən/","tag":"paper proof","definition":"The certificate or training that proves suitability; a competency is the ability itself.","definitionCN":"指证明适合的证书或训练；competency 是能力本身。"},{"word":"standard","ipa":"/ˈstændəd/","tag":"the required level","definition":"A required level of quality; a competency is one such standard tied to a skill.","definitionCN":"指要求的质量水平；competency 是与某项技能绑定的这样一条标准。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations here are the real countable split, the real management use and the real education use.","cn":"正常联想取自真实的可数分工、真实的管理用法与真实的教育用法。"},"normal":[{"en":"competence is the whole; one competency is one item on the list.","cn":"competence 是整体；一项 competency 是清单上的一条。"},{"en":"com- 'together' plus petere 'seek': a person and a task meeting.","cn":"com-「共同」加 petere「寻求」：人与任务相遇。"},{"en":"Human resources made it countable: a framework of named items.","cn":"人力资源让它可数：一份由具名条目组成的框架。"},{"en":"Education made it a gate: a minimum competency per stage.","cn":"教育把它变成一道门：每个阶段的最低能力。"},{"en":"The adjective stays competent; only the noun splits.","cn":"形容词仍是 competent；只有名词发生分工。"}],"abstract":[{"en":"Picture a wall chart of boxes, every box waiting for a tick.","cn":"想象墙上挂着一张方格表，每格都等着打勾。"},{"en":"Picture a job interview reduced to twelve lines and a score beside each.","cn":"想象一场面试被压缩成十二行，每行旁边一个分数。"},{"en":"Picture a ladder with a name written at every rung.","cn":"想象一把梯子，每一级都写着名字。"}]},"examples":[{"en":"The competency framework is reviewed every three years.","cn":"这套能力框架每三年复审一次。"},{"en":"Each competency must be demonstrated in a real setting.","cn":"每项能力都须在真实场景中证明。"},{"en":"Innovation is treated as a core competency of the group.","cn":"创新被视为该集团的核心能力。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「competent（能胜任的）+ cy」——把「能胜任」拆成一条条可勾选的项 → 技能项、能力标准","word":"competency"},"root":"拉丁 com-「共同」+ petere「寻求」→ competere「相遇、适合」→ competentia／competens → 英语 competence；其可数分支写作 competency，十九世纪后渐指可列出的单项能力。petere 的更早来源不确定，相关形式属重构。","sensesIntro":{"en":"Eight senses describe one list: a general fitness is cut into named items, and each item is then used for hiring, for a framework, for strategy, for legal capacity, for proof in assessment, for a training gate, for a behaviour model and for a minimum stage standard.","cn":"八个义项描述的是一张清单：整体胜任力被切成具名条目，每条随后用于招聘、框架、战略、法律资格、评估证明、培训门坎、行为模型与阶段最低标准。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wall chart of named boxes, each waiting for a tick, each tickable only after it has been shown.","cn":"核心意象：墙上挂着一张具名方格表，每格都等着打勾，而每一勾都只能在证明之后落下。"},"chain":["ABILITY","COUNT","ITEM","FRAMEWORK","PROOF","GATE"],"branches":[{"senses":"01 · 02","en":"THE ITEM: ability becomes countable, and the count becomes a human-resources framework.","cn":"条目：能力变得可数，计数又变成人力资源框架。"},{"senses":"03","en":"STRATEGY: a firm chooses a few items to be known for.","cn":"战略：企业选定少数几条来立身。"},{"senses":"04","en":"LAW: the older spelling survives in legal texts for power to act.","cn":"法律：较旧的拼写留存于法律文本，指行动权力。"},{"senses":"05 · 06","en":"PROOF AND TRAINING: an item counts only when shown, and training makes each item a gate.","cn":"证明与培训：条目只有被做出才作数，培训又把每条变成一道门。"},{"senses":"07 · 08","en":"BEHAVIOUR AND FLOOR: items can describe what a person does, and can set the minimum for a stage.","cn":"行为与地板：条目可以描述人做什么，也可以设定阶段的下限。"}]},"affixes":{"intro":{"en":"The noun is the countable branch of a Latin verb family, and its pieces still read clearly: a prefix, a root and a state suffix.","cn":"这个名词是一个拉丁动词词族的可数分支，其部件至今读得清楚：一个前缀、一个词根与一个表状态的后缀。"},"latinIntro":{"en":"Com- and petere build competere; competens gives the adjective, and the -ency suffix gives the countable noun.","cn":"com- 与 petere 构成 competere；competens 给出形容词，名词后缀给出可数名词。"},"items":[{"word":"com-","structure":"Latin prefix, 'together'","meaning":"together","meaningCN":"共同","example":"The prefix joins the two sides.","exampleCN":"这个前缀连接两方。"},{"word":"petere","structure":"Latin verb, third conjugation","meaning":"to seek, aim at","meaningCN":"寻求；指向","example":"Petere is the shared root.","exampleCN":"petere 是共享词根。"},{"word":"competere","structure":"com- + petere","meaning":"to meet, be suitable","meaningCN":"相遇；适合","example":"Competere is the base verb.","exampleCN":"competere 是基础动词。"},{"word":"competens","structure":"present participle of competere","meaning":"meeting, suitable","meaningCN":"相遇的；适合的","example":"Competens gives the adjective.","exampleCN":"competens 给出形容词。"},{"word":"competence","structure":"competent + -ence (state)","meaning":"general fitness or authority","meaningCN":"整体的胜任或权限","example":"Competence is the uncountable form.","exampleCN":"competence 是不可数形式。"},{"word":"competency","structure":"competent + -ency (state)","meaning":"one named skill or standard","meaningCN":"一项具名技能或标准","example":"Competency is the countable branch.","exampleCN":"competency 是可数分支。"},{"word":"competencies","structure":"plural of competency","meaning":"several named skills","meaningCN":"多项具名技能","example":"The list has twelve competencies.","exampleCN":"清单上有十二项能力。"},{"word":"competent","structure":"competens through Latin","meaning":"fit for a duty","meaningCN":"胜任职责","example":"The adjective serves both nouns.","exampleCN":"这个形容词服务两个名词。"},{"word":"competently","structure":"competent + -ly (manner)","meaning":"in a fitting way","meaningCN":"以称职的方式","example":"He acted competently.","exampleCN":"他行事称职。"}],"latinEntries":[{"word":"petere","structure":"petere, petivi, petitum (verb, third conjugation)","meaning":"to seek, aim at","meaningCN":"寻求；指向"},{"word":"competere","structure":"competere, competivi, competitum (verb, third conjugation)","meaning":"to meet, be suitable","meaningCN":"相遇；适合"},{"word":"competentia","structure":"competentia, competentiae (f., first declension)","meaning":"a meeting, a fitting","meaningCN":"相遇；相合"}],"derivatives":[{"word":"competent","pos":"adj.","zh":"能胜任的"},{"word":"competence","pos":"n.","zh":"能力；权限"},{"word":"competently","pos":"adv.","zh":"称职地"},{"word":"incompetence","pos":"n.","zh":"不胜任"}]}},{"word":"certificate","ipa_uk":"/səˈtɪfɪkət/","ipa_us":"/sərˈtɪfɪkət/","definition_zh":"证书；证明书；凭单；（动词）发证确认","definition_en":"an official document that states a fact as true, or the act of confirming something formally in writing","core_image":"一张压着凸纹印章的纸，旁边放着登记簿与钢印器","scene":"办事员核对完课程记录，把一张盖了钢印的纸递出窗口。The clerk issued a certificate for each completed course.","sceneCN":"办事员核对课程记录后递出盖了钢印的纸；句中的 certificate 指「正式证明某项事实的文书」（第 1 个义项：官方出具的证明文件）。图中可辨识物件：证书、钢印、登记簿、窗口。","pos":[{"tag":"n.","zh":"证书；证明书；凭单"},{"tag":"vt.","zh":"发证给；以证书确认"}],"collocations":[{"phrase":"birth certificate","zh":"出生证明"},{"phrase":"death certificate","zh":"死亡证明"},{"phrase":"professional certificate","zh":"职业证书"},{"phrase":"certificate of completion","zh":"结业证书"},{"phrase":"share certificate","zh":"股票凭证"},{"phrase":"issue a certificate","zh":"签发证书"}],"forms":[{"label":"复数","form":"certificates"},{"label":"动词原形（读音不同）","form":"certificate"},{"label":"动词三单","form":"certificates"},{"label":"动词过去式","form":"certificated"},{"label":"动词过去分词","form":"certificated"},{"label":"动词现在分词","form":"certificating"},{"label":"形容词（持有证书的）","form":"certificated"}],"derivatives":[{"word":"certification","pos":"n.","zh":"认证；证明"},{"word":"certify","pos":"v.","zh":"证明；认证"},{"word":"certified","pos":"adj.","zh":"经认证的"},{"word":"certificated","pos":"adj.","zh":"持有证书的"},{"word":"certifier","pos":"n.","zh":"证明人；认证机构"}],"senses":[{"no":"01","title":"An official document of fact","titleCN":"正式证明某项事实的文书","definition":"a document issued by an authority to state that a fact is true","definitionCN":"由权威机构出具、声明某项事实为真的文件","example":"The clerk issued a certificate for each completed course.","exampleCN":"办事员为每门完成的课程签发一张证书。","why":"certificare meant 'to make certain', so a certificate is literally a paper that makes a matter certain to anyone who reads it.","whyCN":"certificare 意为「使确定」，因此 certificate 字面上就是一张让读到它的人对某事确定下来的纸。"},{"no":"02","title":"An academic award","titleCN":"学业证书；文凭","definition":"a document recording a qualification, a degree or a completed course","definitionCN":"记录资格、学位或已完成课程的文件","example":"She framed her degree certificate above the desk.","exampleCN":"她把学位证书装框挂在书桌上方。","why":"schools issue the word in its most familiar form, where a piece of paper stands for years of work.","whyCN":"学校签发这个词最熟悉的形态，此时一张纸代表多年的功夫。"},{"no":"03","title":"A professional licence","titleCN":"职业执照类证书","definition":"a document that allows someone to practise a regulated occupation","definitionCN":"允许某人从事受监管职业的文件","example":"No one may install gas lines without a certificate.","exampleCN":"没有证书者不得安装燃气管道。","why":"a profession uses the document as a gate: the paper is checked before the work is allowed.","whyCN":"行业把这个文件当作闸门：先查纸，再允许开工。"},{"no":"04","title":"A civil record","titleCN":"民事登记证明","definition":"a document recording a birth, a marriage or a death","definitionCN":"记录出生、婚姻或死亡的文件","example":"The hospital filed the birth certificate the same day.","exampleCN":"医院当天就归档了出生证明。","why":"the state's oldest use is the civil record, where a certificate fixes an event in law.","whyCN":"国家最古老的用法是民事登记：证书把一起事件固定在法律上。"},{"no":"05","title":"A financial instrument","titleCN":"金融凭证","definition":"a document representing ownership of shares, bonds or deposits","definitionCN":"代表股份、债券或存款所有权的文件","example":"The old share certificate hung framed in the boardroom.","exampleCN":"那张旧股票凭证装框挂在董事会议室里。","why":"finance borrowed the paper form: ownership used to exist only as a certificate that could be held and transferred.","whyCN":"金融借用了纸质形态：所有权曾只存在于一张可持有、可转让的凭证里。"},{"no":"06","title":"A record of completion","titleCN":"完成事项的凭据","definition":"a document confirming that a course, a training or a task was finished","definitionCN":"确认课程、培训或任务已完成的文件","example":"Trainees receive a certificate of completion at the end.","exampleCN":"受训者在结束时领取结业证书。","why":"completion certificates certify an event rather than a standard, which is why they carry less weight than licences.","whyCN":"结业证书证明的是一次事件而非一项水平，因此其分量低于执照。"},{"no":"07","title":"A digital security certificate","titleCN":"数字安全证书","definition":"an electronic file that proves a website's identity to a browser","definitionCN":"向浏览器证明某个网站身份的电子文件","example":"The browser rejected the site because its certificate had expired.","exampleCN":"浏览器拒绝了这个网站，因为它的证书已过期。","why":"computing kept the logic of the seal: a trusted third party vouches for identity, and the file is checked automatically.","whyCN":"计算领域保留了印章的逻辑：可信第三方为身份作保，文件被自动核查。"},{"no":"08","title":"To confirm in writing","titleCN":"以书面正式确认","definition":"to issue a certificate for something, or to record it officially","definitionCN":"为某事签发证书，或正式记录在案","example":"The board certificated the new training programme.","exampleCN":"董事会为新的培训项目发了证书。","why":"the verb is the noun turned around: instead of receiving the paper, an authority puts its seal on the fact.","whyCN":"动词用法把名词翻了个面：不是领取那张纸，而是权威方把印盖在事实上。"}],"etymology":{"intro":{"en":"Certificate comes from Latin certificare 'to make certain', built on certus 'certain' and facere 'to make'. The noun is the Latin past participle certificatum used as a name for the document. Dates are approximate.","cn":"certificate 来自拉丁 certificare「使确定」，由 certus「确定的」与 facere「使、做」构成。名词是拉丁过去分词 certificatum 被用作文件之名。年代为约数。"},"items":[{"era":"LATIN CERTUS","en":"Certus meant 'settled, decided, sure'. It is related to cernere 'to sift, to distinguish, to decide', so certainty began as the act of separating one thing from another.","cn":"certus 意为「已定的、决断的、确定的」，与 cernere「筛、分辨、裁决」相关，因此「确定」最初是分辨彼此的动作。"},{"era":"LATIN CERTIFICARE","en":"Certus plus facere produced certificare 'to make certain, to assure'. The verb is about producing certainty in someone's mind.","cn":"certus 加 facere 产生 certificare「使确定、向人保证」。这个动词关乎在别人心里造出确定感。"},{"era":"PAST PARTICIPLE CERTIFICATUM","en":"The past participle certificatum named a matter that had been made certain; English took the form as a noun for the paper that carries the assurance.","cn":"过去分词 certificatum 指已被确定之事；英语把这个形式用作名词，指承载这份保证的纸。"},{"era":"FIFTEENTH-CENTURY ENGLISH","en":"Certificate appears in English in the fifteenth century, first for a formal statement by an authority and soon for civil and academic records.","cn":"certificate 于十五世纪出现在英语中，先指权威方的正式声明，很快又指民事与学业记录。"},{"era":"FINANCE AND COMPUTING","en":"In the nineteenth century the word named share and bond documents; in the late twentieth century it was applied to electronic files that vouch for identity.","cn":"十九世纪，这个词指股票与债券凭证；二十世纪后期，它被用于为身份作保的电子文件。"},{"era":"SOURCE UNCERTAIN","en":"The link between certus and cernere is generally accepted, but the deeper origin of cernere is uncertain, and any pre-Latin form offered for it is a reconstruction. The exact first English use for an academic award is not settled.","cn":"certus 与 cernere 之间的联系一般认为是可靠的，但 cernere 的更早来源不确定，为其给出的拉丁语之前形式属重构。英语中用于学业证书的确切最早书证尚无定论。"}]},"similar":{"note":{"en":"Group one holds the act, the adjective and two look-alikes that differ in what they describe; group two holds other documents of proof, each with a different scope.","cn":"第一组是认证行为、形容词，以及两个所指不同的形近词；第二组是其他证明文件，范围各不相同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"certification","ipa":"/ˌsɜːtɪfɪˈkeɪʃən/","tag":"the act","definition":"The process of certifying, not the paper itself; a certificate is the result of certification.","definitionCN":"指认证的过程，而非那张纸；certificate 是认证的结果。"},{"word":"certify","ipa":"/ˈsɜːtɪfaɪ/","tag":"the verb","definition":"To state officially that something is true; certificate as a verb is narrower and means to issue the paper.","definitionCN":"指正式声明某事为真；certificate 作动词较窄，专指签发那张纸。"},{"word":"certified","ipa":"/ˈsɜːtɪfaɪd/","tag":"having been certified","definition":"Describes something that has passed certification, often a person or a product.","definitionCN":"描述已通过认证的人或产品。"},{"word":"certificated","ipa":"/səˈtɪfɪkeɪtɪd/","tag":"holding a certificate","definition":"Describes a person who holds a particular certificate, especially in British usage.","definitionCN":"描述持有某类证书的人，尤见于英式用法。"}]},{"heading":"NEAR MEANING","entries":[{"word":"credential","ipa":"/krəˈdenʃəl/","tag":"proof of trust","definition":"A document or record showing fitness or trustworthiness, often broader than one certificate.","definitionCN":"指显示资格或可信度的文件或记录，常比单张证书更宽。"},{"word":"diploma","ipa":"/dɪˈpləʊmə/","tag":"folded paper","definition":"Specifically an academic award for a completed course or degree, narrower than certificate.","definitionCN":"特指完成课程或学位所得的学业证书，比 certificate 窄。"},{"word":"licence","ipa":"/ˈlaɪsəns/","tag":"permission to act","definition":"Legal permission to do something; a certificate may be the paper that carries it.","definitionCN":"指做某事的法律许可；certificate 可能是承载它的那张纸。"},{"word":"permit","ipa":"/pəˈmɪt/","tag":"entry or action allowed","definition":"A document allowing a specific act, such as building or entering, usually narrower and shorter-lived.","definitionCN":"允许某项具体行为的文件，如施工或入境，通常更窄且期限更短。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations here are the real 'make certain' core, the real paper forms and the real modern digital use.","cn":"正常联想取自真实的「使确定」内核、真实的纸质形态与真实的现代数字用法。"},"normal":[{"en":"certus 'certain' plus facere 'make': a paper that makes a fact certain.","cn":"certus「确定的」加 facere「使」：一张使事实确定下来的纸。"},{"en":"The noun is a Latin past participle: the thing already made certain.","cn":"这个名词是拉丁过去分词：已被确定下来的东西。"},{"en":"The family runs certify, certification, certified, certificated.","cn":"词族包括 certify、certification、certified、certificated。"},{"en":"Fixed phrases mark the domains: birth certificate, share certificate, certificate of completion.","cn":"固定搭配标出领域：出生证明、股票凭证、结业证书。"},{"en":"The digital certificate repeats the seal: a trusted third party vouches for identity.","cn":"数字证书重复了印章的逻辑：可信第三方为身份作保。"}],"abstract":[{"en":"Picture a wax seal pressed onto a page while the ink is still wet.","cn":"想象墨迹未干时，一枚火漆印压到纸页上。"},{"en":"Picture a filing cabinet where every drawer holds one event of a life.","cn":"想象一只档案柜，每个抽屉装着人生中的一起事件。"},{"en":"Picture a browser window slamming shut because a hidden seal has expired.","cn":"想象浏览器窗口砰地关上，只因一枚看不见的印章过期了。"}]},"examples":[{"en":"The embassy requires a certificate of birth for the application.","cn":"使馆要求申请中附出生证明。"},{"en":"Her certificate is recognised in four countries.","cn":"她的证书在四个国家获得承认。"},{"en":"The inspector certificated the building after the final check.","cn":"检查员在终检之后为这栋楼发了合格证。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「cert（确定）+ fic（做）」——把「确定」做成一张纸 → 证书、证明","word":"certificate"},"root":"拉丁 certus「确定的」（与 cernere「分辨」相关）+ facere「做」→ certificare「使确定」→ 过去分词 certificatum → 英语 certificate；cernere 的更早来源不确定，为其给出的拉丁语之前形式属重构。","sensesIntro":{"en":"Eight senses follow one seal: a fact is made certain on paper, and the paper is then used for a course, a degree, a licence, a civil event, a share, a completion, a website's identity and finally for the act of sealing itself.","cn":"八个义项沿同一枚印章展开：一个事实在纸上被确定下来，这张纸随后用于课程、学位、执照、民事事件、股份、完成事项、网站身份，最后用于「盖章确认」这一动作本身。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wax seal pressed onto a page while the ink is still wet, with a register open beside it.","cn":"核心意象：墨迹未干时一枚火漆印压上纸页，旁边摊着登记簿。"},"chain":["CERTAIN","PAPER","AUTHORITY","RECORD","LICENCE","IDENTITY"],"branches":[{"senses":"01 · 02","en":"THE PAPER: a fact made certain, and a course remembered as a framed sheet.","cn":"纸面：事实被确定，课程被记成一张装框的纸。"},{"senses":"03","en":"THE GATE: a regulated trade checks the paper before work begins.","cn":"闸门：受监管行业先查纸，再开工。"},{"senses":"04 · 06","en":"TWO RECORDS: a birth fixes an event in law, a completion certifies that something ended.","cn":"两种记录：出生把事件固定在法律上，结业证明某事已结束。"},{"senses":"05","en":"THE INSTRUMENT: ownership itself once existed only as a held certificate.","cn":"凭证：所有权曾只作为一张可持有的证书存在。"},{"senses":"07 · 08","en":"IDENTITY AND ACT: a trusted third party vouches for a website, and an authority seals the fact.","cn":"身份与动作：可信第三方为网站作保，权威方则为事实盖章。"}]},"affixes":{"intro":{"en":"The word is two Latin pieces plus a participle ending, and both pieces also build English families of their own.","cn":"这个词由两个拉丁部件加一个分词词尾构成，两个部件各自也造出英语词族。"},"latinIntro":{"en":"Certus and cernere supply the certainty half; facere supplies the making half, and the participle ending -atum turns the verb into the document.","cn":"certus 与 cernere 提供「确定」这一半；facere 提供「使、做」这一半，分词词尾把动词变成那份文件。"},"items":[{"word":"certus","structure":"Latin adjective","meaning":"settled, sure","meaningCN":"已定的；确定的","example":"Certus is the first half of the word.","exampleCN":"certus 是这个词的前半。"},{"word":"cernere","structure":"Latin verb, third conjugation","meaning":"to sift, distinguish, decide","meaningCN":"筛；分辨；裁决","example":"Cernere is the root behind certus.","exampleCN":"cernere 是 certus 背后的词根。"},{"word":"facere","structure":"Latin verb, third conjugation","meaning":"to make, do","meaningCN":"做；使","example":"Facere is the second half.","exampleCN":"facere 是后半。"},{"word":"certificare","structure":"certus + facere","meaning":"to make certain","meaningCN":"使确定","example":"The verb is the source of the family.","exampleCN":"这个动词是词族的来源。"},{"word":"certificatum","structure":"past participle of certificare","meaning":"made certain","meaningCN":"已被确定的","example":"The participle became the noun.","exampleCN":"这个分词变成名词。"},{"word":"certificate","structure":"certificatum used as a noun","meaning":"a document that assures a fact","meaningCN":"证明某项事实的文件","example":"The certificate carries the seal.","exampleCN":"证书承载印章。"},{"word":"certify","structure":"certificare through French","meaning":"to declare officially","meaningCN":"正式声明","example":"The board certified the result.","exampleCN":"委员会认证了结果。"},{"word":"certification","structure":"certify + -ation (action)","meaning":"the act of certifying","meaningCN":"认证的行为","example":"Certification precedes the paper.","exampleCN":"认证先于那张纸。"},{"word":"certificated","structure":"certificate + -ed (having)","meaning":"holding a certificate","meaningCN":"持有证书的","example":"A certificated teacher may apply.","exampleCN":"持有证书的教师可以申请。"}],"latinEntries":[{"word":"certus","structure":"certus, certa, certum (adj.)","meaning":"settled, sure","meaningCN":"已定的；确定的"},{"word":"certificare","structure":"certificare, certificavi, certificatum (verb, first conjugation)","meaning":"to make certain","meaningCN":"使确定"},{"word":"certificatum","structure":"certificatum (n., past participle used as noun)","meaning":"a certified statement","meaningCN":"经确认的声明"}],"derivatives":[{"word":"certification","pos":"n.","zh":"认证；证明"},{"word":"certify","pos":"v.","zh":"证明；认证"},{"word":"certified","pos":"adj.","zh":"经认证的"},{"word":"certificated","pos":"adj.","zh":"持有证书的"},{"word":"certifier","pos":"n.","zh":"证明人；认证机构"}]}},{"word":"credential","ipa_uk":"/krəˈdenʃəl/","ipa_us":"/krəˈdenʃəl/","definition_zh":"资格证书；资历证明；凭证","definition_en":"a document or record that shows a person's qualifications, training or right to be trusted","core_image":"一只打开的皮夹，里面夹着证件、推荐信与一张芯片卡","scene":"雇主在面试前先核验学历与执业记录，确认无误才安排面谈。The board verified every credential before the appointment.","sceneCN":"雇主在面试前核验学历与执业记录，确认无误才面谈；句中的 credential 指「证明资历与可信度的材料」（第 1 个义项：记录资格的文件或凭据）。图中可辨识物件：皮夹、证件、推荐信、芯片卡。","pos":[{"tag":"n.","zh":"资格证书；资历证明；凭证"},{"tag":"vt.","zh":"为……提供资历证明；授予资格"}],"collocations":[{"phrase":"professional credentials","zh":"职业资历"},{"phrase":"academic credentials","zh":"学历资历"},{"phrase":"credential verification","zh":"资历核验"},{"phrase":"login credentials","zh":"登录凭据"},{"phrase":"present credentials","zh":"呈递国书"},{"phrase":"credential committee","zh":"资格审查委员会"}],"forms":[{"label":"复数","form":"credentials"},{"label":"动词原形","form":"credential"},{"label":"动词过去式","form":"credentialed"},{"label":"动词过去分词","form":"credentialed"},{"label":"动词现在分词","form":"credentialing"},{"label":"形容词","form":"credentialed"}],"derivatives":[{"word":"credentials","pos":"n.","zh":"资历证明；国书"},{"word":"credentialed","pos":"adj.","zh":"有资质的"},{"word":"credentialing","pos":"n.","zh":"资格认定"},{"word":"credit","pos":"n.","zh":"信用；学分"},{"word":"credible","pos":"adj.","zh":"可信的"}],"senses":[{"no":"01","title":"A documented qualification","titleCN":"记录在案的资格","definition":"a paper or record that proves a person's training or right to practise","definitionCN":"证明某人受过训练或有执业资格的文件或记录","example":"The board verified every credential before the appointment.","exampleCN":"董事会在任命前核验了每一份资历证明。","why":"credere meant 'to believe, to entrust', so a credential is literally something that gives you reason to trust the bearer.","whyCN":"credere 意为「相信、托付」，因此 credential 字面上就是让你有理由信任持有者的东西。"},{"no":"02","title":"Letters of accreditation","titleCN":"（复数）国书；委任状","definition":"the formal papers by which an envoy or a delegate is accredited","definitionCN":"授予使节或代表正式身份的文书","example":"The ambassador presented her credentials at the palace.","exampleCN":"大使在宫中呈递了国书。","why":"diplomacy kept the oldest plural use: letters that vouch for a person's right to speak for a state.","whyCN":"外交保留了最古老的复数用法：为某人代表国家的权利作保的信件。"},{"no":"03","title":"Evidence of trustworthiness","titleCN":"可信度的证据","definition":"anything that gives others reason to rely on a person or an institution","definitionCN":"任何使他人有理由依赖某人或某机构的东西","example":"Years of clean audits became his strongest credential.","exampleCN":"多年无瑕疵的审计记录成了他最有力的信誉凭据。","why":"the word widened from paper to reputation: whatever makes trust reasonable can be called a credential.","whyCN":"这个词从纸面扩展到声誉：凡使信任变得合理的东西都可称为凭据。"},{"no":"04","title":"A professional credential","titleCN":"职业资格","definition":"a licence or certificate required to work in a regulated field","definitionCN":"在受监管领域工作所需的执照或证书","example":"The hospital checks the credentials of every surgeon.","exampleCN":"医院核查每位外科医生的职业资格。","why":"regulated work turns trust into a document, and the document is checked before a patient is handed over.","whyCN":"受监管的工作把信任变成文件，并在把病人交出去之前核查这份文件。"},{"no":"05","title":"A digital login credential","titleCN":"数字登录凭据","definition":"the username, password or key that proves a user's identity to a system","definitionCN":"向系统证明用户身份的用户名、密码或密钥","example":"Never store login credentials in a shared file.","exampleCN":"切勿把登录凭据存放在共享文件里。","why":"computing extended the word to identity itself: the system must be convinced that the user is who the account says.","whyCN":"计算领域把这个词扩展到身份本身：系统必须被说服，用户就是账号所称的那个人。"},{"no":"06","title":"Diplomatic papers","titleCN":"外交文书","definition":"the documents that establish an official's status in a foreign state","definitionCN":"在外国确立某官员身份的文书","example":"The delegation's credentials were accepted without delay.","exampleCN":"代表团的国书被立即接受。","why":"the same plural form serves diplomacy, where a state must vouch for the person who speaks in its name.","whyCN":"同一复数形式在外交中使用：国家必须为以其名义发言的人作保。"},{"no":"07","title":"An academic record","titleCN":"学历资历","definition":"the degrees, transcripts and honours that record a student's study","definitionCN":"记录一个人求学经历的学位、成绩单与荣誉","example":"Her academic credentials opened the door to the programme.","exampleCN":"她的学历资历为她打开了这个项目的大门。","why":"schools kept the oldest sense of a record that stands for a person: the transcript is the paper form of years of study.","whyCN":"学校保留了最古老的「代人之记录」义：成绩单就是多年求学的纸面形态。"},{"no":"08","title":"To provide with credentials","titleCN":"为……提供资历证明","definition":"to supply someone with the papers that establish their standing","definitionCN":"为某人提供确立其身份与地位的文件","example":"The institute credentialed the new instructors in June.","exampleCN":"研究所在六月为新讲师颁发了资质证明。","why":"the verb of the same spelling was formed later, and it names the authority's side of the transaction rather than the bearer's.","whyCN":"同一拼写的动词形式出现较晚，命名的是权威方在这一往来中的一侧，而非持有者一侧。"}],"etymology":{"intro":{"en":"Credential comes from Medieval Latin credentialis, from Latin credentia 'belief, trust', built on credere 'to believe, to entrust'. The plural credentials named letters that accredited a envoy. Dates are approximate.","cn":"credential 来自中世纪拉丁 credentialis，源自拉丁 credentia「相信、信任」，由 credere「相信、托付」构成。复数 credentials 原指为使节授信的文书。年代为约数。"},"items":[{"era":"LATIN CREDERE","en":"Credere meant 'to believe, to trust, to entrust'. It is the root of creed, credit and incredible, all built on the act of trusting.","cn":"credere 意为「相信、信任、托付」，是 creed、credit 与 incredible 的词根，都建立在「信任」这一动作上。"},{"era":"LATIN CREDENTIA","en":"Credentia named belief or trust, and in church use also a letter of recommendation carried by a traveller.","cn":"credentia 指相信或信任，在教会用法中也指旅人随身携带的推荐信。"},{"era":"MEDIEVAL LATIN CREDENTIALIS","en":"Credentialis described what gives credit or standing; the neuter plural credentialia became the set of papers carried by an envoy.","cn":"credentialis 描述给予信用或身份之物；中性复数 credentialia 变为使节携带的一整套文书。"},{"era":"ENGLISH CREDENTIAL","en":"English took credential in the sixteenth century, first in the diplomatic plural and later as any proof of qualification.","cn":"英语在十六世纪吸收 credential，先用于外交复数，后指任何资格证明。"},{"era":"MODERN EXTENSIONS","en":"In the twentieth century the word spread to professional licensing and academic records, and in computing to the data that proves a user's identity.","cn":"二十世纪，这个词扩展到职业执照与学历记录，在计算领域则指证明用户身份的数据。"},{"era":"SOURCE UNCERTAIN","en":"The deeper origin of credere is uncertain; the common connection to a root meaning 'to place one's heart' is a reconstruction. The exact route from church letters to professional qualifications is only partly documented.","cn":"credere 的更早来源不确定；常被提到的、与表示「把心放上」的词根的联系属重构形式。从教会文书到职业资格的演变路径只有部分记录。"}]},"similar":{"note":{"en":"Group one holds words from the same believing root, each with a different job; group two holds other proofs of standing, which differ in what they guarantee.","cn":"第一组同出「相信」这一词根，各司不同职守；第二组是其他身份证明，所保证的内容各不相同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"credentials","ipa":"/krəˈdenʃəlz/","tag":"the plural","definition":"The collected papers of standing, especially diplomatic letters; modern usage treats it as a mass noun.","definitionCN":"指成套的身份文书，尤指国书；现代用法把它当作不可数集合名词。"},{"word":"credit","ipa":"/ˈkredɪt/","tag":"same root, money sense","definition":"Trust turned into financial terms: the belief that a debt will be paid.","definitionCN":"信任转为金融术语：相信欠款会偿付。"},{"word":"creed","ipa":"/kriːd/","tag":"same root, belief","definition":"A statement of what is believed, from the same verb but with no notion of papers.","definitionCN":"指所信内容的陈述，同出该动词，却无文书之意。"},{"word":"credibility","ipa":"/ˌkredəˈbɪləti/","tag":"quality, not paper","definition":"The quality of being believable; a credential is an object that supports it.","definitionCN":"指可信的性质；credential 是支撑这份性质的具体物件。"}]},{"heading":"NEAR MEANING","entries":[{"word":"certificate","ipa":"/səˈtɪfɪkət/","tag":"one document","definition":"A single official document stating a fact; a credential may be a whole record of standing.","definitionCN":"指声明某项事实的单一正式文件；credential 可以是一整套身份记录。"},{"word":"qualification","ipa":"/ˌkwɒlɪfɪˈkeɪʃən/","tag":"the training","definition":"The training or exam passed, spoken of as an ability rather than a paper.","definitionCN":"指通过的训练或考试，说的是能力而非纸张。"},{"word":"licence","ipa":"/ˈlaɪsəns/","tag":"permission","definition":"Legal permission to act; the credential may be the paper that carries the permission.","definitionCN":"指行动的法律许可；credential 可能是承载许可的纸。"},{"word":"reference","ipa":"/ˈrefrəns/","tag":"someone's word","definition":"A statement from a third party about a person, which vouches without being an official document.","definitionCN":"指第三方对某人的陈述，能作保但不是正式文件。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations here are the real believing root, the real diplomatic plural and the real modern digital sense.","cn":"正常联想取自真实的「相信」词根、真实的外交复数用法与真实的现代数字义。"},"normal":[{"en":"credere 'to believe': a credential gives you a reason to believe the bearer.","cn":"credere「相信」：credential 给你理由相信持有者。"},{"en":"The plural began as diplomatic letters carried by an envoy.","cn":"复数形式最初是使节携带的外交文书。"},{"en":"The family runs credit, creed, credible, credibility, incredible.","cn":"词族包括 credit、creed、credible、credibility、incredible。"},{"en":"Fixed phrases mark the checks: credential verification, professional credentials, academic credentials.","cn":"固定搭配标出核验场景：资历核验、职业资历、学历资历。"},{"en":"Computing uses it for the password that proves who you are.","cn":"计算领域用它指证明「你是谁」的密码。"}],"abstract":[{"en":"Picture a wallet whose every card is a small argument for trusting its owner.","cn":"想象一只钱包，每张卡都是「请信任此人」的一小段论证。"},{"en":"Picture a sealed letter handed over at a palace gate.","cn":"想象一封密封的信在宫门处被递出。"},{"en":"Picture a system asking who you are before it will open a single door.","cn":"想象一个系统在开任何一扇门之前先问「你是谁」。"}]},"examples":[{"en":"The panel reviewed her academic credentials and two references.","cn":"小组审阅了她的学历资历与两封推荐信。"},{"en":"No credential substitutes for a clean safety record.","cn":"任何资历证明都替代不了一份无事故的安全记录。"},{"en":"The platform stores credentials in an encrypted vault.","cn":"该平台把登录凭据存放在加密保险库中。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「cred（相信）」——让人有理由相信你的那套材料 → 资历证明、资格证书","word":"credential"},"root":"拉丁 credere「相信、托付」→ credentia「信任」→ 中世纪拉丁 credentialis／credentialia（使节文书）→ 英语 credential；credere 的更早来源不确定，与「把心放上」词根的联系属重构形式。","sensesIntro":{"en":"Eight senses follow one paper trail: something makes trust reasonable, and that something can be a qualification, an envoy's letters, a clean record, a licence, a password, a diplomatic document, a transcript or the act of supplying the papers.","cn":"八个义项沿同一条纸面线索展开：某物使信任变得合理，而这个某物可以是资格、使节文书、清白记录、执照、密码、外交文件、成绩单，或「提供这些材料」这一动作。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wallet in which every card is a small argument for trusting the person who carries it.","cn":"核心意象：一只钱包，每张卡都是「请信任此人」的一小段论证。"},"chain":["BELIEVE","PROOF","PAPER","OFFICE","IDENTITY","ACCESS"],"branches":[{"senses":"01 · 03","en":"PROOF: training records and clean audits both give reason to trust.","cn":"证明：训练记录与清白审计都给出信任的理由。"},{"senses":"02 · 06","en":"THE ENVOY: the plural began as letters that let a person speak for a state.","cn":"使节：复数最初是让人代表国家发言的文书。"},{"senses":"04 · 07","en":"THE PROFESSIONS: a licence and a transcript are the same proof inside different gates.","cn":"行业：执照与成绩单是不同闸门内的同一种证明。"},{"senses":"05","en":"THE MACHINE: computing asks for proof of identity before opening a door.","cn":"机器：计算领域在开门前要求身份证明。"},{"senses":"08","en":"THE ACT: an authority supplies the papers, turning standing into something that can be shown.","cn":"动作：权威方提供文件，把身份变成可出示之物。"}]},"affixes":{"intro":{"en":"The word is one Latin root plus a noun and an adjective suffix, and the root also builds a large family around trusting.","cn":"这个词由一个拉丁词根加名词与形容词后缀构成，该词根还造出一大族围绕「信任」的词。"},"latinIntro":{"en":"Credere builds credentia, whose Medieval Latin adjective credentialis gives the English noun; the same root gives credit and creed.","cn":"credere 构成 credentia，其中世纪拉丁形容词 credentialis 给出英语名词；同一词根给出 credit 与 creed。"},"items":[{"word":"credere","structure":"Latin verb, third conjugation","meaning":"to believe, entrust","meaningCN":"相信；托付","example":"Credere is the root of the family.","exampleCN":"credere 是这个词族的根。"},{"word":"credentia","structure":"credere + -entia (state)","meaning":"belief, trust","meaningCN":"相信；信任","example":"Credentia gave the Medieval Latin adjective.","exampleCN":"credentia 给出中世纪拉丁形容词。"},{"word":"credentialis","structure":"credentia + -alis (of)","meaning":"of trust, giving credit","meaningCN":"关于信任的；给予信用的","example":"Credentialis became English credential.","exampleCN":"credentialis 变成英语 credential。"},{"word":"credential","structure":"credentialis through Medieval Latin","meaning":"a proof of standing","meaningCN":"身份或资历的证明","example":"The noun entered English in the sixteenth century.","exampleCN":"这个名词于十六世纪进入英语。"},{"word":"credentials","structure":"plural of credential","meaning":"letters of accreditation","meaningCN":"国书；委任文书","example":"The plural kept the diplomatic sense.","exampleCN":"复数保留了外交义。"},{"word":"credentialed","structure":"credential + -ed (having)","meaning":"holding credentials","meaningCN":"持有资历证明的","example":"Only credentialed staff may sign.","exampleCN":"只有具备资质的人员可以签署。"},{"word":"credentialing","structure":"credential + -ing (process)","meaning":"the process of certifying","meaningCN":"资格认定的过程","example":"Credentialing takes six weeks.","exampleCN":"资格认定需要六周。"},{"word":"credit","structure":"credere through French","meaning":"trust in payment","meaningCN":"偿付上的信任","example":"Credit is the money sense of trust.","exampleCN":"credit 是「信任」的金钱义。"},{"word":"creed","structure":"credo, from credere","meaning":"a statement of belief","meaningCN":"信念的陈述","example":"Creed is the belief sense without papers.","exampleCN":"creed 是没有文书的信念义。"}],"latinEntries":[{"word":"credere","structure":"credere, credidi, creditum (verb, third conjugation)","meaning":"to believe, entrust","meaningCN":"相信；托付"},{"word":"credentia","structure":"credentia, credentiae (f., first declension)","meaning":"belief, trust","meaningCN":"相信；信任"},{"word":"credentialis","structure":"credentialis, credentiale (adj., third declension)","meaning":"of trust, giving credit","meaningCN":"关于信任的；给予信用的"}],"derivatives":[{"word":"credentials","pos":"n.","zh":"资历证明；国书"},{"word":"credentialed","pos":"adj.","zh":"有资质的"},{"word":"credentialing","pos":"n.","zh":"资格认定"},{"word":"credit","pos":"n.","zh":"信用；学分"},{"word":"credible","pos":"adj.","zh":"可信的"}]}},{"word":"graduation","ipa_uk":"/ˌɡrædʒuˈeɪʃən/","ipa_us":"/ˌɡrædʒuˈeɪʃən/","definition_zh":"毕业；毕业典礼；刻度划分","definition_en":"the act or ceremony of completing a course of study, or the marking of a scale into regular degrees","core_image":"一顶学位帽放在折叠的证书旁，礼堂椅子排成整齐的方阵","scene":"礼堂里念到名字的人依次上台，接过证书后把帽穗拨到另一边。Her graduation was the first in the family.","sceneCN":"礼堂里被念到名字的人依次上台，接过证书后把帽穗拨到另一边；句中的 graduation 指「完成学业的毕业典礼」（第 2 个义项：授予学位的仪式）。图中可辨识物件：学位帽、证书、礼堂座椅、帽穗。","pos":[{"tag":"n.","zh":"毕业；毕业典礼；刻度划分"}],"collocations":[{"phrase":"graduation ceremony","zh":"毕业典礼"},{"phrase":"graduation rate","zh":"毕业率"},{"phrase":"graduation requirements","zh":"毕业要求"},{"phrase":"graduation thesis","zh":"毕业论文"},{"phrase":"graduation day","zh":"毕业日"},{"phrase":"graduation gown","zh":"毕业袍"}],"forms":[{"label":"复数","form":"graduations"},{"label":"动词","form":"graduate"},{"label":"形容词","form":"gradual"},{"label":"副词","form":"gradually"},{"label":"名词（刻度）","form":"gradation"}],"derivatives":[{"word":"graduate","pos":"n./v./adj.","zh":"毕业生；毕业；研究生的"},{"word":"gradual","pos":"adj.","zh":"逐渐的"},{"word":"gradually","pos":"adv.","zh":"逐渐地"},{"word":"gradation","pos":"n.","zh":"刻度；层次"},{"word":"undergraduate","pos":"n.","zh":"本科生"},{"word":"postgraduate","pos":"n./adj.","zh":"研究生；研究生的"}],"senses":[{"no":"01","title":"Completing a course of study","titleCN":"完成学业","definition":"the act of finishing a course or a degree and being formally recognised","definitionCN":"完成课程或学位并获得正式承认的行为","example":"Graduation from the programme takes two years.","exampleCN":"从这个项目毕业需要两年。","why":"the Latin verb meant 'to take a degree', built on gradus 'step', so finishing study is pictured as reaching the top step of a stair.","whyCN":"这个拉丁动词意为「取得学位」，由 gradus「台阶」构成，因此完成学业被想象成走到楼梯的最高一级。"},{"no":"02","title":"The ceremony itself","titleCN":"毕业典礼","definition":"the formal event at which degrees or diplomas are conferred","definitionCN":"正式授予学位或证书的仪式","example":"Her graduation was the first in the family.","exampleCN":"她的毕业典礼是家里第一次。","why":"the event sense grew from the act: once many people finish at once, the finishing needs a hall, a stage and a name read aloud.","whyCN":"仪式义由行为义生长而来：一旦许多人同时完成，这份完成就需要礼堂、舞台与被念出的名字。"},{"no":"03","title":"Marks on a measuring scale","titleCN":"量具上的刻度划分","definition":"the set of marks that divide a scale into measured intervals","definitionCN":"把量具分成等距区间的那些刻线","example":"The thermometer's graduation is etched in fine lines.","exampleCN":"这支温度计的刻度以细线蚀刻。","why":"the physical sense is the oldest literal one: a scale is divided into steps, and each step is a degree.","whyCN":"这个物理义是最早的字面义：量具被分成台阶，每一级就是一个度。"},{"no":"04","title":"A graduation rate","titleCN":"毕业率","definition":"the proportion of students who finish a programme within a stated time","definitionCN":"在规定时间内完成项目的学生比例","example":"The district reports a graduation rate above ninety percent.","exampleCN":"该学区报告的毕业率超过九成。","why":"statistics turned an event into a ratio, so the word now measures a system rather than a person.","whyCN":"统计学把事件变成比率，于是这个词衡量的是系统而非个人。"},{"no":"05","title":"Graduation requirements","titleCN":"毕业要求","definition":"the courses, credits and conditions a student must satisfy to finish","definitionCN":"学生完成学业必须满足的课程、学分与条件","example":"The new graduation requirements include a research project.","exampleCN":"新的毕业要求包含一个研究项目。","why":"requirements define the steps: if graduation is a stair, then each requirement is one tread that must be stood on.","whyCN":"要求把台阶定义清楚：若毕业是楼梯，那么每一项要求都是必须踩上的一级。"},{"no":"06","title":"The graduating class","titleCN":"毕业年级；当届毕业生","definition":"the group of students finishing in a given year, taken as a whole","definitionCN":"在某一年完成学业、被视作整体的那群学生","example":"The graduating class planted a tree by the gate.","exampleCN":"本届毕业生在门旁种了一棵树。","why":"the word attaches to a group as well as an act, because the people who finish together acquire a shared name.","whyCN":"这个词既可指行为也可指群体，因为一同完成的人获得了一个共同的名字。"},{"no":"07","title":"A gradual transition, in old use","titleCN":"旧义：逐渐的过渡","definition":"a passing from one state to another by small steps","definitionCN":"以细小步伐从一种状态转入另一种状态","example":"Old texts describe the graduation of dusk into dark.","exampleCN":"旧文献描写黄昏逐渐转入黑暗。","why":"the step image produced an older abstract sense: anything that changes by degrees undergoes a graduation.","whyCN":"台阶意象产生了一个更旧的抽象义：凡按度变化者都经历一次「graduation」。"},{"no":"08","title":"Calibrating an instrument","titleCN":"给仪器标定刻度","definition":"the act of marking an instrument into regular degrees for measurement","definitionCN":"把仪器划成规则度数以便测量的动作","example":"The technician finished the graduation of the new gauge.","exampleCN":"技师完成了新量规的刻度标定。","why":"the technical sense keeps the verb alive: to graduate a vessel is to give it steps that can be read.","whyCN":"技术义让动词用法保持活力：给容器「分度」，就是给它可读的台阶。"}],"etymology":{"intro":{"en":"Graduation comes from Latin graduatio, built on graduari 'to take a degree', from gradus 'step, degree'. The word entered English in the fifteenth century. Dates are approximate.","cn":"graduation 来自拉丁 graduatio，由 graduari「取得学位」构成，后者出自 gradus「台阶、度数」。这个词于十五世纪进入英语。年代为约数。"},"items":[{"era":"LATIN GRADUS","en":"Gradus meant 'step, stride, degree'. A stair and a scale share the word because both are measured in steps.","cn":"gradus 意为「台阶、步伐、度数」。楼梯与量具共享这个词，因为两者都以台阶计量。"},{"era":"LATIN GRADI","en":"Gradi meant 'to walk, to step'. The verb behind gradus pictures movement foot by foot.","cn":"gradi 意为「行走、迈步」，是 gradus 背后的动词，意象是一步一步地移动。"},{"era":"LATIN GRADUARI","en":"Graduari meant 'to take a degree, to be advanced step by step', used of students who had climbed the required steps.","cn":"graduari 意为「取得学位、逐级晋升」，用于那些已爬完所需台阶的学生。"},{"era":"LATIN GRADUATIO","en":"Graduatio named the act of conferring a degree, and the English noun kept that sense when it was borrowed.","cn":"graduatio 指授予学位的行为，英语借入时保留了这一意义。"},{"era":"CEREMONY AND SCALE","en":"By the eighteenth century the noun also named the ceremony, and the older measuring sense continued in instruments, where a scale is divided into graduations.","cn":"到十八世纪，这个名词也指仪式；更早的测量义则在仪器中延续，量具被分成一道道刻度。"},{"era":"SOURCE UNCERTAIN","en":"The deeper origin of gradus and gradi is uncertain; the usual link to a root meaning 'to step, go' is reconstructed. The spread from the degree sense to the scale sense is attested but not dated precisely.","cn":"gradus 与 gradi 的更早来源不确定；通常所说的、与表示「迈步、行走」的词根的联系属重构形式。「学位」义向「刻度」义的扩展有书证，但确切年代不明。"}]},"similar":{"note":{"en":"Group one holds the step-root family and the words that look closest; group two holds the events and documents that mark the same end of study.","cn":"第一组是「台阶」词根的词族与最形近的词；第二组是标记同一学业终点的仪式与文件。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"graduate","ipa":"/ˈɡrædʒuət/","tag":"the person or verb","definition":"The person who has finished, or the verb of finishing; graduation is the act or the ceremony.","definitionCN":"指已完成的人或完成的动作；graduation 是行为或仪式。"},{"word":"gradual","ipa":"/ˈɡrædʒuəl/","tag":"step by step","definition":"Moving by small degrees; it shares the step image but has nothing to do with finishing school.","definitionCN":"指按小度数变化；共享台阶意象，却与完成学业无关。"},{"word":"gradually","ipa":"/ˈɡrædʒuəli/","tag":"the adverb","definition":"In small steps, the adverb of gradual rather than of graduation.","definitionCN":"指以小步伐地，是 gradual 的副词而非 graduation 的。"},{"word":"gradation","ipa":"/ɡrəˈdeɪʃən/","tag":"a series of degrees","definition":"A series of stages or shades; closer to the scale sense than to the ceremony.","definitionCN":"指一连串阶段或层次；比仪式义更接近刻度义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"commencement","ipa":"/kəˈmensmənt/","tag":"the ceremony","definition":"The American name for the ceremony, literally a beginning, stressing the start rather than the finish.","definitionCN":"美式对毕业典礼的称呼，字面是「开始」，强调开端而非结束。"},{"word":"convocation","ipa":"/ˌkɒnvəˈkeɪʃən/","tag":"assembled body","definition":"A formal assembly, often for conferring degrees; it names the gathering, not the completion.","definitionCN":"指正式集会，常用于授学位；命名的是聚会而非完成。"},{"word":"certification","ipa":"/ˌsɜːtɪfɪˈkeɪʃən/","tag":"the paper proof","definition":"The act of certifying a qualification; graduation is the finishing, certification the documentation.","definitionCN":"指认证资格的行为；graduation 是完成，certification 是出具文件。"},{"word":"school-leaving","ipa":"/ˈskuːl ˈliːvɪŋ/","tag":"leaving school","definition":"British usage for finishing secondary school, without the ceremony or degree sense.","definitionCN":"英式说法，指读完中学，不含仪式或学位义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations here are the real step image, the real Latin verb for taking a degree, and the real modern statistics.","cn":"正常联想取自真实的台阶意象、真实的「取得学位」拉丁动词，以及真实的现代统计用法。"},"normal":[{"en":"gradus 'step': a degree is a step on a stair.","cn":"gradus「台阶」：一个学位就是楼梯上的一级。"},{"en":"graduari 'to take a degree': the student has climbed the required steps.","cn":"graduari「取得学位」：学生已爬完所需台阶。"},{"en":"The family runs graduate, gradual, gradually, gradation.","cn":"词族包括 graduate、gradual、gradually、gradation。"},{"en":"Fixed phrases mark the event: graduation ceremony, graduation day, graduation gown.","cn":"固定搭配标出事件：毕业典礼、毕业日、毕业袍。"},{"en":"The scale sense survives on instruments: a thermometer has graduations.","cn":"刻度义留在仪器上：温度计有一道道刻度。"}],"abstract":[{"en":"Picture a staircase whose top step is a stage with a name being read aloud.","cn":"想象一座楼梯，最高一级是舞台，上面正念出一个名字。"},{"en":"Picture a ruler and a diploma lying side by side, both divided into degrees.","cn":"想象一把尺与一张文凭并排放着，两者都被分成度数。"},{"en":"Picture a class planting a tree that will be taller than them next time.","cn":"想象一个班级种下一棵树，下次相见时它会比他们更高。"}]},"examples":[{"en":"Graduation requirements changed after the curriculum review.","cn":"课程复审后，毕业要求发生了变化。"},{"en":"The graduation rate rose for the third year running.","cn":"毕业率连续第三年上升。"},{"en":"He missed his sister's graduation because of the storm.","cn":"因为暴风雨，他错过了姐姐的毕业典礼。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「grad（台阶）」——一级一级走完，走到最高那级 → 毕业、毕业典礼","word":"graduation"},"root":"拉丁 gradus「台阶、度数」（源自 gradi「迈步」）→ graduari「取得学位」→ graduatio → 英语 graduation；gradus 与 gradi 的更早来源不确定，与「迈步」词根的联系属重构形式。","sensesIntro":{"en":"Eight senses climb one stair: study is finished step by step, the finishing becomes a ceremony, the steps become marks on a scale, then a rate, a set of requirements, a class, an older gradual change and a technical calibration.","cn":"八个义项爬同一座楼梯：学业被逐级完成，完成变成仪式，台阶随后变成量具上的刻度、毕业率、一组要求、一个班级、一种旧的渐变，以及技术上的标定。"},"semanticMap":{"core":{"en":"CORE IMAGE: a staircase whose top step is a stage, and whose treads are also etched on a measuring instrument.","cn":"核心意象：一座楼梯，最高一级是舞台，而它的各级踏步同时也蚀刻在一件量具上。"},"chain":["STEP","CLIMB","COMPLETION","CEREMONY","MEASURE","RATE"],"branches":[{"senses":"01 · 05","en":"THE CLIMB: finishing is reaching the top, and requirements are the treads that must be stood on.","cn":"攀爬：完成即登顶，要求则是必须踩上的踏步。"},{"senses":"02 · 06","en":"THE GATHERING: a ceremony and a class give the private climb a public shape.","cn":"聚集：仪式与班级给私人的攀爬一个公开的形状。"},{"senses":"03 · 08","en":"THE SCALE: a stair and a gauge are both divided into degrees, one for climbing and one for reading.","cn":"刻度：楼梯与量具都被分成度数，一个供攀爬，一个供读数。"},{"senses":"04","en":"THE RATIO: statistics turns a personal arrival into a system's percentage.","cn":"比率：统计学把个人的到达变成系统的百分比。"},{"senses":"07","en":"OLD GRADATION: anything that changes by small steps undergoes a graduation.","cn":"旧的渐变义：凡按小步变化者都经历一次「graduation」。"}]},"affixes":{"intro":{"en":"The word is a Latin root plus two suffixes, and the same pieces build the whole graduate family and the scale words beside it.","cn":"这个词由拉丁词根加两个后缀构成，同一批部件造出整个 graduate 词族及其旁边的刻度词。"},"latinIntro":{"en":"Gradus and gradi supply the step; graduari and graduatio supply the degree-taking; the English noun keeps both the ceremony and the scale.","cn":"gradus 与 gradi 提供「台阶」；graduari 与 graduatio 提供「取得学位」；英语名词同时保留仪式与刻度两义。"},"items":[{"word":"gradus","structure":"Latin noun, fourth declension","meaning":"step, degree","meaningCN":"台阶；度数","example":"Gradus is the shared root.","exampleCN":"gradus 是共享词根。"},{"word":"gradi","structure":"Latin verb, third conjugation","meaning":"to walk, step","meaningCN":"行走；迈步","example":"Gradi is the verb behind the noun.","exampleCN":"gradi 是名词背后的动词。"},{"word":"graduari","structure":"Latin deponent verb","meaning":"to take a degree","meaningCN":"取得学位","example":"Graduari names the climb's end.","exampleCN":"graduari 指攀爬的终点。"},{"word":"graduatio","structure":"graduari + -atio (action)","meaning":"the conferring of a degree","meaningCN":"授予学位的行为","example":"Graduatio became English graduation.","exampleCN":"graduatio 变成英语 graduation。"},{"word":"graduation","structure":"graduatio through French","meaning":"the act or ceremony","meaningCN":"行为或仪式","example":"The noun entered English in the fifteenth century.","exampleCN":"这个名词于十五世纪进入英语。"},{"word":"graduate","structure":"graduatus, past participle","meaning":"one who has taken a degree","meaningCN":"已取得学位的人","example":"The person and the verb share one form.","exampleCN":"人与动词共用一词形。"},{"word":"gradual","structure":"gradus + -alis (of)","meaning":"moving by steps","meaningCN":"按台阶移动的","example":"Gradual keeps the step image.","exampleCN":"gradual 保留台阶意象。"},{"word":"gradually","structure":"gradual + -ly (manner)","meaning":"step by step","meaningCN":"一步一步地","example":"Gradually is the adverb of gradual.","exampleCN":"gradually 是 gradual 的副词。"},{"word":"gradation","structure":"gradus + -ation (action)","meaning":"a series of degrees","meaningCN":"一串度数","example":"Gradation is close to the scale sense.","exampleCN":"gradation 接近刻度义。"}],"latinEntries":[{"word":"gradus","structure":"gradus, gradus (m., fourth declension)","meaning":"step, degree","meaningCN":"台阶；度数"},{"word":"gradi","structure":"gradi, gressus sum (verb, third conjugation)","meaning":"to walk, step","meaningCN":"行走；迈步"},{"word":"graduatio","structure":"graduatio, graduationis (f., third declension)","meaning":"a conferring of a degree","meaningCN":"授予学位"}],"derivatives":[{"word":"graduate","pos":"n./v./adj.","zh":"毕业生；毕业；研究生的"},{"word":"gradual","pos":"adj.","zh":"逐渐的"},{"word":"gradually","pos":"adv.","zh":"逐渐地"},{"word":"gradation","pos":"n.","zh":"刻度；层次"},{"word":"undergraduate","pos":"n.","zh":"本科生"}]}},{"word":"graduate","ipa_uk":"/ˈɡrædʒuət; ˈɡrædʒueɪt/","ipa_us":"/ˈɡrædʒuət; ˈɡrædʒueɪt/","definition_zh":"毕业生；毕业；把……分刻度；研究生的","definition_en":"a person who has completed a degree, or to complete one and move up to the next stage","core_image":"一位穿毕业袍的人把证书夹在臂下，另一只手提着一只标有刻度线的量筒","scene":"实验室里，新来的助理先量出准确体积，再把量筒放回架上。She graduated from the programme and now works in the same lab.","sceneCN":"新助理量出准确体积后把量筒放回架上，她刚从该项目毕业并留在这间实验室；句中的 graduate 指「完成学业取得学位」（第 2 个义项：读完课程并获授学位）。图中可辨识物件：毕业袍、证书、量筒刻度、实验台。","pos":[{"tag":"n.","zh":"毕业生；学位获得者"},{"tag":"v.","zh":"毕业；授予学位；分刻度；逐步过渡"},{"tag":"adj.","zh":"研究生的；毕业后的"}],"collocations":[{"phrase":"graduate from","zh":"从……毕业"},{"phrase":"graduate school","zh":"研究生院"},{"phrase":"college graduate","zh":"大学毕业生"},{"phrase":"graduate student","zh":"研究生"},{"phrase":"graduate degree","zh":"研究生学位"},{"phrase":"recent graduate","zh":"应届毕业生"}],"forms":[{"label":"名词复数","form":"graduates"},{"label":"动词三单","form":"graduates"},{"label":"动词过去式","form":"graduated"},{"label":"动词过去分词","form":"graduated"},{"label":"动词现在分词","form":"graduating"},{"label":"名词（毕业）","form":"graduation"}],"derivatives":[{"word":"graduation","pos":"n.","zh":"毕业；毕业典礼；刻度"},{"word":"gradual","pos":"adj.","zh":"逐渐的"},{"word":"gradually","pos":"adv.","zh":"逐渐地"},{"word":"undergraduate","pos":"n.","zh":"本科生"},{"word":"postgraduate","pos":"n./adj.","zh":"研究生；研究生的"},{"word":"gradation","pos":"n.","zh":"刻度；层次"}],"senses":[{"no":"01","title":"A person who holds a degree","titleCN":"持有学位的毕业生","definition":"someone who has completed a degree or a course of study","definitionCN":"已完成学位或一段学业的人","example":"The firm hires two graduates each spring.","exampleCN":"这家公司每年春天招聘两名毕业生。","why":"the Latin past participle graduatus named someone advanced step by step, and English kept it as the word for the finished student.","whyCN":"拉丁过去分词 graduatus 指逐级晋升的人，英语把它保留为「学业已完成者」的称呼。"},{"no":"02","title":"To complete a degree","titleCN":"完成学业取得学位","definition":"to finish a course of study and be formally awarded a degree","definitionCN":"读完一段学业并被正式授予学位","example":"She graduated from the programme and now works in the same lab.","exampleCN":"她从该项目毕业，如今在同一间实验室工作。","why":"the verb began as 'to take a degree' in Medieval Latin, so it names the moment of formal completion.","whyCN":"这个动词在中世纪拉丁语中本为「取得学位」，因此它命名的正是正式完成的那一刻。"},{"no":"03","title":"To move up a level","titleCN":"升到更高一档","definition":"to move from one stage or rank to a higher one","definitionCN":"从一个阶段或等级升到更高的一级","example":"The junior clerk graduated to head of section in four years.","exampleCN":"这位低级职员四年内升到科长。","why":"the step image survives outside school: any promotion or transfer upward can be called a graduation.","whyCN":"台阶意象在校外仍然存活：任何向上晋升或转入更高位置都可称为 graduate。"},{"no":"04","title":"Postgraduate, as an adjective","titleCN":"形容词：研究生的","definition":"describing study or a school that comes after a first degree","definitionCN":"描述取得首个学位之后的学业或院校","example":"He moved into graduate study after two years of teaching.","exampleCN":"教了两年书之后，他转入研究生学习。","why":"American usage fixed the adjective to the stage above the bachelor's degree, which is why graduate school names a place, not a person.","whyCN":"美式用法把这个形容词固定在学士之上的阶段，因此「研究生院」这类说法指的是一个地方而非一个人。"},{"no":"05","title":"To mark a scale in degrees","titleCN":"把量具划成刻度","definition":"to divide a vessel or instrument into regular measured marks","definitionCN":"把容器或仪器分成规则的测量刻线","example":"The glass was graduated in millilitres on one side.","exampleCN":"这只玻璃器皿一侧按毫升划了刻度。","why":"the oldest technical sense is physical: to graduate a vessel is to give it steps that can be read.","whyCN":"最早的技术义是物理性的：给容器「分度」就是给它可读的台阶。"},{"no":"06","title":"A secondary-school finisher","titleCN":"中学毕业生","definition":"in American usage, a person who has finished high school","definitionCN":"在美式用法中，指读完高中的人","example":"Half the town turned out for the high school graduates.","exampleCN":"半个镇子的人都出来为高中毕业生庆祝。","why":"American speech widened the noun downward to secondary school, so the word no longer guarantees a degree.","whyCN":"美式口语把名词向下扩展到中学，因此这个词不再保证持有学位。"},{"no":"07","title":"To pass through stages","titleCN":"逐步经过各阶段","definition":"to change by small steps from one condition to another","definitionCN":"以一种状态按小步转入另一种状态","example":"The colours graduate from pale yellow to deep orange.","exampleCN":"色彩从浅黄逐步过渡到深橙。","why":"the step sense turns abstract again here: a continuous change is read as a series of degrees.","whyCN":"台阶义在此再次抽象化：连续的变化被读成一串度数。"},{"no":"08","title":"A trained programme finisher","titleCN":"完成培训项目的结业者","definition":"a person who has completed a specified training programme, as in nursing","definitionCN":"完成某项特定培训项目的人，如护理专业","example":"The ward employs two nurse graduates from the new cohort.","exampleCN":"该病区雇用了新一批护理专业的结业者。","why":"training programmes use the noun for anyone who has finished their course, whether or not a degree is awarded.","whyCN":"培训项目用这个名词指任何完成课程的人，无论是否授予学位。"}],"etymology":{"intro":{"en":"Graduate comes from Latin graduatus, the past participle of graduari 'to take a degree', from gradus 'step'. The noun and the marking verb entered English by different routes in the fifteenth and seventeenth centuries. Dates are approximate.","cn":"graduate 来自拉丁 graduatus，即 graduari「取得学位」的过去分词，源于 gradus「台阶」。名词与「划刻度」的动词用法在十五与十七世纪经不同路径进入英语。年代为约数。"},"items":[{"era":"LATIN GRADUS","en":"Gradus meant 'step, stride, degree', the shared source of the stair and the scale.","cn":"gradus 意为「台阶、步伐、度数」，是楼梯与量具的共同来源。"},{"era":"LATIN GRADUARI","en":"Graduari meant 'to take a degree, to be advanced step by step'. It described the student who had climbed all the required steps.","cn":"graduari 意为「取得学位、逐级晋升」，描述已爬完所有必需台阶的学生。"},{"era":"GRADUATUS","en":"The past participle graduatus named the person who had been advanced, and it is the direct source of the English noun.","cn":"过去分词 graduatus 指已被晋升的人，是英语名词的直接来源。"},{"era":"ENGLISH NOUN","en":"English graduate appeared in the fifteenth century for a person holding a degree, and the university sense dominated for centuries.","cn":"英语 graduate 于十五世纪出现，指持有学位的人，此后数百年间以大学义为主。"},{"era":"MARKING SENSE","en":"In the seventeenth century the same form was used as a verb for dividing a vessel into degrees, which is why a graduated cylinder carries the word without any school.","cn":"十七世纪，同一词形被用作动词，指把容器分成度数，因此在「刻度量筒」这样的说法里，这个词与学校毫无关系。"},{"era":"SOURCE UNCERTAIN","en":"The deeper origin of gradus and gradi is uncertain; the link to a root meaning 'to step, go' is a reconstruction. The American widening of the noun to secondary school is recent and only loosely documented.","cn":"gradus 与 gradi 的更早来源不确定；与表示「迈步、行走」的词根的联系属重构形式。名词在美式用法中向中学扩展是晚近现象，记录亦不严密。"}]},"similar":{"note":{"en":"Group one holds the step-root family, including the two words most often confused with this one; group two holds the people and stages around finishing study.","cn":"第一组是「台阶」词根词族，包括最易与它混淆的两个词；第二组是围绕完成学业的人与阶段。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"graduation","ipa":"/ˌɡrædʒuˈeɪʃən/","tag":"the event","definition":"The act, the ceremony or the scale marks; graduate is the person or the verb.","definitionCN":"指行为、仪式或刻度；graduate 指人或动词。"},{"word":"gradual","ipa":"/ˈɡrædʒuəl/","tag":"by steps","definition":"Changing little by little; it describes pace, not the completion of study.","definitionCN":"指一点一点变化，描述节奏而非完成学业。"},{"word":"graduate school","ipa":"/ˈɡrædʒuət skuːl/","tag":"the place","definition":"The institution for study after a first degree; the adjective sense lives mainly in this and similar compounds.","definitionCN":"指取得首个学位后就读的院校；形容词义主要活在此类复合词中。"},{"word":"undergraduate","ipa":"/ˌʌndəˈɡrædʒuət/","tag":"the step below","definition":"A student who has not yet taken a first degree, the rung below the graduate.","definitionCN":"指尚未取得首个学位的学生，是 graduate 下面的一级。"}]},{"heading":"NEAR MEANING","entries":[{"word":"alumnus","ipa":"/əˈlʌmnəs/","tag":"former student","definition":"A former student of a particular school, whether or not recently graduated; it stresses loyalty to the institution.","definitionCN":"指某校的旧生，无论是否刚毕业；强调对院校的归属。"},{"word":"postgraduate","ipa":"/ˌpəʊstˈɡrædʒuət/","tag":"after the first degree","definition":"British usage for study after a bachelor's degree, close to the adjective sense of graduate.","definitionCN":"英式说法，指学士之后的学业，接近 graduate 的形容词义。"},{"word":"school-leaver","ipa":"/ˈskuːl ˈliːvə/","tag":"leaving school","definition":"A British term for someone finishing secondary school, with no implication of a degree.","definitionCN":"英式说法，指读完中学的人，不含学位之意。"},{"word":"bachelor","ipa":"/ˈbætʃələ/","tag":"the first degree","definition":"The holder of a first degree, a specific rank rather than a general finisher.","definitionCN":"指首个学位的持有者，是具体等级而非泛称的完成者。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations here are the real step root, the real double life of the word in schools and laboratories, and the real American usage.","cn":"正常联想取自真实的台阶词根、这个词在学校与实验室之间的真实双重身份，以及真实的美式用法。"},"normal":[{"en":"gradus 'step': a graduate has reached the top of the stair.","cn":"gradus「台阶」：graduate 已走到楼梯顶端。"},{"en":"Graduari 'to take a degree' gave the noun; to graduate a vessel gave the measuring verb.","cn":"graduari「取得学位」给出名词；给容器分度则给出测量的动词义。"},{"en":"The family runs graduation, gradual, gradually, undergraduate, postgraduate.","cn":"词族包括 graduation、gradual、gradually、undergraduate、postgraduate。"},{"en":"Fixed phrases mark the school sense: graduate from, graduate school, graduate student.","cn":"固定搭配标出学校义：从……毕业、研究生院、研究生。"},{"en":"The laboratory keeps the measuring sense: a graduated cylinder is read at the eye line.","cn":"实验室保留测量义：量筒的读数要与视线齐平。"}],"abstract":[{"en":"Picture a cap thrown into the air above a crowd of identical gowns.","cn":"想象一顶帽子被抛到一片相同毕业袍的上方。"},{"en":"Picture a glass tube ruled with fine lines, standing beside a diploma on the same bench.","cn":"想象一根划着细线的玻璃管，与一张文凭并排放在同一张台上。"},{"en":"Picture a staircase that continues past the stage and out of the building.","cn":"想象一座楼梯越过舞台，继续延伸到楼外。"}]},"examples":[{"en":"She graduated from a small college in the north.","cn":"她从北方一所小学院毕业。"},{"en":"The scheme hires recent graduates for two-year placements.","cn":"该计划雇用应届毕业生做两年岗位实习。"},{"en":"Every vessel in the cabinet is graduated in millilitres.","cn":"柜中每件器皿都按毫升划了刻度。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「grad（台阶）」——走完台阶的人毕业，给量具刻上台阶就是分度 → 毕业生、毕业、分刻度","word":"graduate"},"root":"拉丁 gradus「台阶、度数」（源自 gradi「迈步」）→ graduari「取得学位」→ 过去分词 graduatus → 英语 graduate；十七世纪同一词形又用作「给量具分度」。gradus 与 gradi 的更早来源不确定，与「迈步」词根的联系属重构形式。","sensesIntro":{"en":"Eight senses climb one stair and then leave the school: a person reaches the top, the reaching becomes a verb, an upward move, a postgraduate adjective, a scale on a glass vessel, a high-school finisher, a gradual change and a trained programme finisher.","cn":"八个义项先爬同一座楼梯，再走出校门：有人走到顶端，到达成为动词、向上的晋升、研究生的形容词、玻璃器皿上的刻度、中学结业者、渐变，以及完成培训项目的人。"},"semanticMap":{"core":{"en":"CORE IMAGE: a staircase that continues past the stage and out of the building, while a ruled glass tube stands on the same bench as a diploma.","cn":"核心意象：一座越过舞台、延伸出楼外的楼梯，而一根划着刻度的玻璃管与文凭并排放在同一张台上。"},"chain":["STEP","CLIMB","DEGREE","PROMOTION","SCALE","TRAINING"],"branches":[{"senses":"01 · 02","en":"THE PERSON AND THE ACT: the one at the top and the moment of arriving share one form.","cn":"人与动作：站在顶端的人与到达的那一刻共用同一词形。"},{"senses":"03 · 04","en":"THE NEXT STAGE: an upward move at work, and the adjective for study above a first degree.","cn":"下一阶段：职场上的向上晋升，以及首个学位之后学业的形容词。"},{"senses":"05 · 07","en":"THE RULED LINE: a vessel is divided into degrees, and continuous change is read as degrees too.","cn":"刻线：器皿被分成度数，连续变化也被读成度数。"},{"senses":"06","en":"THE WIDER NOUN: American speech lowers the word to secondary school, so a degree is no longer guaranteed.","cn":"更宽的名词：美式口语把词降到中学，学位不再是保证。"},{"senses":"08","en":"THE COURSE: any training programme can produce a graduate, degree or not.","cn":"课程：任何培训项目都能产出结业者，有没有学位都一样。"}]},"affixes":{"intro":{"en":"The word is a Latin root and participle ending, and the same pieces build the school family and the measuring words.","cn":"这个词由拉丁词根与分词词尾构成，同一批部件造出学校词族与测量类词。"},"latinIntro":{"en":"Gradus and gradi supply the step; graduari and its participle graduatus supply the person and the verb, while the same form was reused for marking a scale.","cn":"gradus 与 gradi 提供「台阶」；graduari 及其分词 graduatus 提供人与动词，而同一词形又被用于划刻度。"},"items":[{"word":"gradus","structure":"Latin noun, fourth declension","meaning":"step, degree","meaningCN":"台阶；度数","example":"Gradus is the shared root.","exampleCN":"gradus 是共享词根。"},{"word":"gradi","structure":"Latin verb, third conjugation","meaning":"to walk, step","meaningCN":"行走；迈步","example":"Gradi is the verb behind the noun.","exampleCN":"gradi 是名词背后的动词。"},{"word":"graduari","structure":"Latin deponent verb","meaning":"to take a degree","meaningCN":"取得学位","example":"Graduari names the climb's end.","exampleCN":"graduari 指攀爬的终点。"},{"word":"graduatus","structure":"past participle of graduari","meaning":"having taken a degree","meaningCN":"已取得学位的","example":"Graduatus is the direct source of the noun.","exampleCN":"graduatus 是名词的直接来源。"},{"word":"graduate","structure":"graduatus through Medieval Latin","meaning":"a degree holder; to finish a degree","meaningCN":"学位持有者；完成学位","example":"The noun and verb share one spelling.","exampleCN":"名词与动词共用一种拼写。"},{"word":"graduation","structure":"graduari + -ation (action)","meaning":"the act or ceremony","meaningCN":"行为或仪式","example":"Graduation names the event.","exampleCN":"graduation 命名这一事件。"},{"word":"gradual","structure":"gradus + -alis (of)","meaning":"by small steps","meaningCN":"按小步的","example":"Gradual describes the pace.","exampleCN":"gradual 描述节奏。"},{"word":"graduated","structure":"graduate + -ed (having)","meaning":"marked in degrees","meaningCN":"划有刻度的","example":"A graduated cylinder is read at eye level.","exampleCN":"量筒读数要与视线齐平。"},{"word":"undergraduate","structure":"under- + graduate","meaning":"a student below the first degree","meaningCN":"尚未取得首个学位的学生","example":"Undergraduate is the rung below.","exampleCN":"undergraduate 是下面的一级。"}],"latinEntries":[{"word":"gradus","structure":"gradus, gradus (m., fourth declension)","meaning":"step, degree","meaningCN":"台阶；度数"},{"word":"gradi","structure":"gradi, gressus sum (verb, third conjugation)","meaning":"to walk, step","meaningCN":"行走；迈步"},{"word":"graduatus","structure":"graduatus, graduata, graduatum (adj. and noun)","meaning":"having taken a degree","meaningCN":"已取得学位的"}],"derivatives":[{"word":"graduation","pos":"n.","zh":"毕业；毕业典礼；刻度"},{"word":"gradual","pos":"adj.","zh":"逐渐的"},{"word":"gradually","pos":"adv.","zh":"逐渐地"},{"word":"undergraduate","pos":"n.","zh":"本科生"},{"word":"postgraduate","pos":"n./adj.","zh":"研究生；研究生的"}]}}]);
